"""
This file contains all the classes present in the autosar schema.
It provides methods to access/modify/create elements from the autosar
arxml file.
"""

from __future__ import annotations

from lxml import etree
from enum import Enum, unique
import logging, os.path, sys
from typing import Type, Any
from .utils import datatype_utils
from .utils.XmlElementDirtyTracker import XmlElementDirtyTracker

# dict supposed to be used internally by the module to store the path and its corresponding autosar node
__pathsToNodeDict__ = {}
__autosarPathsToNodeDict__ = {}
__refBaseToArPackageDict__={}
# root autosar node
__autosarNode__ = None
# ElementDirtyTracker for xml nodes
XDT = XmlElementDirtyTracker()

# namespace for autosar arxml files
__autosarNsMap__ = {None: "http://autosar.org/schema/r4.0", 'xsi': "http://www.w3.org/2001/XMLSchema-instance"}
__rootSchemaAttr__ = {'{http://www.w3.org/2001/XMLSchema-instance}schemaLocation': 'http://autosar.org/schema/r4.0 AUTOSAR_00048.xsd'}


def read(files: list[str]=[]) -> tuple['AUTOSAR', bool]:
    """
    Reads the given files/files inside the folder and returns the AUTOSAR root.

    :param files: List of arxml file or folders containing arxml file
    :return: The merged AUTOSAR root node(the current file + all other
             files already loaded) and the status. May return None
             if the given file is not AUTOSAR compliant file or if
             it does not have any AR-PACKAGES.
    """
    global __autosarNode__
    status = True

    if isinstance(files, list) is False:
        raise InvalidInputException('argument files should be list of file')

    for file in files:
        if os.path.isdir(file):
            status &= __read_folder(file)
        else:
            status &= __read_file(file)
        if status is False:
            break

    # Resolve the references of all the nodes.
    if status is True:
        # Identify any reference bases
        referenceBases = get_all_instances(__autosarNode__, ReferenceBase)
        for r in referenceBases:
            r._resolve_references()
            if r.get_package() is not None:
                __refBaseToArPackageDict__[r.get_shortLabel()] = r.get_package()

        for node in __pathsToNodeDict__.values():
            node._resolve_references()
            # If the node has fragements, try to resolve it's references. This is done to ensure that any proxy nodes gets assigned to a real object later on.
            for fragment in (node._fragments or {}).values():
                if fragment is not node:
                    fragment._resolve_references()
    return __autosarNode__, status


def __read_folder(folder: str) -> bool:
    status = True
    for root, dirs, files in os.walk(folder):
        for file in files:
            if file.endswith(".arxml"):
                status &= __read_file(os.path.join(root, file))
            if status is False:
                break
    return status


def __read_file(file: str) -> bool:
    global __autosarNode__
    status = False
    tree = etree.parse(file, etree.XMLParser(huge_tree=True, remove_blank_text=True))

    if tree is not None and tree.getroot() is not None:
        if etree.QName(tree.getroot()).localname == 'AUTOSAR':
            status = True
            asrRootNode = AUTOSAR()._build(tree.getroot(), file)
            if len(asrRootNode.get_arPackages()) > 0:
                logging.info('{} read successfull.'.format(file))
                if __autosarNode__ is None:
                    __autosarNode__ = asrRootNode
                else:
                    for arpackage in asrRootNode.get_arPackages():
                        __merge_to_parent_node(arpackage, __autosarNode__)

                __autosarNode__._mergedFromNodes[file] = asrRootNode
            else:
                logging.warning('{} read but no ar-packages found. Hence ingoring the file contents.'.format(file))
        else:
            logging.error('{} read Failed. AUTOSAR root node not found in the arxml file.'.format(file))
    else:
        logging.error('{} read Failed. Seems like the file is not a valid arxml file.'.format(file))

    return status


def __merge_to_parent_node(node, parentNode):
    """
    Merges the child node to the parent node.
    """
    nodeWithSamePath = list(filter(lambda n: n == node, parentNode.get_children()))
    if nodeWithSamePath is None or len(nodeWithSamePath) == 0:
        parentNode.add_child(node, node._parent._containment_slot_of(node))
    else:
        existingNode = nodeWithSamePath[0]
        if existingNode.is_atp_splitable():
            # Track that `node`'s file now contributes directly to the existingNode.
            if existingNode._merged_files is None:
                existingNode._merged_files = {existingNode.file}
                existingNode._fragments = {existingNode.file: existingNode}

            existingNode._merged_files.add(node.file)
            existingNode._fragments[node.file] = node
            node._merge_target = existingNode

            # ignore if value variation points
            for child in list(filter(lambda n: not isinstance(n, (AttributeValueVariationPoint, MultilanguageLongName)), node.get_children())):
                __merge_to_parent_node(child, existingNode)
        elif isinstance(nodeWithSamePath[0], Identifiable):
            logging.warning('The node {} with short name {} is not splitable, but found in multiple files.'.format(nodeWithSamePath[0].__class__.__name__, nodeWithSamePath[0].name))


def new_file(path: str, defaultArPackage: str='RootPackage', overWrite: bool=False) -> 'ARPackage':
    """
    Creates a new file and return the ar-package node.
    Throws exception if the file already exist when the
    argument overWrite is not provided or is False.

    :param path: The absolute path where the file needs to be created.
    :param defaultArPackage: The name of the default ar-package.
    :param overWrite: Pass True if the new file should overwrite if
                      a file is already present in the given path.
    :return: The Ar-package.
    """
    global __autosarNode__
    if os.path.isfile(path) and overWrite is False:
        raise FileExistsError('File {} already exists. If it needs overwriting, then please set True for argument overWrite.'.format(path))

    # Create file
    root = etree.Element('AUTOSAR', nsmap=__autosarNsMap__, attrib=__rootSchemaAttr__)
    arpackages = etree.SubElement(root, 'AR-PACKAGES')
    arpackage = etree.SubElement(arpackages, 'AR-PACKAGE')
    shortName = etree.SubElement(arpackage, 'SHORT-NAME')
    shortName.text = defaultArPackage
    et = etree.ElementTree(root)
    et.write(path, pretty_print=True, xml_declaration=True,   encoding="utf-8")
    logging.info('File created successfully at {}.'.format(path))

    # Now create the Autosar object
    asrRootNode = AUTOSAR()._build(root, path)
    createdArPackage = next(iter(asrRootNode.get_arPackages()))
    if __autosarNode__ is None:
        __autosarNode__ = asrRootNode
    else:
        __merge_to_parent_node(createdArPackage, __autosarNode__) #Merging the new arpackage to the root node.

    __autosarNode__._mergedFromNodes[path] = asrRootNode
    return createdArPackage


def get_root() -> 'AUTOSAR':
    """
    Returns the root AUTOSAR node.
    """
    global __autosarNode__
    return __autosarNode__


def reinit() -> None:
    """
    Re-initialize the package. All the loaded model entities(from input
    /newly created files, modified/new model objects) will be removed.
    """
    global __autosarNode__
    __autosarNode__ = None # Reinit the root node.
    __pathsToNodeDict__.clear() # Clearing the cache
    __autosarPathsToNodeDict__.clear() # Clearing the cache
    __refBaseToArPackageDict__.clear() # Clearing the cache
    XDT.clear_dirty() # Clearing the dirty element tracing


def get_node(path) -> 'AutosarNode':
    """
    Returns the autosar node for the corresponding path.

    :param path: The fully qualified autosar path for eg: /Autosar/Swc1/port1.
    :return: The node corresponding to the path or None if the node for path is not available.
    """
    if path in __autosarPathsToNodeDict__:
        return __autosarPathsToNodeDict__[path]
    else:
        return None


def get_all_instances(node: 'AutosarNode', clazz) -> list['AutosarNode']:
    """
    Returns all the instances of the given class type by performing a deep search under the given node
    :param node: The node under which the type needs to be searched for.
    :param clazz: The python class type of the node to be searched for.
    """
    instances = []
    for child in node.get_children():
        if isinstance(child, clazz):
            instances.append(child)
        instances.extend(get_all_instances(child, clazz))
    return instances


def export_to_file(element: 'AutosarNode', path: str, overWrite: bool=False) -> None:
    """
    Export the element to the given file.
    :param element: the element which needs to be exported.
    :param path: the file path to which the element is exported.
    :param overWrite: Pass True if the new file should overwrite if
                  a file is already present in the given path.
    """
    if isinstance(element, CollectableElement):
        element.export_to_file(path, overWrite)
    else:
        raise Exception('Only elements of type CollectableElement can be exported(for eg: ARPackage, ApplicationSwComponentType, ISignal etc etc.)')


def save(files: list[str]=[]) -> None:
    """
    Saves the changes in AUTOSAR model.
    :param files: The files to be saved. If not provided
                  all the input files will be saved.
    """
    global __autosarNode__
    if __autosarNode__ is not None:
    	__autosarNode__.save(files)


def saveAs(file: str, overWrite: bool=False) -> None:
    """
    Saves the changes in AUTOSAR model(contents from input files, created files,
    new model entities, modified model entities) to a single file. This package
    do not validate if there exists AR-PACKAGE was duplicate names. It is the
    responsibility of the user to make sure this.

    :param file: The file where the complete AUTOSAR model will be saved.
    :param overWrite: Pass True if the new file should overwrite if
                      a file is already present in the given path.
    """
    global __autosarNode__
    __autosarNode__.saveAs(file, overWrite=overWrite)


def __str_to_class__(str):
    """
    To be used internally by the package.
    """
    return getattr(sys.modules[__name__], str)


class AutosarNode:
    """
    Base class for all autosar nodes
    """
    _uid_counter = 0 # unique sequence counter for any AutosarNode.

    def __init__(self):
        """
        Constructor for any Autosar node.
        """
        self._parent = None
        self._node = None
        self._name = None
        self.path = ''
        self.autosar_path = ''
        self.file = ''
        self._insert_after_tags = []
        self.referenced_by = set()
        self._merged_files = None   # None until a merge touches this node (lazy)
        self._fragments = None      # dict[str, AutosarNode]; populated only for merged splittable nodes
        self._merge_target = None   # the node this fragment was merged into (inverse of _fragments)
        AutosarNode._uid_counter += 1
        self._uid = AutosarNode._uid_counter

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        """
        Build the node
        :param parent: The parent under which new model element needs to be created.
        :param node: The xml node for which the autosar node needs to be created.
        """
        self._parent = parent
        self._node = node
        self.file = file
        shortNameNode = node.find('{*}SHORT-NAME')
        if shortNameNode is not None:
            self.name = shortNameNode.text

        self._build_path(elementNameIfShortNameMissing)
        return self

    @property
    def name(self):
        return self._name

    @name.setter
    def name(self, value):
        if value != self._name:
            self._name = value
            if self._parent is not None:
                self._refresh_paths()

    def _build_path(self, elementNameIfShortNameMissing = None):
        """
        Builds the path for the current node.
        """
        # First remove the current node from dict
        if self.path in __pathsToNodeDict__:
            del __pathsToNodeDict__[self.path]
        # Build the node and add to dict.
        if self.path not in __pathsToNodeDict__ and self._parent is not None:
            if self.name is not None:
                self.path = self._parent.path + '/' + self.name
                self.autosar_path = self._parent.autosar_path + '/' + self.name
                if self.autosar_path not in __autosarPathsToNodeDict__:
                    __autosarPathsToNodeDict__[self.autosar_path] = self
            elif elementNameIfShortNameMissing is not None:
                self.path = self._parent.path + '/' + elementNameIfShortNameMissing
                self.autosar_path = self._parent.autosar_path
            else:
                self.path = self._parent.path + '[' + self.__class__.__name__ + ']'
                self.autosar_path = self._parent.autosar_path

            if self.path not in __pathsToNodeDict__:
                __pathsToNodeDict__[self.path] = self
        else:
            self.path = ''


    @staticmethod
    def _add_or_get_xml_node(parentNode, tagName, dest = None, createNode = True, forceCreate = False, create_after_nodes = []):
        """
        Get or create a new xml node with the tagName.
        :param parentNode: Parent node under which the new tag needs to be created.
        :param tagName: The tag name which needs to be created.
        :param dest: The destination object if its a reference value.
        :param createNode: Create node is it doesn't exist.
        :param forceCreate: Create element forecefully even if it exists.
        :param create_after_nodes: The list of elements after which the element needs to be created.
        """
        xmlNode = parentNode.find('{*}' + tagName)
        if (xmlNode is None and createNode) or forceCreate:
            xmlNode = etree.Element(tagName, attrib = {'DEST' : dest.tag} if dest is not None else None)
            AutosarNode._insert_element_after_given_tags(parentNode, xmlNode, create_after_nodes = create_after_nodes)
        return xmlNode


    @staticmethod
    def _insert_element_after_given_tags(parentNode, xmlNode, create_after_nodes = []):
        """
        Inserts the element after given list of tags
        :param xmlNode: The node to be inserted
        :param create_after_nodes: The list nodes after which the element needs to be inserted
        """
        node_inserted = False
        for tag in create_after_nodes:
            nodes = parentNode.findall('{*}' + tag)
            if nodes is not None and len(nodes) > 0:
                parentNode.insert(parentNode.index(nodes[-1]) + 1, xmlNode)
                node_inserted = True
                break
        if node_inserted is False:
            # if not found already in the above list of nodes, it must be the first child element
            parentNode.insert(0, xmlNode)


    @staticmethod
    def _remove_xml_node_if_exists(parentNode, tagName):
        """
        Remove xml node with the tagName if it exists under the parentNode.
        :param parentNode: Parent node under which tagName element exists.
        :param tagName: The tag name to search for.
        """
        for xmlNode in parentNode.findall('{*}' + tagName):
            parentNode.remove(xmlNode)

    @staticmethod
    def _get_node_text(node, tagName):
        value = node.find('{*}' + tagName)
        if value is not None:
            return value.text
        return None

    @staticmethod
    def _export_element_to_file(element, path, overWrite=False):
        """
        Export the element to the given file.
        :param element: the element which needs to be exported.
        :param path: the file path to which the element is exported.
        :param overWrite: Pass True if the new file should overwrite if
                      a file is already present in the given path.
        """
        if os.path.isfile(path) and overWrite is False:
            raise FileExistsError('File {} already exists. If it needs overwriting, then please set True for argument overWrite.'.format(path))

        # Create file
        root = etree.Element('AUTOSAR', nsmap=__autosarNsMap__, attrib=__rootSchemaAttr__)
        arpackages = etree.SubElement(root, 'AR-PACKAGES')
        isPackageableElementToExport = isinstance(element, ARPackage)

        # Identify and add all packages
        packages = []
        AutosarNode.__identify_parentArPackages_until_root(element, packages)
        parentNode = arpackages

        for pack in packages:
            packNode = etree.SubElement(parentNode, 'AR-PACKAGE')
            shortName = etree.SubElement(packNode, 'SHORT-NAME')
            shortName.text = pack.name
            if pack == packages[-1] and isPackageableElementToExport:
                elementsNode = etree.SubElement(packNode, 'ELEMENTS')
                parentNode = elementsNode
            else:
                arPacksNode = etree.SubElement(packNode, 'AR-PACKAGES')
                parentNode = arPacksNode

        parentNode.append(element._node) # Add element
        et = etree.ElementTree(root)
        et.write(path, pretty_print=True, xml_declaration=True,   encoding="utf-8")
        logging.info('File exported successfully at {}.'.format(path))


    @staticmethod
    def __identify_parentArPackages_until_root(element, packages):
        if isinstance(element.get_parent(), ARPackage):
            AutosarNode.__identify_parentArPackages_until_root(element.get_parent(), packages)
            packages.append(element.get_parent())


    def get_parent(self) -> AutosarNode:
        return self._parent


    def get_children(self) -> AutosarNode:
        """
        Get all the child nodes of the current node. This method is supposed to be overridden by all sub-classes.
        """
        return []


    def get_property_values(self) -> dict[str, Any]:
        """
        Get the property and its value for a corresponding node as dict. This method is supposed to be overridden by all sub-classes.
        """
        return {'File' : repr(self.file)}

    def is_proxy(self) -> bool:
        """
        Return True if the node is proxy object
        """
        return False

    def _resolve_references(self):
        """
        This method is supposed to be overridden by all sub-classes.
        """
        pass


    def _refresh_paths(self):
        old_path = self.autosar_path
        if __autosarPathsToNodeDict__.get(old_path) is self:
            del __autosarPathsToNodeDict__[old_path]
        self._build_path()
        for referrer in list(self.referenced_by):
            XDT.mark_dirty(None, referrer)    # references to this node are saved with the new path
        for child in filter(None, self.get_children()):
            child._refresh_paths()

    def is_atp_splitable(self) -> bool:
        """
        This method is supposed to be overridden by the relevant sub-classes which is atp-splitable.
        """
        return False

    @property
    def contributing_files(self) -> set[str]:
        """
        Files whose content lives directly in this node (not recursively into
        children). For non-splittable or never-merged nodes this is just
        {self.file}. For a splittable node that received content merged in
        from other files, this is the full set, populated at merge time.
        """
        if self._merged_files is not None:
            return self._merged_files
        return {self.file}

    def get_fragment_files(self) -> list[str]:
        """
        Files this node has a presence in. Use with get_fragment() to target one.
        """
        return list(self.contributing_files)

    def get_fragment(self, file: str) -> 'AutosarNode | None':
        """
        Returns this node's own fragment object as it exists in `file`, so new
        content can be added specifically into that file's slice of a
        splittable node. Returns self if file == self.file, or None if this
        node has no presence in the given file.
        """
        if file == self.file:
            return self
        return self._fragments.get(file) if self._fragments is not None else None

    def add_child(self, child: AutosarNode, containment_slot: str) -> None:
        """
        This method is supposed to be overridden by all sub-classes.
        """
        pass

    def remove_child(self, child: AutosarNode, containment_slot: str) -> None:
        """
        This method is supposed to be overridden by all sub-classes.
        """
        pass

    def _containment_slot_of(self, child: AutosarNode) -> str | None:
        """
        Name of the containment slot of self that holds child, or None.
        Overridden by every class that has containment elements.
        """
        return None

    def _sync_add_to_merge_target(self, child: AutosarNode) -> None:
        """
        If the node is a fragment that was merged into a node, mirror a
        just-added child into the node's own collection too, so content
        is visible in the model.
        """
        if self._merge_target is not None:
            self._merge_target.add_child(child, child._parent._containment_slot_of(child))

    def _detach_from_parent(self) -> None:
        """
        Removes self from whichever containment slot its current parent holds it (eg:used when a node is moved).
        """
        parent = self._parent
        if parent is not None:
            XDT.mark_dirty(None, parent)
            slot = parent._containment_slot_of(self)
            parent.remove_child(self, slot)
            parent._sync_remove_from_merge_target(self, slot)

    def _sync_remove_from_merge_target(self, child: AutosarNode, containment_slot: str) -> None:
        """
        Bidirectional removal of the child node, since removal can be
        initiated from either side:
        - if self is a fragment, mirror the removal up into the node
        - if self IS the node and `child` actually belongs to a different
          file's fragment, mirror the removal down into that fragment too
       :param containment_slot: The containment dict from which the node needs to be removed.
        """
        if self._merge_target is not None:
            self._merge_target.remove_child(child, containment_slot)
        if self._fragments is not None and child.file != self.file:
            fragment = self._fragments.get(child.file)
            if fragment is not None and fragment is not self:
                fragment.remove_child(child, containment_slot)

    @staticmethod
    def _insert_at_index(ordered_dict, key, index):
        items = list(ordered_dict.keys())
        items.insert(index, key)
        ordered_dict.clear()
        for k in items:
            ordered_dict[k] = None

    def _read_xml_attribute(self, xml_attrib_name, converter):
        """
        Read the xml attribute with the given name from the node.
        :param xml_attrib_name: Attribute name.
        :param converter: The converter function(enumeration or one of the datatype_utils)
        """
        value = self._node.attrib.get(xml_attrib_name)
        return converter(value) if value is not None else None

    def _save_xml_attribute(self, xml_attrib_name, attr_name, text_value):
	    """
	    Saves a scalar field as an xml attribute on this node's own element.
	    :param xml_attrib_name: Attribute name.
	    :text_value: Value to be saved
	    """
	    if XDT.is_attribute_dirty(attr_name, self):
	        if text_value is not None:
	            self._node.attrib[xml_attrib_name] = text_value

    def _read_scalar_element(self, tag, converter):
        """
        Read the value of  element with the given tag from the node.
        :param tag: Element name.
        :param converter: The converter function(enumeration or one of the datatype_utils)
        """
        value = AutosarNode._get_node_text(self._node, tag)
        return converter(value) if value is not None else None

    def _save_scalar_element(self, tag_name, attr_name, text_value, create_after_nodes):
	    """
	    Saves a scalar (str/bool/enum) field as a child xml element with text_value.
	    :param tag_name: Element name.
        :text_value: Value to be saved
	    """
	    if XDT.is_attribute_dirty(attr_name, self):
	        if text_value is None:
	            AutosarNode._remove_xml_node_if_exists(self._node, tag_name)
	        else:
	            xml_node = AutosarNode._add_or_get_xml_node(self._node, tag_name, create_after_nodes=create_after_nodes)
	            xml_node.text = text_value

    def _read_own_text(self, converter):
        """
        Read the value of the contents of the node.
        :param converter: The converter function(enumeration or one of the datatype_utils)
        """
        return converter(self._node.text) if self._node.text is not None else None

    def _save_text_content(self, attr_name, text_value):
	    """
	    Scalar whose value is the element's own text (mixed content eg: IntegerValueVariationPoint).
	    """
	    if XDT.is_attribute_dirty(attr_name, self):
	        self._node.text = text_value

    @staticmethod
    def _resolve_child_type(child_type, xml_node):
        """
        Utility api to get the class name for the given tagName of the xml_node from the provided dict child_type.
        """
        if isinstance(child_type, dict):
            return __str_to_class__(child_type[etree.QName(xml_node).localname])
        return child_type

    def _build_child_node(self, xml_node, child_type, file, placeholder_name):
        """
        Build a child node of the given type under the parent xml_node.
        :param xml_node: parent xml element
        :param child_type: The child python class
        :placeholder_name: is only used when xml_node has no SHORT-NAME. Else, pass None
        """
        has_name = xml_node.find('{*}SHORT-NAME') is not None
        cls = AutosarNode._resolve_child_type(child_type, xml_node)
        return cls()._build(self, xml_node, file, None if has_name else placeholder_name)

    def _build_single_child(self, tag_name, child_type, file, role_name):
        """
        Build a child object of the given child_type class for the tag_name
        :param tag_name: The tag name for the child node
        :param child_type: The python class for which object needs to be created
        """
        xml_node = self._node.find(tag_name)
        if xml_node is None:
            return None
        return self._build_child_node(xml_node, child_type, file, '[{}_@]'.format(role_name))

    def _save_single_child(self, tag_name, value, create_after_nodes):
	    """
	    Saves a single child element, but only writes/recurses into it if it
	    belongs to this node's file (self.file). If value is None, removes
	    any existing xml node with tag_name.
	    :param value: the child node to be saved under the node.
	                  If None, removes any existing xml node with tag_name.
        :param create_after_nodes: The list nodes after which the element needs to
                                   be inserted
        :param tag_name: the tag to be created under the parent.
	    """
	    if value is not None:
	        if XDT.is_dirty(value) and value.file == self.file:
	            value._node.tag = tag_name
	            value._save_contents()
	            if self._node.find('{*}' + tag_name) is None:
	                AutosarNode._insert_element_after_given_tags(self._node, value._node, create_after_nodes=create_after_nodes)
	    else:
	        AutosarNode._remove_xml_node_if_exists(self._node, tag_name)

    def _build_child_collection(self, collection, tag_name, child_type, file, role_name, ref_counter):
        """
        Builds every child with the tag_name into `collection`; returns the updated placeholder counter.
        :param tag_name: The tag name for the child node
        :param child_type: The python class for which object needs to be created
        :param collection: The dict to which the object needs to be added
        """
        for xml_node in self._node.findall(tag_name):
            has_name = xml_node.find('{*}SHORT-NAME') is not None
            placeholder = None if has_name else '[{}_@{}]'.format(role_name, ref_counter)
            if not has_name:
                ref_counter += 1
            collection[self._build_child_node(xml_node, child_type, file, placeholder)] = None
        return ref_counter

    def _save_child_collection(self, wrapper_tag, item_tag, collection, create_after_nodes):
        """
        Saves an owned child collection, writing only members that belong to
        this node's file (self.file).
        :param collection: the child nodes to be saved under the node.
        :param create_after_nodes: The list nodes after which the element needs to
                                   be inserted
        :param wrapper_tag: wrapper tag where the child nodes shall be placed.
                            pass None, when items are placed directly as siblings to
                            the parent.
        :param item_tag: the tag to set on each item if its class doesn't already
                         carry a fixed tag (role element, no subtypes).
                         pass None when the child's own class tag is already
                         correct (has concrete subtypes).
        """
        if len(collection) == 0:
            return
        parent_node = AutosarNode._add_or_get_xml_node(self._node, wrapper_tag, create_after_nodes=create_after_nodes) if wrapper_tag is not None else None
        idx = 0
        for value in collection:
            if value.file == self.file:
                if XDT.is_dirty(value):
                    if item_tag is not None:
                        value._node.tag = item_tag
                    value._save_contents()
                if parent_node is not None:
                    parent_node.insert(idx, value._node)
                else:
                    AutosarNode._insert_element_after_given_tags(self._node, value._node, create_after_nodes = [item_tag] + create_after_nodes)
                idx += 1

    def _build_inline_child(self, child_type, file):
        """
        Child that shares this node's own xml element(EMF attribute
        groups attached directly to the parent's tag, not a separate child
        element) - no wrapper/tag management.
        """
        return child_type()._build(self, self._node, file)

    def _save_inline_child(self, value, create_after_nodes):
        """
        Saves a child that shares this node's own xml element.
        """
        if value is not None and XDT.is_dirty(value):
            value._insert_after_tags = create_after_nodes
            value._save_contents()

    def _build_wrapped_polymorphic_child(self, tag_to_type, file):
        """
        Builds an owned single child that has tag matching to the given tag_to_type.
        """
        for tag, type_name in tag_to_type:
            if self._node.find('{*}' + tag) is not None:
                return __str_to_class__(type_name)()._build(self, self._node, file)
        return None

    def _save_wrapped_polymorphic_child(self, wrapper_tag, value, create_after_nodes):
        """
        Saves an owned single child that has concrete subtypes - the child
        keeps its own tag (set by its class), wrapped inside wrapper_tag.
        """
        if value is not None:
            if XDT.is_dirty(value) and value.file == self.file:
                wrapper_node = AutosarNode._add_or_get_xml_node(self._node, wrapper_tag, create_after_nodes=create_after_nodes)
                value._save_contents()
                wrapper_node.append(value._node)
        else:
            AutosarNode._remove_xml_node_if_exists(self._node, wrapper_tag)

    @staticmethod
    def _reference_text(xml_node):
        """
        Full autosar path held by a *-REF element (BASE prefix applied), or None if there is no reference configured.
        """
        if xml_node.text is None:
            return None
        ref_text = ''
        ref_base = xml_node.attrib.get('BASE')
        if ref_base is not None and ref_base in __refBaseToArPackageDict__:
            ref_text = __refBaseToArPackageDict__[ref_base].path + '/'
        return ref_text + xml_node.text

    def _resolve_single_reference(self, tagName, current):
        """
        Resolves one reference element.
        :param tagName: tagName of the reference
        :param current: the current value of the reference node.
        """
        if current is not None:
            target = __autosarPathsToNodeDict__.get(current.path) if current.is_proxy() else None
            if target is not None:
                target.referenced_by.add(self)
            else:
                target = current
            return target
        else:
            xml_node = self._node.find(tagName)
            ref_text = AutosarNode._reference_text(xml_node) if xml_node is not None else None
            if ref_text is None:
                return None

            target = __autosarPathsToNodeDict__.get(ref_text)
            if target is None:
                target = UnresolvedRef(ref_text, xml_node.attrib.get('DEST'))
            else:
                target.referenced_by.add(self)
        return target

    def _resolve_reference_list(self, tagName, current):
        """
        Resolves every reference element with the given tagName and returns the resolved nodes.
        :param tagName: tagName of the reference
        :param current: the current value of the reference nodes.
        """
        refs = {}
        if (len(current) > 0):
            for k in current:
                target = __autosarPathsToNodeDict__.get(k.path) if k.is_proxy() else None
                if target is not None:
                    target.referenced_by.add(self)
                    refs[target] = None
                else:
                    refs[k] = None
        else:
            for xml_node in self._node.findall(tagName):
                ref_text = AutosarNode._reference_text(xml_node)
                if ref_text is None:
                    continue
                target = __autosarPathsToNodeDict__.get(ref_text)
                if target is not None:
                    target.referenced_by.add(self)
                    refs[target] = None
                else:
                    refs[UnresolvedRef(ref_text, xml_node.attrib.get('DEST'))] = None
        return refs

    def _save_single_reference(self, tag_name, ref_value, create_after_nodes):
	    """
	    Saves a single reference as a DEST-attributed xml element.
	    :param ref_value: The reference value to be set for the node.
	                      If None, removes the node.
        :param create_after_nodes: The list nodes after which the element needs to
                                   be inserted
        :param tag_name: the xml tag name for the reference.
	    """
	    if ref_value is None:
	        AutosarNode._remove_xml_node_if_exists(self._node, tag_name)
	    elif ref_value.is_proxy() is False and XDT.is_dirty(ref_value):
	        xml_node = AutosarNode._add_or_get_xml_node(self._node, tag_name, dest=ref_value, create_after_nodes=create_after_nodes)
	        xml_node.text = ref_value.autosar_path
	        xml_node.attrib['DEST'] = ref_value.tag

    def _save_reference_list(self, wrapper_tag, item_tag, ref_values, create_after_nodes):
        """
        Saves a list of references as DEST-attributed item elements, optionally
        inside a wrapper element.
        :param ref_values: the list of nodes to be referenced.
        :param create_after_nodes: The list nodes after which the element needs to
                                   be inserted
        :param wrapper_tag: wrapper tag where the referenced nodes shall be placed.
                            pass None, when items are placed directly as siblings to
                            the parent(no wrapper).
        :param item_tag: the xml tag name for the reference.
        """
        if wrapper_tag is not None:
            AutosarNode._remove_xml_node_if_exists(self._node, wrapper_tag)
            item_after = [item_tag]
        else:
            AutosarNode._remove_xml_node_if_exists(self._node, item_tag)
            item_after = [item_tag] + create_after_nodes

        ref_items = {}
        for ref in ref_values:
            if ref.is_proxy():
                ref_items[ref.path] = ref.dest
            else:
                ref_items[ref.autosar_path] =  ref.tag

        if len(ref_items) == 0:
            return

        parent_node = AutosarNode._add_or_get_xml_node(self._node, wrapper_tag, create_after_nodes=create_after_nodes) if wrapper_tag is not None else self._node
        for path, dest in ref_items.items():
            item_node = etree.Element(item_tag, attrib={'DEST': dest} if dest else None)
            item_node.text = path
            AutosarNode._insert_element_after_given_tags(parent_node, item_node, create_after_nodes=item_after)

    def get_unique_hash(self):
        """
        Gets the unique hash value for the object
        """
        return str(self._uid)

    def __repr__(self):
        return (self.__class__.__name__ + '(' + self.path + ')')

    def __hash__(self):
        return hash(self._uid)

    def __eq__(self, other):
        return (self.__class__ == other.__class__ and self.path == other.path)


class ARObject(AutosarNode):
    """
    Implicit base class of all classes in meta-model.
    """
    def __init__(self):
        super().__init__()
        self.__checksum = None
        self.__timestamp = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        self.__checksum = self._read_xml_attribute('S', datatype_utils.get_string_value)
        self.__timestamp = self._read_xml_attribute('T', datatype_utils.get_string_value)

        return self

    def get_checksum(self) -> str:
        return self.__checksum

    def set_checksum(self, value: str) -> None:
        self.__checksum = value
        XDT.mark_attribute_dirty('checksum', self)

    def get_timestamp(self) -> str:
        return self.__timestamp

    def set_timestamp(self, value: str) -> None:
        self.__timestamp = value
        XDT.mark_attribute_dirty('timestamp', self)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['Checksum'] = self.__checksum
        property_values['Timestamp'] = self.__timestamp
        return property_values


    def _save_ARObject(self):
        """
        Saves the content of ARObject node
        """
        self._save_xml_attribute('S', 'checksum', str(self.__checksum) if self.__checksum is not None else None)
        self._save_xml_attribute('T', 'timestamp', str(self.__timestamp) if self.__timestamp is not None else None)

class Referrable(ARObject):
    """
    Instances of this class can be referred to by their identifier (while adhering to namespace borders).
    """
    def __init__(self):
        super().__init__()
        self.__shortName = None
        self.__shortNameFragments = {}

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        self.__shortName = self._read_scalar_element('SHORT-NAME', datatype_utils.get_string_value)

        refCounter = 0
        refCounter = self._build_child_collection(self.__shortNameFragments, '{*}SHORT-NAME-FRAGMENTS/*', ShortNameFragment, file, 'shortNameFragments', refCounter)
        return self

    def get_shortName(self) -> str:
        return self.__shortName

    def set_shortName(self, value: str) -> None:
        self.__shortName = value
        self.name = value
        XDT.mark_attribute_dirty('shortName', self)

    def get_shortNameFragments(self) -> list[ShortNameFragment]:
        return list(self.__shortNameFragments.keys())

    def __bind_shortNameFragment(self, value: ShortNameFragment) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__shortNameFragments.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, ShortNameFragment) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of ShortNameFragment or its sub-classes'.format(value))

        value._detach_from_parent()
        value._parent = self #set parent
        value.file = self.file
        if value.name is not None:
            value._refresh_paths()
        else:
            value._build_path(elementNameIfShortNameMissing = 'ShortNameFragment_@' + str(len(self.get_children()))) #updates the path
        XDT.mark_dirty(value, self, attributesToMakeDirty = ['timestamp', 'checksum'])

    def add_shortNameFragment_at_index(self, index: int, value: ShortNameFragment) -> None:
        """
        Adds a single value to the shortNameFragments at the given index
        """
        if value is not None:
            self.__bind_shortNameFragment(value)
            AutosarNode._insert_at_index(self.__shortNameFragments, value, index)
            self._sync_add_to_merge_target(value)

    def add_shortNameFragment(self, value: ShortNameFragment) -> None:
        """
        Adds a single value to the shortNameFragments
        """
        if value is not None:
            self.__bind_shortNameFragment(value)
            self.__shortNameFragments[value] = None
            self._sync_add_to_merge_target(value)

    def set_shortNameFragments(self, values: list[ShortNameFragment]) -> None:
        """
        Adds a list of ref value to the shortNameFragments
        """
        for value in values:
            self.add_shortNameFragment(value)

    def remove_shortNameFragment(self, value: ShortNameFragment) -> None:
        """
        Removes a single value from shortNameFragments
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            value._detach_from_parent()
            value._parent = None #No parent
            value._refresh_paths() #resets the path
            if value._node.getparent() is not None:
                value._node.getparent().remove(value._node)

    def remove_shortNameFragments(self, values: list[ShortNameFragment]) -> None:
        """
        Removes a list of value from shortNameFragments
        """
        for value in values:
            self.remove_shortNameFragment(value)

    def new_ShortNameFragment(self, name: str=None) -> ShortNameFragment:
        """
        Creates a new ShortNameFragment under the Referrable.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        ShortNameFragment_obj = ShortNameFragment()
        if isinstance(ShortNameFragment_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        ShortNameFragment_obj.name = name if isinstance(ShortNameFragment_obj, Referrable) else None
        self.add_shortNameFragment(ShortNameFragment_obj)
        if isinstance(ShortNameFragment_obj, Referrable):
            ShortNameFragment_obj.set_shortName(name)
        return ShortNameFragment_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        children.extend(self.__shortNameFragments)
        return children

    def _containment_slot_of(self, child: AutosarNode) -> str | None:
        if child in self.__shortNameFragments:
            return 'shortNameFragments'
        return super()._containment_slot_of(child)

    def add_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'shortNameFragments':
            self.__shortNameFragments[child] = None
        else:
            super().add_child(child, containment_slot)

    def remove_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'shortNameFragments':
            self.__shortNameFragments.pop(child, None)
        else:
            super().remove_child(child, containment_slot)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['ShortName'] = self.__shortName
        return property_values


    def _save_Referrable(self):
        """
        Saves the content of Referrable node
        """
        super()._save_ARObject()
        self._save_scalar_element('SHORT-NAME', 'shortName', str(self.__shortName) if self.__shortName is not None else None, create_after_nodes = ['T', 'S'] + self._insert_after_tags)
        self._save_child_collection('SHORT-NAME-FRAGMENTS', None, self.__shortNameFragments, self._insert_after_tags + ['SHORT-NAME', 'T', 'S'])

class HwDescriptionEntity(Referrable):
    """
    This meta-class represents the ability to describe a hardware entity.
    """
    def __init__(self):
        super().__init__()
        self.__hwType = None
        self.__hwCategories = {}
        self.__hwAttributeValues = {}

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)

        refCounter = 0
        refCounter = self._build_child_collection(self.__hwAttributeValues, '{*}HW-ATTRIBUTE-VALUES/*', HwAttributeValue, file, 'hwAttributeValues', refCounter)
        return self

    def _resolve_references(self):
        super()._resolve_references()
        self.__hwType = self._resolve_single_reference('{*}HW-TYPE-REF', self.__hwType)
        self.__hwCategories = self._resolve_reference_list('{*}HW-CATEGORY-REFS/*', self.__hwCategories)

    def get_hwType(self) -> HwType:
        return self.__hwType

    def set_hwType(self, value: HwType) -> None:
        """
        Adds a single value to the hwType
        """
        if value is not None:
            if isinstance(value, HwType) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of HwType or its sub-classes'.format(value))
            if self.__hwType is not None and self.__hwType.is_proxy() is False:
                self.__hwType.referenced_by.remove(self)
            self.__hwType = value
            value.referenced_by.add(self)
        elif self.__hwType is not None:
            if self.__hwType.is_proxy() is False:
                self.__hwType.referenced_by.remove(self)
            self.__hwType = None
        XDT.mark_dirty(self.__hwType, self)

    def get_hwCategories(self) -> list[HwCategory]:
        return list(self.__hwCategories.keys())

    def __bind_hwCategorie(self, value: HwCategory) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__hwCategories.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, HwCategory) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of HwCategory or its sub-classes'.format(value))

        value.referenced_by.add(self)
        XDT.mark_dirty(value, self)


    def add_hwCategorie(self, value: HwCategory) -> None:
        """
        Adds a single value to the hwCategories
        """
        if value is not None:
            self.__bind_hwCategorie(value)
            self.__hwCategories[value] = None

    def set_hwCategories(self, values: list[HwCategory]) -> None:
        """
        Adds a list of ref value to the hwCategories
        """
        for value in values:
            self.add_hwCategorie(value)

    def remove_hwCategorie(self, value: HwCategory) -> None:
        """
        Removes a single value from hwCategories
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            self.__hwCategories.pop(value)
            if value.is_proxy() is False:
                value.referenced_by.remove(self)

    def remove_hwCategories(self, values: list[HwCategory]) -> None:
        """
        Removes a list of value from hwCategories
        """
        for value in values:
            self.remove_hwCategorie(value)

    def get_hwAttributeValues(self) -> list[HwAttributeValue]:
        return list(self.__hwAttributeValues.keys())

    def __bind_hwAttributeValue(self, value: HwAttributeValue) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__hwAttributeValues.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, HwAttributeValue) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of HwAttributeValue or its sub-classes'.format(value))

        value._detach_from_parent()
        value._parent = self #set parent
        value.file = self.file
        if value.name is not None:
            value._refresh_paths()
        else:
            value._build_path(elementNameIfShortNameMissing = 'HwAttributeValue_@' + str(len(self.get_children()))) #updates the path
        XDT.mark_dirty(value, self, attributesToMakeDirty = ['timestamp', 'checksum'])

    def add_hwAttributeValue_at_index(self, index: int, value: HwAttributeValue) -> None:
        """
        Adds a single value to the hwAttributeValues at the given index
        """
        if value is not None:
            self.__bind_hwAttributeValue(value)
            AutosarNode._insert_at_index(self.__hwAttributeValues, value, index)
            self._sync_add_to_merge_target(value)

    def add_hwAttributeValue(self, value: HwAttributeValue) -> None:
        """
        Adds a single value to the hwAttributeValues
        """
        if value is not None:
            self.__bind_hwAttributeValue(value)
            self.__hwAttributeValues[value] = None
            self._sync_add_to_merge_target(value)

    def set_hwAttributeValues(self, values: list[HwAttributeValue]) -> None:
        """
        Adds a list of ref value to the hwAttributeValues
        """
        for value in values:
            self.add_hwAttributeValue(value)

    def remove_hwAttributeValue(self, value: HwAttributeValue) -> None:
        """
        Removes a single value from hwAttributeValues
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            value._detach_from_parent()
            value._parent = None #No parent
            value._refresh_paths() #resets the path
            if value._node.getparent() is not None:
                value._node.getparent().remove(value._node)

    def remove_hwAttributeValues(self, values: list[HwAttributeValue]) -> None:
        """
        Removes a list of value from hwAttributeValues
        """
        for value in values:
            self.remove_hwAttributeValue(value)

    def new_HwAttributeValue(self, name: str=None) -> HwAttributeValue:
        """
        Creates a new HwAttributeValue under the HwDescriptionEntity.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        HwAttributeValue_obj = HwAttributeValue()
        if isinstance(HwAttributeValue_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        HwAttributeValue_obj.name = name if isinstance(HwAttributeValue_obj, Referrable) else None
        self.add_hwAttributeValue(HwAttributeValue_obj)
        if isinstance(HwAttributeValue_obj, Referrable):
            HwAttributeValue_obj.set_shortName(name)
        return HwAttributeValue_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        children.extend(self.__hwAttributeValues)
        return children

    def _containment_slot_of(self, child: AutosarNode) -> str | None:
        if child in self.__hwAttributeValues:
            return 'hwAttributeValues'
        return super()._containment_slot_of(child)

    def add_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'hwAttributeValues':
            self.__hwAttributeValues[child] = None
        else:
            super().add_child(child, containment_slot)

    def remove_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'hwAttributeValues':
            self.__hwAttributeValues.pop(child, None)
        else:
            super().remove_child(child, containment_slot)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['HwType'] = self.__hwType
        property_values['HwCategories'] = self.__hwCategories
        return property_values


    def _save_HwDescriptionEntity(self):
        """
        Saves the content of HwDescriptionEntity node
        """
        super()._save_Referrable()
        self._save_single_reference('HW-TYPE-REF', self.__hwType, self._insert_after_tags + ['SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])
        self._save_reference_list('HW-CATEGORY-REFS', 'HW-CATEGORY-REF', self.__hwCategories, self._insert_after_tags + ['HW-TYPE-REF', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])
        self._save_child_collection('HW-ATTRIBUTE-VALUES', None, self.__hwAttributeValues, self._insert_after_tags + ['HW-CATEGORY-REFS', 'HW-TYPE-REF', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])

class Describable(ARObject):
    """
    This meta-class represents the ability to add a descriptive documentation to non identifiable elements.
    """
    def __init__(self):
        super().__init__()
        self.__category = None
        self.__desc = None
        self.__introduction = None
        self.__adminData = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
