class EnumerationMappingTable(PackageableElement):
    """
    This class represents an attribute value variation point for Enumeration attributes., , Note that this class might be used in the extended meta-model only.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'ENUMERATION-MAPPING-TABLE'
        self._node = etree.Element('ENUMERATION-MAPPING-TABLE')
        self.__entries = {}

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)

        refCounter = 0
        refCounter = self._build_child_collection(self.__entries, '{*}ENTRYS/*', EnumerationMappingEntry, file, 'entries', refCounter)
        return self

    def get_entries(self) -> list[EnumerationMappingEntry]:
        return list(self.__entries.keys())

    def __bind_entrie(self, value: EnumerationMappingEntry) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__entries.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, EnumerationMappingEntry) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of EnumerationMappingEntry or its sub-classes'.format(value))

        value._detach_from_parent()
        value._parent = self #set parent
        value.file = self.file
        if value.name is not None:
            value._refresh_paths()
        else:
            value._build_path(elementNameIfShortNameMissing = 'EnumerationMappingEntry_@' + str(len(self.get_children()))) #updates the path
        XDT.mark_dirty(value, self, attributesToMakeDirty = ['timestamp', 'checksum'])

    def add_entrie_at_index(self, index: int, value: EnumerationMappingEntry) -> None:
        """
        Adds a single value to the entries at the given index
        """
        if value is not None:
            self.__bind_entrie(value)
            AutosarNode._insert_at_index(self.__entries, value, index)
            self._sync_add_to_merge_target(value)

    def add_entrie(self, value: EnumerationMappingEntry) -> None:
        """
        Adds a single value to the entries
        """
        if value is not None:
            self.__bind_entrie(value)
            self.__entries[value] = None
            self._sync_add_to_merge_target(value)

    def set_entries(self, values: list[EnumerationMappingEntry]) -> None:
        """
        Adds a list of ref value to the entries
        """
        for value in values:
            self.add_entrie(value)

    def remove_entrie(self, value: EnumerationMappingEntry) -> None:
        """
        Removes a single value from entries
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            value._detach_from_parent()
            value._parent = None #No parent
            value._refresh_paths() #resets the path
            if value._node.getparent() is not None:
                value._node.getparent().remove(value._node)

    def remove_entries(self, values: list[EnumerationMappingEntry]) -> None:
        """
        Removes a list of value from entries
        """
        for value in values:
            self.remove_entrie(value)

    def new_Entrie(self, name: str=None) -> EnumerationMappingEntry:
        """
        Creates a new EnumerationMappingEntry under the EnumerationMappingTable.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        EnumerationMappingEntry_obj = EnumerationMappingEntry()
        if isinstance(EnumerationMappingEntry_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        EnumerationMappingEntry_obj.name = name if isinstance(EnumerationMappingEntry_obj, Referrable) else None
        self.add_entrie(EnumerationMappingEntry_obj)
        if isinstance(EnumerationMappingEntry_obj, Referrable):
            EnumerationMappingEntry_obj.set_shortName(name)
        return EnumerationMappingEntry_obj

