class AclObjectSet(ARElement,AtpBlueprint,AtpBlueprintable):
    """
    This meta class represents the ability to denote a set of objects for which roles and rights (access control lists) shall be defined. It basically can define the objects based on, , * the nature of objects, * the involved blueprints, * the artifact in which the objects are serialized, * the definition of the object (in a definition - value pattern), * individual reference objects
    """
    def __init__(self):
        super().__init__()
        self.tag = 'ACL-OBJECT-SET'
        self._node = etree.Element('ACL-OBJECT-SET')
        self.__aclObjectClass = None
        self.__aclScope = None
        self.__collection = None
        self.__derivedFromBlueprints = {}
        self.__engineeringObjects = {}
        self.__objectDefinitions = {}
        self.__objectDefintions = {}
        self.__objects = {}

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        self.__aclObjectClass = self._read_scalar_element('ACL-OBJECT-CLASS', datatype_utils.get_string_value)
        self.__aclScope = self._read_scalar_element('ACL-SCOPE', AclScopeEnum.get)

        refCounter = 0
        refCounter = self._build_child_collection(self.__engineeringObjects, '{*}ENGINEERING-OBJECTS/*', AutosarEngineeringObject, file, 'engineeringObjects', refCounter)
        return self

    def _resolve_references(self):
        super()._resolve_references()
        self.__collection = self._resolve_single_reference('{*}COLLECTION-REF', self.__collection)
        self.__derivedFromBlueprints = self._resolve_reference_list('{*}DERIVED-FROM-BLUEPRINT-REFS/*', self.__derivedFromBlueprints)
        self.__objectDefinitions = self._resolve_reference_list('{*}OBJECT-DEFINITION-REFS/*', self.__objectDefinitions)
        self.__objectDefintions = self._resolve_reference_list('{*}OBJECT-DEFINTION-REFS/*', self.__objectDefintions)
        self.__objects = self._resolve_reference_list('{*}OBJECT-REFS/*', self.__objects)

