    def _save_contents(self):
        """
        Saves the content of StructuredReq node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_Identifiable()
        super()._save_Paginateable()
        super()._save_Traceable()
        self._save_scalar_element('DATE', 'date', str(self.__date) if self.__date is not None else None, create_after_nodes = ['TRACE-REFS', 'KEEP-WITH-PREVIOUS', 'BREAK', 'VIEW', 'SI', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'] + self._insert_after_tags)
