        self._save_scalar_element('TYPE', 'type', str(self.__type) if self.__type is not None else None, create_after_nodes = ['ISSUED-BY', 'DATE', 'TRACE-REFS', 'KEEP-WITH-PREVIOUS', 'BREAK', 'VIEW', 'SI', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'] + self._insert_after_tags)
        self._save_scalar_element('IMPORTANCE', 'importance', str(self.__importance) if self.__importance is not None else None, create_after_nodes = ['TYPE', 'ISSUED-BY', 'DATE', 'TRACE-REFS', 'KEEP-WITH-PREVIOUS', 'BREAK', 'VIEW', 'SI', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'] + self._insert_after_tags)
        self._save_single_child('DESCRIPTION', self.__description, self._insert_after_tags + ['IMPORTANCE', 'TYPE', 'ISSUED-BY', 'DATE', 'TRACE-REFS', 'KEEP-WITH-PREVIOUS', 'BREAK', 'VIEW', 'SI', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])
