class Row(Paginateable):
    """
    This meta-class represents the ability to express one row in a table.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'ROW'
        self._node = etree.Element('ROW')
        self.__rowsep = None
        self.__valign = None
        self.__entries = {}
        self.__variationPoint = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        self.__rowsep = self._read_xml_attribute('ROWSEP', datatype_utils.get_string_value)
        self.__valign = self._read_xml_attribute('VALIGN', ValignEnum.get)

        refCounter = 0
        refCounter = self._build_child_collection(self.__entries, '{*}ENTRY', Entry, file, 'entries', refCounter)
        self.__variationPoint = self._build_single_child('{*}VARIATION-POINT', VariationPoint, file, 'variationPoint')
        return self

    def get_rowsep(self) -> str:
        return self.__rowsep

    def set_rowsep(self, value: str) -> None:
        self.__rowsep = value
        XDT.mark_attribute_dirty('rowsep', self)

    def get_valign(self) -> ValignEnum:
        return self.__valign

    def set_valign(self, value: ValignEnum) -> None:
        self.__valign = value
        XDT.mark_attribute_dirty('valign', self)

    def get_entries(self) -> list[Entry]:
        return list(self.__entries.keys())

    def __bind_entrie(self, value: Entry) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__entries.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, Entry) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of Entry or its sub-classes'.format(value))

        value._detach_from_parent()
        value._parent = self #set parent
        value.file = self.file
        if value.name is not None:
            value._refresh_paths()
        else:
            value._build_path(elementNameIfShortNameMissing = 'Entry_@' + str(len(self.get_children()))) #updates the path
        XDT.mark_dirty(value, self, attributesToMakeDirty = ['timestamp', 'checksum'])

    def add_entrie_at_index(self, index: int, value: Entry) -> None:
        """
        Adds a single value to the entries at the given index
        """
        if value is not None:
            self.__bind_entrie(value)
            AutosarNode._insert_at_index(self.__entries, value, index)
            self._sync_add_to_merge_target(value)

    def add_entrie(self, value: Entry) -> None:
        """
        Adds a single value to the entries
        """
        if value is not None:
            self.__bind_entrie(value)
            self.__entries[value] = None
            self._sync_add_to_merge_target(value)

    def set_entries(self, values: list[Entry]) -> None:
        """
        Adds a list of ref value to the entries
        """
        for value in values:
            self.add_entrie(value)

    def remove_entrie(self, value: Entry) -> None:
        """
        Removes a single value from entries
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            value._detach_from_parent()
            value._parent = None #No parent
            value._refresh_paths() #resets the path
            if value._node.getparent() is not None:
                value._node.getparent().remove(value._node)

    def remove_entries(self, values: list[Entry]) -> None:
        """
        Removes a list of value from entries
        """
        for value in values:
            self.remove_entrie(value)

    def get_variationPoint(self) -> VariationPoint:
        return self.__variationPoint

    def set_variationPoint(self, value: VariationPoint) -> None:
        """
        Adds a single value to the variationPoint
        """
        if value is not None:
            if isinstance(value, VariationPoint) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of VariationPoint or its sub-classes'.format(value))

            value._detach_from_parent()
            self.__variationPoint = value
            value.file = self.file
            value._parent = self #set parent
            if value.name is not None:
                value._refresh_paths()
            else:
                value._build_path(elementNameIfShortNameMissing = 'VariationPoint_@' + str(len(self.get_children()))) #updates the path
            self._sync_add_to_merge_target(value)
        elif self.__variationPoint is not None:
            self.__variationPoint._detach_from_parent()
            self.__variationPoint = None
        XDT.mark_dirty(self.__variationPoint, self)

    def new_VariationPoint(self, name: str=None) -> VariationPoint:
        """
        Creates a new VariationPoint under the Row.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        VariationPoint_obj = VariationPoint()
        if isinstance(VariationPoint_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        VariationPoint_obj.name = name if isinstance(VariationPoint_obj, Referrable) else None
        self.set_variationPoint(VariationPoint_obj)
        if isinstance(VariationPoint_obj, Referrable):
            VariationPoint_obj.set_shortName(name)
        return VariationPoint_obj

    def new_Entrie(self, name: str=None) -> Entry:
        """
        Creates a new Entry under the Row.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        Entry_obj = Entry()
        if isinstance(Entry_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        Entry_obj.name = name if isinstance(Entry_obj, Referrable) else None
        self.add_entrie(Entry_obj)
        if isinstance(Entry_obj, Referrable):
            Entry_obj.set_shortName(name)
        return Entry_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        children.extend(self.__entries)
        if self.__variationPoint is not None:
            children.append(self.__variationPoint)
        return children

    def _containment_slot_of(self, child: AutosarNode) -> str | None:
        if child in self.__entries:
            return 'entries'
        if self.__variationPoint is child:
            return 'variationPoint'
        return super()._containment_slot_of(child)

    def add_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'entries':
            self.__entries[child] = None
        elif containment_slot == 'variationPoint':
            if self.__variationPoint is None:
                self.__variationPoint = child
        else:
            super().add_child(child, containment_slot)

    def remove_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'entries':
            self.__entries.pop(child, None)
        elif containment_slot == 'variationPoint':
            if self.__variationPoint is child:
                self.__variationPoint = None
        else:
            super().remove_child(child, containment_slot)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['Rowsep'] = self.__rowsep
        property_values['Valign'] = self.__valign
        return property_values


    def _save_contents(self):
        """
        Saves the content of Row node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_Paginateable()
        self._save_xml_attribute('ROWSEP', 'rowsep', str(self.__rowsep) if self.__rowsep is not None else None)
        self._save_xml_attribute('VALIGN', 'valign', self.__valign.literal if self.__valign is not None else None)
        self._save_child_collection(None, 'ENTRY', self.__entries, self._insert_after_tags + ['KEEP-WITH-PREVIOUS', 'BREAK', 'VIEW', 'SI', 'T', 'S'])
        self._save_single_child('VARIATION-POINT', self.__variationPoint, self._insert_after_tags + ['ENTRY', 'KEEP-WITH-PREVIOUS', 'BREAK', 'VIEW', 'SI', 'T', 'S'])

