        self._save_single_child('VERBATIM', self.__verbatim, self._insert_after_tags + ['L-GRAPHIC', 'FORMULA-CAPTION', 'KEEP-WITH-PREVIOUS', 'BREAK', 'VIEW', 'SI', 'T', 'S'])
