        self._save_child_collection(None, 'STRUCTURED-REQ', self.__structuredReqs, self._insert_after_tags + ['P', 'NOTE', 'MSR-QUERY-P-2', 'LIST', 'LABELED-LIST', 'FORMULA', 'FIGURE', 'DEF-LIST', 'T', 'S'])
