class EmphasisText(ARObject):
    """
    This is an emphasized text. As a compromise it contains some rendering oriented attributes such as color and font.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'EMPHASIS-TEXT'
        self._node = etree.Element('EMPHASIS-TEXT')
        self.__color = None
        self.__font = None
        self.__subs = None
        self.__sups = None
        self.__type = None
        self.__tts = {}

        self.__mixedtext = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        self.__color = self._read_xml_attribute('COLOR', datatype_utils.get_string_value)
        self.__font = self._read_xml_attribute('FONT', EEnumFont.get)
        self.__subs = self._read_scalar_element('SUB', datatype_utils.get_string_value)
        self.__sups = self._read_scalar_element('SUP', datatype_utils.get_string_value)
        self.__type = self._read_xml_attribute('TYPE', EEnum.get)

        refCounter = 0
        refCounter = self._build_child_collection(self.__tts, '{*}TT', Tt, file, 'tts', refCounter)
        self.__mixedtext = node.text
        return self

    def get_color(self) -> str:
        return self.__color

    def set_color(self, value: str) -> None:
        self.__color = value
        XDT.mark_attribute_dirty('color', self)

    def get_font(self) -> EEnumFont:
        return self.__font

    def set_font(self, value: EEnumFont) -> None:
        self.__font = value
        XDT.mark_attribute_dirty('font', self)

    def get_subs(self) -> str:
        return self.__subs

    def set_subs(self, value: str) -> None:
        self.__subs = value
        XDT.mark_attribute_dirty('subs', self)

    def get_sups(self) -> str:
        return self.__sups

    def set_sups(self, value: str) -> None:
        self.__sups = value
        XDT.mark_attribute_dirty('sups', self)

    def get_type(self) -> EEnum:
        return self.__type

    def set_type(self, value: EEnum) -> None:
        self.__type = value
        XDT.mark_attribute_dirty('type', self)

    def get_tts(self) -> list[Tt]:
        return list(self.__tts.keys())

    def __bind_tt(self, value: Tt) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__tts.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, Tt) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of Tt or its sub-classes'.format(value))

        value._detach_from_parent()
        value._parent = self #set parent
        value.file = self.file
        if value.name is not None:
            value._refresh_paths()
        else:
            value._build_path(elementNameIfShortNameMissing = 'Tt_@' + str(len(self.get_children()))) #updates the path
        XDT.mark_dirty(value, self, attributesToMakeDirty = ['timestamp', 'checksum'])

    def add_tt_at_index(self, index: int, value: Tt) -> None:
        """
        Adds a single value to the tts at the given index
        """
        if value is not None:
            self.__bind_tt(value)
            AutosarNode._insert_at_index(self.__tts, value, index)
            self._sync_add_to_merge_target(value)

    def add_tt(self, value: Tt) -> None:
        """
        Adds a single value to the tts
        """
        if value is not None:
            self.__bind_tt(value)
            self.__tts[value] = None
            self._sync_add_to_merge_target(value)

    def set_tts(self, values: list[Tt]) -> None:
        """
        Adds a list of ref value to the tts
        """
        for value in values:
            self.add_tt(value)

    def remove_tt(self, value: Tt) -> None:
        """
        Removes a single value from tts
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            value._detach_from_parent()
            value._parent = None #No parent
            value._refresh_paths() #resets the path
            if value._node.getparent() is not None:
                value._node.getparent().remove(value._node)

    def remove_tts(self, values: list[Tt]) -> None:
        """
        Removes a list of value from tts
        """
        for value in values:
            self.remove_tt(value)

    def new_Tt(self, name: str=None) -> Tt:
        """
        Creates a new Tt under the EmphasisText.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        Tt_obj = Tt()
        if isinstance(Tt_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        Tt_obj.name = name if isinstance(Tt_obj, Referrable) else None
        self.add_tt(Tt_obj)
        if isinstance(Tt_obj, Referrable):
            Tt_obj.set_shortName(name)
        return Tt_obj

    def get(self) -> str:
        return self.__mixedtext

    def set(self, text: str) -> None:
        self.__mixedtext = text
        if text is not None:
            self._node.text = str(text)
        else:
            self._node.text = ''
        XDT.mark_attribute_dirty('mixedtext', self)

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        children.extend(self.__tts)
        return children

    def _containment_slot_of(self, child: AutosarNode) -> str | None:
        if child in self.__tts:
            return 'tts'
        return super()._containment_slot_of(child)

    def add_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'tts':
            self.__tts[child] = None
        else:
            super().add_child(child, containment_slot)

    def remove_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'tts':
            self.__tts.pop(child, None)
        else:
            super().remove_child(child, containment_slot)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['Color'] = self.__color
        property_values['Font'] = self.__font
        property_values['Subs'] = self.__subs
        property_values['Sups'] = self.__sups
