class AnyInstanceRef(AtpInstanceRef):
    """
    Describes a reference to any instance in an AUTOSAR model. This is the most generic form of an instance ref. Refer to the superclass notes for more details.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'ANY-INSTANCE-REF-IREF'
        self._node = etree.Element('ANY-INSTANCE-REF-IREF')
        self.__contextElements = {}
        self.__target = None
        self.__variationPoint = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)

        self.__variationPoint = self._build_single_child('{*}VARIATION-POINT', VariationPoint, file, 'variationPoint')
        return self

    def _resolve_references(self):
        super()._resolve_references()
        self.__contextElements = self._resolve_reference_list('{*}CONTEXT-ELEMENT-REF', self.__contextElements)
        self.__target = self._resolve_single_reference('{*}TARGET-REF', self.__target)

    def get_contextElements(self) -> list[AtpFeature]:
        return list(self.__contextElements.keys())

    def __bind_contextElement(self, value: AtpFeature) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__contextElements.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, AtpFeature) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of AtpFeature or its sub-classes'.format(value))

        value.referenced_by.add(self)
        XDT.mark_dirty(value, self)


    def add_contextElement(self, value: AtpFeature) -> None:
        """
        Adds a single value to the contextElements
        """
        if value is not None:
            self.__bind_contextElement(value)
            self.__contextElements[value] = None

    def set_contextElements(self, values: list[AtpFeature]) -> None:
        """
        Adds a list of ref value to the contextElements
        """
        for value in values:
            self.add_contextElement(value)

    def remove_contextElement(self, value: AtpFeature) -> None:
        """
        Removes a single value from contextElements
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            self.__contextElements.pop(value)
            if value.is_proxy() is False:
                value.referenced_by.remove(self)

    def remove_contextElements(self, values: list[AtpFeature]) -> None:
        """
        Removes a list of value from contextElements
        """
        for value in values:
            self.remove_contextElement(value)

    def get_target(self) -> AtpFeature:
        return self.__target

    def set_target(self, value: AtpFeature) -> None:
        """
        Adds a single value to the target
        """
        if value is not None:
            if isinstance(value, AtpFeature) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of AtpFeature or its sub-classes'.format(value))
            if self.__target is not None and self.__target.is_proxy() is False:
                self.__target.referenced_by.remove(self)
            self.__target = value
            value.referenced_by.add(self)
        elif self.__target is not None:
            if self.__target.is_proxy() is False:
                self.__target.referenced_by.remove(self)
            self.__target = None
        XDT.mark_dirty(self.__target, self)

    def get_variationPoint(self) -> VariationPoint:
        return self.__variationPoint

    def set_variationPoint(self, value: VariationPoint) -> None:
        """
        Adds a single value to the variationPoint
        """
        if value is not None:
            if isinstance(value, VariationPoint) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of VariationPoint or its sub-classes'.format(value))

            value._detach_from_parent()
            self.__variationPoint = value
            value.file = self.file
            value._parent = self #set parent
            if value.name is not None:
                value._refresh_paths()
            else:
                value._build_path(elementNameIfShortNameMissing = 'VariationPoint_@' + str(len(self.get_children()))) #updates the path
            self._sync_add_to_merge_target(value)
        elif self.__variationPoint is not None:
            self.__variationPoint._detach_from_parent()
            self.__variationPoint = None
        XDT.mark_dirty(self.__variationPoint, self)

    def new_VariationPoint(self, name: str=None) -> VariationPoint:
        """
        Creates a new VariationPoint under the AnyInstanceRef.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        VariationPoint_obj = VariationPoint()
        if isinstance(VariationPoint_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        VariationPoint_obj.name = name if isinstance(VariationPoint_obj, Referrable) else None
        self.set_variationPoint(VariationPoint_obj)
        if isinstance(VariationPoint_obj, Referrable):
            VariationPoint_obj.set_shortName(name)
        return VariationPoint_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        if self.__variationPoint is not None:
            children.append(self.__variationPoint)
        return children

    def _containment_slot_of(self, child: AutosarNode) -> str | None:
        if self.__variationPoint is child:
            return 'variationPoint'
        return super()._containment_slot_of(child)

    def add_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'variationPoint':
            if self.__variationPoint is None:
                self.__variationPoint = child
        else:
            super().add_child(child, containment_slot)

    def remove_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'variationPoint':
            if self.__variationPoint is child:
                self.__variationPoint = None
        else:
            super().remove_child(child, containment_slot)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['ContextElements'] = self.__contextElements
        property_values['Target'] = self.__target
        return property_values

    def is_atp_splitable(self) -> bool:
        return True

    def _save_contents(self):
        """
        Saves the content of AnyInstanceRef node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_AtpInstanceRef()
        self._save_reference_list(None, 'CONTEXT-ELEMENT-REF', self.__contextElements, self._insert_after_tags + ['T', 'S'])
        self._save_single_reference('TARGET-REF', self.__target, self._insert_after_tags + ['CONTEXT-ELEMENT-REF', 'T', 'S'])
        self._save_single_child('VARIATION-POINT', self.__variationPoint, self._insert_after_tags + ['TARGET-REF', 'CONTEXT-ELEMENT-REF', 'T', 'S'])

