class SwDataDefPropsConditional(SwDataDefPropsContent):
    """
    This element was generated/modified due to an atpVariation stereotype.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'SW-DATA-DEF-PROPS-CONDITIONAL'
