class RptComponent(Identifiable):
    """
    Description of component instance for which rapid prototyping support is implemented.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'RPT-COMPONENT'
        self._node = etree.Element('RPT-COMPONENT')
        self.__mcDataAssignments = {}
        self.__rpImplPolicy = None
        self.__rptExecutableEntities = {}
        self.__variationPoint = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)

        refCounter = 0
        refCounter = self._build_child_collection(self.__mcDataAssignments, '{*}MC-DATA-ASSIGNMENTS/*', RoleBasedMcDataAssignment, file, 'mcDataAssignments', refCounter)
        self.__rpImplPolicy = self._build_single_child('{*}RP-IMPL-POLICY', RptImplPolicy, file, 'rpImplPolicy')
        refCounter = self._build_child_collection(self.__rptExecutableEntities, '{*}RPT-EXECUTABLE-ENTITYS/*', RptExecutableEntity, file, 'rptExecutableEntities', refCounter)
        self.__variationPoint = self._build_single_child('{*}VARIATION-POINT', VariationPoint, file, 'variationPoint')
        return self

    def get_mcDataAssignments(self) -> list[RoleBasedMcDataAssignment]:
        return list(self.__mcDataAssignments.keys())

    def __bind_mcDataAssignment(self, value: RoleBasedMcDataAssignment) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__mcDataAssignments.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, RoleBasedMcDataAssignment) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of RoleBasedMcDataAssignment or its sub-classes'.format(value))

        value._detach_from_parent()
        value._parent = self #set parent
        value.file = self.file
        if value.name is not None:
            value._refresh_paths()
        else:
            value._build_path(elementNameIfShortNameMissing = 'RoleBasedMcDataAssignment_@' + str(len(self.get_children()))) #updates the path
        XDT.mark_dirty(value, self, attributesToMakeDirty = ['timestamp', 'checksum'])

    def add_mcDataAssignment_at_index(self, index: int, value: RoleBasedMcDataAssignment) -> None:
        """
        Adds a single value to the mcDataAssignments at the given index
        """
        if value is not None:
            self.__bind_mcDataAssignment(value)
            AutosarNode._insert_at_index(self.__mcDataAssignments, value, index)
            self._sync_add_to_merge_target(value)

    def add_mcDataAssignment(self, value: RoleBasedMcDataAssignment) -> None:
        """
        Adds a single value to the mcDataAssignments
        """
        if value is not None:
            self.__bind_mcDataAssignment(value)
            self.__mcDataAssignments[value] = None
            self._sync_add_to_merge_target(value)

    def set_mcDataAssignments(self, values: list[RoleBasedMcDataAssignment]) -> None:
        """
        Adds a list of ref value to the mcDataAssignments
        """
        for value in values:
            self.add_mcDataAssignment(value)

    def remove_mcDataAssignment(self, value: RoleBasedMcDataAssignment) -> None:
        """
        Removes a single value from mcDataAssignments
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            value._detach_from_parent()
            value._parent = None #No parent
            value._refresh_paths() #resets the path
            if value._node.getparent() is not None:
                value._node.getparent().remove(value._node)

    def remove_mcDataAssignments(self, values: list[RoleBasedMcDataAssignment]) -> None:
        """
        Removes a list of value from mcDataAssignments
        """
        for value in values:
            self.remove_mcDataAssignment(value)

