class DependencyOnArtifact(Identifiable):
    """
    Dependency on the existence of another artifact, e.g. a library.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'DEPENDENCY-ON-ARTIFACT'
        self._node = etree.Element('DEPENDENCY-ON-ARTIFACT')
        self.__usages = None
        self.__artifactDescriptor = None
        self.__variationPoint = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        self.__usages = self._read_scalar_element('USAGE', DependencyUsageEnum.get)

        self.__artifactDescriptor = self._build_single_child('{*}ARTIFACT-DESCRIPTOR', AutosarEngineeringObject, file, 'artifactDescriptor')
        self.__variationPoint = self._build_single_child('{*}VARIATION-POINT', VariationPoint, file, 'variationPoint')
        return self

    def get_usages(self) -> DependencyUsageEnum:
        return self.__usages

    def set_usages(self, value: DependencyUsageEnum) -> None:
        self.__usages = value
        XDT.mark_attribute_dirty('usages', self)

    def get_artifactDescriptor(self) -> AutosarEngineeringObject:
        return self.__artifactDescriptor

    def set_artifactDescriptor(self, value: AutosarEngineeringObject) -> None:
        """
        Adds a single value to the artifactDescriptor
        """
        if value is not None:
            if isinstance(value, AutosarEngineeringObject) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of AutosarEngineeringObject or its sub-classes'.format(value))

            value._detach_from_parent()
            self.__artifactDescriptor = value
            value.file = self.file
            value._parent = self #set parent
            if value.name is not None:
                value._refresh_paths()
            else:
                value._build_path(elementNameIfShortNameMissing = 'AutosarEngineeringObject_@' + str(len(self.get_children()))) #updates the path
            self._sync_add_to_merge_target(value)
        elif self.__artifactDescriptor is not None:
            self.__artifactDescriptor._detach_from_parent()
            self.__artifactDescriptor = None
        XDT.mark_dirty(self.__artifactDescriptor, self)

    def get_variationPoint(self) -> VariationPoint:
        return self.__variationPoint

    def set_variationPoint(self, value: VariationPoint) -> None:
        """
        Adds a single value to the variationPoint
        """
        if value is not None:
            if isinstance(value, VariationPoint) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of VariationPoint or its sub-classes'.format(value))

            value._detach_from_parent()
            self.__variationPoint = value
            value.file = self.file
            value._parent = self #set parent
            if value.name is not None:
                value._refresh_paths()
            else:
                value._build_path(elementNameIfShortNameMissing = 'VariationPoint_@' + str(len(self.get_children()))) #updates the path
            self._sync_add_to_merge_target(value)
        elif self.__variationPoint is not None:
            self.__variationPoint._detach_from_parent()
            self.__variationPoint = None
        XDT.mark_dirty(self.__variationPoint, self)

    def new_ArtifactDescriptor(self, name: str=None) -> AutosarEngineeringObject:
        """
        Creates a new AutosarEngineeringObject under the DependencyOnArtifact.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        AutosarEngineeringObject_obj = AutosarEngineeringObject()
        if isinstance(AutosarEngineeringObject_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        AutosarEngineeringObject_obj.name = name if isinstance(AutosarEngineeringObject_obj, Referrable) else None
        self.set_artifactDescriptor(AutosarEngineeringObject_obj)
        if isinstance(AutosarEngineeringObject_obj, Referrable):
            AutosarEngineeringObject_obj.set_shortName(name)
        return AutosarEngineeringObject_obj

    def new_VariationPoint(self, name: str=None) -> VariationPoint:
        """
        Creates a new VariationPoint under the DependencyOnArtifact.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        VariationPoint_obj = VariationPoint()
        if isinstance(VariationPoint_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        VariationPoint_obj.name = name if isinstance(VariationPoint_obj, Referrable) else None
        self.set_variationPoint(VariationPoint_obj)
        if isinstance(VariationPoint_obj, Referrable):
            VariationPoint_obj.set_shortName(name)
        return VariationPoint_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        if self.__artifactDescriptor is not None:
            children.append(self.__artifactDescriptor)
        if self.__variationPoint is not None:
            children.append(self.__variationPoint)
        return children

    def _containment_slot_of(self, child: AutosarNode) -> str | None:
        if self.__artifactDescriptor is child:
            return 'artifactDescriptor'
        if self.__variationPoint is child:
            return 'variationPoint'
        return super()._containment_slot_of(child)

    def add_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'artifactDescriptor':
            if self.__artifactDescriptor is None:
                self.__artifactDescriptor = child
        elif containment_slot == 'variationPoint':
            if self.__variationPoint is None:
                self.__variationPoint = child
        else:
            super().add_child(child, containment_slot)

    def remove_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'artifactDescriptor':
            if self.__artifactDescriptor is child:
                self.__artifactDescriptor = None
        elif containment_slot == 'variationPoint':
            if self.__variationPoint is child:
                self.__variationPoint = None
        else:
            super().remove_child(child, containment_slot)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['Usages'] = self.__usages
        return property_values


    def _save_contents(self):
        """
        Saves the content of DependencyOnArtifact node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_Identifiable()
        self._save_single_child('ARTIFACT-DESCRIPTOR', self.__artifactDescriptor, self._insert_after_tags + ['UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])
        self._save_scalar_element('USAGE', 'usages', self.__usages.literal if self.__usages is not None else None, create_after_nodes = ['ARTIFACT-DESCRIPTOR', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'] + self._insert_after_tags)
        self._save_single_child('VARIATION-POINT', self.__variationPoint, self._insert_after_tags + ['USAGE', 'ARTIFACT-DESCRIPTOR', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])

