class ErrorTracerNeeds(ServiceNeeds):
    """
    Specifies the need to report failures to the error tracer.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'ERROR-TRACER-NEEDS'
        self._node = etree.Element('ERROR-TRACER-NEEDS')
        self.__tracedFailures = {}
        self.__tracedFailures_childTypes = {'DEVELOPMENT-ERROR': 'DevelopmentError', 'RUNTIME-ERROR': 'RuntimeError', 'TRANSIENT-FAULT': 'TransientFault', }

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)

        refCounter = 0
        refCounter = self._build_child_collection(self.__tracedFailures, '{*}TRACED-FAILURES/*', self.__tracedFailures_childTypes, file, 'tracedFailures', refCounter)
        return self

    def get_tracedFailures(self) -> list[TracedFailure]:
        return list(self.__tracedFailures.keys())

    def __bind_tracedFailure(self, value: TracedFailure) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__tracedFailures.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, TracedFailure) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of TracedFailure or its sub-classes'.format(value))

        value._detach_from_parent()
        value._parent = self #set parent
        value.file = self.file
        if value.name is not None:
            value._refresh_paths()
        else:
            value._build_path(elementNameIfShortNameMissing = 'TracedFailure_@' + str(len(self.get_children()))) #updates the path
        XDT.mark_dirty(value, self, attributesToMakeDirty = ['uuid', 'category', 'shortName', 'timestamp', 'checksum'])

    def add_tracedFailure_at_index(self, index: int, value: TracedFailure) -> None:
        """
        Adds a single value to the tracedFailures at the given index
        """
        if value is not None:
            self.__bind_tracedFailure(value)
            AutosarNode._insert_at_index(self.__tracedFailures, value, index)
            self._sync_add_to_merge_target(value)

    def add_tracedFailure(self, value: TracedFailure) -> None:
        """
        Adds a single value to the tracedFailures
        """
        if value is not None:
            self.__bind_tracedFailure(value)
            self.__tracedFailures[value] = None
            self._sync_add_to_merge_target(value)

    def set_tracedFailures(self, values: list[TracedFailure]) -> None:
        """
        Adds a list of ref value to the tracedFailures
        """
        for value in values:
            self.add_tracedFailure(value)

    def remove_tracedFailure(self, value: TracedFailure) -> None:
        """
        Removes a single value from tracedFailures
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            value._detach_from_parent()
            value._parent = None #No parent
            value._refresh_paths() #resets the path
            if value._node.getparent() is not None:
                value._node.getparent().remove(value._node)

    def remove_tracedFailures(self, values: list[TracedFailure]) -> None:
        """
        Removes a list of value from tracedFailures
        """
        for value in values:
            self.remove_tracedFailure(value)

    def new_TransientFault(self, name: str=None) -> TransientFault:
        """
        Creates a new TransientFault under the ErrorTracerNeeds.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        TransientFault_obj = TransientFault()
        if isinstance(TransientFault_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        TransientFault_obj.name = name if isinstance(TransientFault_obj, Referrable) else None
        self.add_tracedFailure(TransientFault_obj)
        if isinstance(TransientFault_obj, Referrable):
            TransientFault_obj.set_shortName(name)
        return TransientFault_obj

    def new_DevelopmentError(self, name: str=None) -> DevelopmentError:
        """
        Creates a new DevelopmentError under the ErrorTracerNeeds.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        DevelopmentError_obj = DevelopmentError()
        if isinstance(DevelopmentError_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        DevelopmentError_obj.name = name if isinstance(DevelopmentError_obj, Referrable) else None
        self.add_tracedFailure(DevelopmentError_obj)
        if isinstance(DevelopmentError_obj, Referrable):
            DevelopmentError_obj.set_shortName(name)
        return DevelopmentError_obj

    def new_RuntimeError(self, name: str=None) -> RuntimeError:
        """
        Creates a new RuntimeError under the ErrorTracerNeeds.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        RuntimeError_obj = RuntimeError()
        if isinstance(RuntimeError_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        RuntimeError_obj.name = name if isinstance(RuntimeError_obj, Referrable) else None
        self.add_tracedFailure(RuntimeError_obj)
        if isinstance(RuntimeError_obj, Referrable):
            RuntimeError_obj.set_shortName(name)
        return RuntimeError_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        children.extend(self.__tracedFailures)
        return children

    def _containment_slot_of(self, child: AutosarNode) -> str | None:
        if child in self.__tracedFailures:
            return 'tracedFailures'
        return super()._containment_slot_of(child)

    def add_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'tracedFailures':
            self.__tracedFailures[child] = None
        else:
            super().add_child(child, containment_slot)

    def remove_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'tracedFailures':
            self.__tracedFailures.pop(child, None)
        else:
            super().remove_child(child, containment_slot)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        return property_values

    def is_atp_splitable(self) -> bool:
        return True

    def _save_contents(self):
        """
        Saves the content of ErrorTracerNeeds node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_ServiceNeeds()
        self._save_child_collection('TRACED-FAILURES', None, self.__tracedFailures, self._insert_after_tags + ['UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])

