class AliasNameSet(ARElement,AtpBlueprint,AtpBlueprintable):
    """
    This meta-class represents a set of AliasNames. The AliasNameSet can for example be an input to the A2L-Generator.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'ALIAS-NAME-SET'
        self._node = etree.Element('ALIAS-NAME-SET')
        self.__aliasNames = {}

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)

        refCounter = 0
        refCounter = self._build_child_collection(self.__aliasNames, '{*}ALIAS-NAMES/*', AliasNameAssignment, file, 'aliasNames', refCounter)
        return self

    def get_aliasNames(self) -> list[AliasNameAssignment]:
        return list(self.__aliasNames.keys())

    def __bind_aliasName(self, value: AliasNameAssignment) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__aliasNames.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, AliasNameAssignment) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of AliasNameAssignment or its sub-classes'.format(value))

        value._detach_from_parent()
        value._parent = self #set parent
        value.file = self.file
        if value.name is not None:
            value._refresh_paths()
        else:
            value._build_path(elementNameIfShortNameMissing = 'AliasNameAssignment_@' + str(len(self.get_children()))) #updates the path
        XDT.mark_dirty(value, self, attributesToMakeDirty = ['timestamp', 'checksum'])

    def add_aliasName_at_index(self, index: int, value: AliasNameAssignment) -> None:
        """
        Adds a single value to the aliasNames at the given index
        """
        if value is not None:
            self.__bind_aliasName(value)
            AutosarNode._insert_at_index(self.__aliasNames, value, index)
            self._sync_add_to_merge_target(value)

    def add_aliasName(self, value: AliasNameAssignment) -> None:
        """
        Adds a single value to the aliasNames
        """
        if value is not None:
            self.__bind_aliasName(value)
            self.__aliasNames[value] = None
            self._sync_add_to_merge_target(value)

    def set_aliasNames(self, values: list[AliasNameAssignment]) -> None:
        """
        Adds a list of ref value to the aliasNames
        """
        for value in values:
            self.add_aliasName(value)

    def remove_aliasName(self, value: AliasNameAssignment) -> None:
        """
        Removes a single value from aliasNames
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            value._detach_from_parent()
            value._parent = None #No parent
            value._refresh_paths() #resets the path
            if value._node.getparent() is not None:
                value._node.getparent().remove(value._node)

    def remove_aliasNames(self, values: list[AliasNameAssignment]) -> None:
        """
        Removes a list of value from aliasNames
        """
        for value in values:
            self.remove_aliasName(value)

    def new_AliasName(self, name: str=None) -> AliasNameAssignment:
        """
        Creates a new AliasNameAssignment under the AliasNameSet.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        AliasNameAssignment_obj = AliasNameAssignment()
        if isinstance(AliasNameAssignment_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        AliasNameAssignment_obj.name = name if isinstance(AliasNameAssignment_obj, Referrable) else None
        self.add_aliasName(AliasNameAssignment_obj)
        if isinstance(AliasNameAssignment_obj, Referrable):
            AliasNameAssignment_obj.set_shortName(name)
        return AliasNameAssignment_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        children.extend(self.__aliasNames)
        return children

    def _containment_slot_of(self, child: AutosarNode) -> str | None:
        if child in self.__aliasNames:
            return 'aliasNames'
        return super()._containment_slot_of(child)

    def add_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'aliasNames':
            self.__aliasNames[child] = None
        else:
            super().add_child(child, containment_slot)

    def remove_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'aliasNames':
            self.__aliasNames.pop(child, None)
        else:
            super().remove_child(child, containment_slot)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        return property_values

    def is_atp_splitable(self) -> bool:
        return True

    def _save_contents(self):
        """
        Saves the content of AliasNameSet node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_ARElement()
        super()._save_AtpBlueprint()
        super()._save_AtpBlueprintable()
        self._save_child_collection('ALIAS-NAMES', None, self.__aliasNames, self._insert_after_tags + ['SHORT-NAME-PATTERN', 'BLUEPRINT-POLICYS', 'VARIATION-POINT', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])

