class BswCompositionTiming(TimingExtension):
    """
    A model element used to define timing descriptions and constraints for a set of BswImplementations representing a BSW composition. A constraint defined at this level holds true for all referenced BswImplementations. Note, that multiple implementations of the same basic software module could be involved., , TimingDescriptions aggregated by BswCompositionTiming are restricted to event chains referring to events which are derived from the class TDEventBswInternalBehavior and TDEventBsw.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'BSW-COMPOSITION-TIMING'
        self._node = etree.Element('BSW-COMPOSITION-TIMING')
        self.__implementations = {}


    def _resolve_references(self):
        super()._resolve_references()
        self.__implementations = self._resolve_reference_list('{*}IMPLEMENTATION-REFS/*', self.__implementations)

    def get_implementations(self) -> list[BswImplementation]:
        return list(self.__implementations.keys())

    def __bind_implementation(self, value: BswImplementation) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__implementations.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, BswImplementation) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of BswImplementation or its sub-classes'.format(value))

        value.referenced_by.add(self)
        XDT.mark_dirty(value, self)


    def add_implementation(self, value: BswImplementation) -> None:
        """
        Adds a single value to the implementations
        """
        if value is not None:
            self.__bind_implementation(value)
            self.__implementations[value] = None

    def set_implementations(self, values: list[BswImplementation]) -> None:
        """
        Adds a list of ref value to the implementations
        """
        for value in values:
            self.add_implementation(value)

    def remove_implementation(self, value: BswImplementation) -> None:
        """
        Removes a single value from implementations
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            self.__implementations.pop(value)
            if value.is_proxy() is False:
                value.referenced_by.remove(self)

    def remove_implementations(self, values: list[BswImplementation]) -> None:
        """
        Removes a list of value from implementations
        """
        for value in values:
            self.remove_implementation(value)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['Implementations'] = self.__implementations
        return property_values

    def is_atp_splitable(self) -> bool:
        return True

    def _save_contents(self):
        """
        Saves the content of BswCompositionTiming node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_TimingExtension()
        self._save_reference_list('IMPLEMENTATION-REFS', 'IMPLEMENTATION-REF', self.__implementations, self._insert_after_tags + ['TIMING-RESOURCE', 'TIMING-REQUIREMENTS', 'TIMING-GUARANTEES', 'TIMING-DESCRIPTIONS', 'TIMING-CONDITIONS', 'VARIATION-POINT', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])

