class TimingDescriptionEventChain(TimingDescription):
    """
    An event chain describes the causal order for a set of functionally dependent timing events. Each event chain has a well defined stimulus and response, which describe its start and end point. Furthermore, it can be hierarchically decomposed into an arbitrary number of sub-chains, so called ''event chain segments''.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'TIMING-DESCRIPTION-EVENT-CHAIN'
        self._node = etree.Element('TIMING-DESCRIPTION-EVENT-CHAIN')
        self.__stimulus = None
        self.__response = None
        self.__segments = {}


    def _resolve_references(self):
        super()._resolve_references()
        self.__stimulus = self._resolve_single_reference('{*}STIMULUS-REF', self.__stimulus)
        self.__response = self._resolve_single_reference('{*}RESPONSE-REF', self.__response)
        self.__segments = self._resolve_reference_list('{*}SEGMENT-REFS/*', self.__segments)

    def get_stimulus(self) -> TimingDescriptionEvent:
        return self.__stimulus

    def set_stimulus(self, value: TimingDescriptionEvent) -> None:
        """
        Adds a single value to the stimulus
        """
        if value is not None:
            if isinstance(value, TimingDescriptionEvent) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of TimingDescriptionEvent or its sub-classes'.format(value))
            if self.__stimulus is not None and self.__stimulus.is_proxy() is False:
                self.__stimulus.referenced_by.remove(self)
            self.__stimulus = value
            value.referenced_by.add(self)
        elif self.__stimulus is not None:
            if self.__stimulus.is_proxy() is False:
                self.__stimulus.referenced_by.remove(self)
            self.__stimulus = None
        XDT.mark_dirty(self.__stimulus, self)

    def get_response(self) -> TimingDescriptionEvent:
        return self.__response

    def set_response(self, value: TimingDescriptionEvent) -> None:
        """
        Adds a single value to the response
        """
        if value is not None:
            if isinstance(value, TimingDescriptionEvent) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of TimingDescriptionEvent or its sub-classes'.format(value))
            if self.__response is not None and self.__response.is_proxy() is False:
                self.__response.referenced_by.remove(self)
            self.__response = value
            value.referenced_by.add(self)
        elif self.__response is not None:
            if self.__response.is_proxy() is False:
                self.__response.referenced_by.remove(self)
            self.__response = None
        XDT.mark_dirty(self.__response, self)

    def get_segments(self) -> list[TimingDescriptionEventChain]:
        return list(self.__segments.keys())

    def __bind_segment(self, value: TimingDescriptionEventChain) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__segments.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, TimingDescriptionEventChain) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of TimingDescriptionEventChain or its sub-classes'.format(value))

        value.referenced_by.add(self)
        XDT.mark_dirty(value, self)


    def add_segment(self, value: TimingDescriptionEventChain) -> None:
        """
        Adds a single value to the segments
        """
        if value is not None:
            self.__bind_segment(value)
            self.__segments[value] = None

    def set_segments(self, values: list[TimingDescriptionEventChain]) -> None:
        """
        Adds a list of ref value to the segments
        """
        for value in values:
            self.add_segment(value)

    def remove_segment(self, value: TimingDescriptionEventChain) -> None:
        """
        Removes a single value from segments
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            self.__segments.pop(value)
            if value.is_proxy() is False:
                value.referenced_by.remove(self)

    def remove_segments(self, values: list[TimingDescriptionEventChain]) -> None:
        """
        Removes a list of value from segments
        """
        for value in values:
            self.remove_segment(value)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['Stimulus'] = self.__stimulus
        property_values['Response'] = self.__response
        property_values['Segments'] = self.__segments
        return property_values

