class TDEventSwc(TimingDescriptionEvent):
    """
    This is the abstract parent class to describe timing events at Software Component (SW-C) level.
    """
    def __init__(self):
        super().__init__()
        self.__component = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)

        self.__component = self._build_single_child('{*}COMPONENT-IREF', ComponentInCompositionInstanceRef, file, 'component')
        return self

    def get_component(self) -> ComponentInCompositionInstanceRef:
        return self.__component

    def set_component(self, value: ComponentInCompositionInstanceRef) -> None:
        """
        Adds a single value to the component
        """
        if value is not None:
            if isinstance(value, ComponentInCompositionInstanceRef) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of ComponentInCompositionInstanceRef or its sub-classes'.format(value))

            value._detach_from_parent()
            self.__component = value
            value.file = self.file
            value._parent = self #set parent
            if value.name is not None:
                value._refresh_paths()
            else:
                value._build_path(elementNameIfShortNameMissing = 'ComponentInCompositionInstanceRef_@' + str(len(self.get_children()))) #updates the path
            self._sync_add_to_merge_target(value)
        elif self.__component is not None:
            self.__component._detach_from_parent()
            self.__component = None
        XDT.mark_dirty(self.__component, self)

    def new_Component(self, name: str=None) -> ComponentInCompositionInstanceRef:
        """
        Creates a new ComponentInCompositionInstanceRef under the TDEventSwc.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        ComponentInCompositionInstanceRef_obj = ComponentInCompositionInstanceRef()
        if isinstance(ComponentInCompositionInstanceRef_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        ComponentInCompositionInstanceRef_obj.name = name if isinstance(ComponentInCompositionInstanceRef_obj, Referrable) else None
        self.set_component(ComponentInCompositionInstanceRef_obj)
        if isinstance(ComponentInCompositionInstanceRef_obj, Referrable):
            ComponentInCompositionInstanceRef_obj.set_shortName(name)
        return ComponentInCompositionInstanceRef_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        if self.__component is not None:
            children.append(self.__component)
        return children

    def _containment_slot_of(self, child: AutosarNode) -> str | None:
        if self.__component is child:
            return 'component'
        return super()._containment_slot_of(child)

    def add_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'component':
            if self.__component is None:
                self.__component = child
        else:
            super().add_child(child, containment_slot)

    def remove_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'component':
            if self.__component is child:
                self.__component = None
        else:
            super().remove_child(child, containment_slot)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        return property_values

    def is_atp_splitable(self) -> bool:
        return True

    def _save_TDEventSwc(self):
        """
        Saves the content of TDEventSwc node
        """
        super()._save_TimingDescriptionEvent()
        self._save_single_child('COMPONENT-IREF', self.__component, self._insert_after_tags + ['OCCURRENCE-EXPRESSION', 'VARIATION-POINT', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])

