        self._save_single_reference('ARGUMENT-REF', self.__argument, self._insert_after_tags + ['AGE', 'ANNOTATION-TEXT', 'ANNOTATION-ORIGIN', 'LABEL', 'T', 'S'])
        self._save_scalar_element('BSW-RESOLUTION', 'bswResolution', str(self.__bswResolution) if self.__bswResolution is not None else None, create_after_nodes = ['ARGUMENT-REF', 'AGE', 'ANNOTATION-TEXT', 'ANNOTATION-ORIGIN', 'LABEL', 'T', 'S'] + self._insert_after_tags)
