class SwRecordLayoutGroup(ARObject):
    """
    Specifies how a record layout is set up. Using SwRecordLayoutGroup it recursively models iterations through axis values. The subelement swRecordLayoutGroupContentType may reference other SwRecordLayouts, SwRecordLayoutVs and SwRecordLayoutGroups for the modeled record layout.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'SW-RECORD-LAYOUT-GROUP'
        self._node = etree.Element('SW-RECORD-LAYOUT-GROUP')
        self.__shortLabel = None
        self.__category = None
        self.__swRecordLayoutGroupAxis = None
        self.__swRecordLayoutGroupIndex = None
        self.__swRecordLayoutGroupFrom = None
        self.__swRecordLayoutGroupTo = None
        self.__swRecordLayoutGroupStep = None
        self.__swRecordLayoutComponent = None
        self.__desc = None
        self.__swGenericAxisParamType = None
        self.__swRecordLayouts = {}
        self.__swRecordLayoutGroups = {}
        self.__swRecordLayoutVs = {}

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        self.__shortLabel = self._read_scalar_element('SHORT-LABEL', datatype_utils.get_string_value)
        self.__category = self._read_scalar_element('CATEGORY', datatype_utils.get_string_value)
        self.__swRecordLayoutGroupAxis = self._read_scalar_element('SW-RECORD-LAYOUT-GROUP-AXIS', datatype_utils.get_string_value)
        self.__swRecordLayoutGroupIndex = self._read_scalar_element('SW-RECORD-LAYOUT-GROUP-INDEX', datatype_utils.get_string_value)
        self.__swRecordLayoutGroupFrom = self._read_scalar_element('SW-RECORD-LAYOUT-GROUP-FROM', datatype_utils.get_string_value)
        self.__swRecordLayoutGroupTo = self._read_scalar_element('SW-RECORD-LAYOUT-GROUP-TO', datatype_utils.get_string_value)
        self.__swRecordLayoutGroupStep = self._read_scalar_element('SW-RECORD-LAYOUT-GROUP-STEP', datatype_utils.get_int_value)
        self.__swRecordLayoutComponent = self._read_scalar_element('SW-RECORD-LAYOUT-COMPONENT', datatype_utils.get_string_value)

        refCounter = 0
        self.__desc = self._build_single_child('{*}DESC', MultiLanguageOverviewParagraph, file, 'desc')
        refCounter = self._build_child_collection(self.__swRecordLayoutGroups, '{*}SW-RECORD-LAYOUT-GROUP', SwRecordLayoutGroup, file, 'swRecordLayoutGroups', refCounter)
        refCounter = self._build_child_collection(self.__swRecordLayoutVs, '{*}SW-RECORD-LAYOUT-V', SwRecordLayoutV, file, 'swRecordLayoutVs', refCounter)
        return self

