class SwcInternalBehavior(InternalBehavior):
    """
    The SwcInternalBehavior of an AtomicSwComponentType describes the relevant aspects of the software-component with respect to the RTE, i.e. the RunnableEntities and the RTEEvents they respond to.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'SWC-INTERNAL-BEHAVIOR'
        self._node = etree.Element('SWC-INTERNAL-BEHAVIOR')
        self.__handleTerminationAndRestart = None
        self.__supportsMultipleInstantiation = None
        self.__arTypedPerInstanceMemories = {}
        self.__events = {}
        self.__exclusiveAreaPolicies = {}
