class AccessCountSet(ARObject):
    """
    This meta-class provides a set of count values evaluated according to the rules of a specific countProfile.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'ACCESS-COUNT-SET'
        self._node = etree.Element('ACCESS-COUNT-SET')
        self.__countProfile = None
        self.__accessCounts = {}
        self.__variationPoint = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        self.__countProfile = self._read_scalar_element('COUNT-PROFILE', datatype_utils.get_string_value)

        refCounter = 0
        refCounter = self._build_child_collection(self.__accessCounts, '{*}ACCESS-COUNTS/*', AccessCount, file, 'accessCounts', refCounter)
        self.__variationPoint = self._build_single_child('{*}VARIATION-POINT', VariationPoint, file, 'variationPoint')
        return self

    def get_countProfile(self) -> str:
        return self.__countProfile

    def set_countProfile(self, value: str) -> None:
        self.__countProfile = value
        XDT.mark_attribute_dirty('countProfile', self)

    def get_accessCounts(self) -> list[AccessCount]:
        return list(self.__accessCounts.keys())

    def __bind_accessCount(self, value: AccessCount) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__accessCounts.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, AccessCount) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of AccessCount or its sub-classes'.format(value))

        value._detach_from_parent()
        value._parent = self #set parent
        value.file = self.file
        if value.name is not None:
            value._refresh_paths()
        else:
            value._build_path(elementNameIfShortNameMissing = 'AccessCount_@' + str(len(self.get_children()))) #updates the path
        XDT.mark_dirty(value, self, attributesToMakeDirty = ['timestamp', 'checksum'])

    def add_accessCount_at_index(self, index: int, value: AccessCount) -> None:
        """
        Adds a single value to the accessCounts at the given index
        """
        if value is not None:
            self.__bind_accessCount(value)
            AutosarNode._insert_at_index(self.__accessCounts, value, index)
            self._sync_add_to_merge_target(value)

    def add_accessCount(self, value: AccessCount) -> None:
        """
        Adds a single value to the accessCounts
        """
        if value is not None:
            self.__bind_accessCount(value)
            self.__accessCounts[value] = None
            self._sync_add_to_merge_target(value)

    def set_accessCounts(self, values: list[AccessCount]) -> None:
        """
        Adds a list of ref value to the accessCounts
        """
