class IncludedModeDeclarationGroupSet(ARObject):
    """
    An IncludedModeDeclarationGroupSet declares that a set of ModeDeclarationGroups used by the software component for its implementation and consequently these ModeDeclarationGroups become part of the contract.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'INCLUDED-MODE-DECLARATION-GROUP-SET'
        self._node = etree.Element('INCLUDED-MODE-DECLARATION-GROUP-SET')
        self.__prefix = None
        self.__modeDeclarationGroups = {}

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        self.__prefix = self._read_scalar_element('PREFIX', datatype_utils.get_string_value)

        return self

    def _resolve_references(self):
        super()._resolve_references()
        self.__modeDeclarationGroups = self._resolve_reference_list('{*}MODE-DECLARATION-GROUP-REFS/*', self.__modeDeclarationGroups)

    def get_prefix(self) -> str:
        return self.__prefix

    def set_prefix(self, value: str) -> None:
        self.__prefix = value
        XDT.mark_attribute_dirty('prefix', self)

    def get_modeDeclarationGroups(self) -> list[ModeDeclarationGroup]:
        return list(self.__modeDeclarationGroups.keys())

    def __bind_modeDeclarationGroup(self, value: ModeDeclarationGroup) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__modeDeclarationGroups.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, ModeDeclarationGroup) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of ModeDeclarationGroup or its sub-classes'.format(value))

        value.referenced_by.add(self)
        XDT.mark_dirty(value, self)


    def add_modeDeclarationGroup(self, value: ModeDeclarationGroup) -> None:
        """
        Adds a single value to the modeDeclarationGroups
        """
        if value is not None:
            self.__bind_modeDeclarationGroup(value)
            self.__modeDeclarationGroups[value] = None

    def set_modeDeclarationGroups(self, values: list[ModeDeclarationGroup]) -> None:
        """
        Adds a list of ref value to the modeDeclarationGroups
        """
        for value in values:
            self.add_modeDeclarationGroup(value)

    def remove_modeDeclarationGroup(self, value: ModeDeclarationGroup) -> None:
        """
        Removes a single value from modeDeclarationGroups
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            self.__modeDeclarationGroups.pop(value)
            if value.is_proxy() is False:
                value.referenced_by.remove(self)

    def remove_modeDeclarationGroups(self, values: list[ModeDeclarationGroup]) -> None:
        """
        Removes a list of value from modeDeclarationGroups
        """
        for value in values:
            self.remove_modeDeclarationGroup(value)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['Prefix'] = self.__prefix
        property_values['ModeDeclarationGroups'] = self.__modeDeclarationGroups
        return property_values

    def is_atp_splitable(self) -> bool:
        return True

    def _save_contents(self):
        """
        Saves the content of IncludedModeDeclarationGroupSet node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_ARObject()
        self._save_reference_list('MODE-DECLARATION-GROUP-REFS', 'MODE-DECLARATION-GROUP-REF', self.__modeDeclarationGroups, self._insert_after_tags + ['T', 'S'])
        self._save_scalar_element('PREFIX', 'prefix', str(self.__prefix) if self.__prefix is not None else None, create_after_nodes = ['MODE-DECLARATION-GROUP-REFS', 'T', 'S'] + self._insert_after_tags)

