class IncludedDataTypeSet(ARObject):
    """
    An includedDataTypeSet declares that a set of AutosarDataType is used by a basic software module or a software component for its implementation and the AutosarDataType becomes part of the contract. , , This information is required if the AutosarDataType is not used for any DataPrototype owned by this software component or if the enumeration literals, lowerLimit and upperLimit constants shall be generated with a literalPrefix., , The optional literalPrefix is used to add a common prefix on enumeration literals, lowerLimit and upperLimit constants created by the RTE.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'INCLUDED-DATA-TYPE-SET'
        self._node = etree.Element('INCLUDED-DATA-TYPE-SET')
        self.__literalPrefix = None
        self.__dataTypes = {}

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        self.__literalPrefix = self._read_scalar_element('LITERAL-PREFIX', datatype_utils.get_string_value)

        return self

    def _resolve_references(self):
        super()._resolve_references()
        self.__dataTypes = self._resolve_reference_list('{*}DATA-TYPE-REFS/*', self.__dataTypes)

    def get_literalPrefix(self) -> str:
        return self.__literalPrefix

    def set_literalPrefix(self, value: str) -> None:
        self.__literalPrefix = value
        XDT.mark_attribute_dirty('literalPrefix', self)

    def get_dataTypes(self) -> list[AutosarDataType]:
        return list(self.__dataTypes.keys())

    def __bind_dataType(self, value: AutosarDataType) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__dataTypes.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, AutosarDataType) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of AutosarDataType or its sub-classes'.format(value))

        value.referenced_by.add(self)
        XDT.mark_dirty(value, self)


    def add_dataType(self, value: AutosarDataType) -> None:
        """
        Adds a single value to the dataTypes
        """
        if value is not None:
            self.__bind_dataType(value)
            self.__dataTypes[value] = None

    def set_dataTypes(self, values: list[AutosarDataType]) -> None:
        """
        Adds a list of ref value to the dataTypes
        """
        for value in values:
            self.add_dataType(value)

    def remove_dataType(self, value: AutosarDataType) -> None:
        """
        Removes a single value from dataTypes
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            self.__dataTypes.pop(value)
            if value.is_proxy() is False:
                value.referenced_by.remove(self)

    def remove_dataTypes(self, values: list[AutosarDataType]) -> None:
        """
        Removes a list of value from dataTypes
        """
        for value in values:
            self.remove_dataType(value)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['LiteralPrefix'] = self.__literalPrefix
        property_values['DataTypes'] = self.__dataTypes
        return property_values

    def is_atp_splitable(self) -> bool:
        return True

    def _save_contents(self):
        """
        Saves the content of IncludedDataTypeSet node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_ARObject()
        self._save_reference_list('DATA-TYPE-REFS', 'DATA-TYPE-REF', self.__dataTypes, self._insert_after_tags + ['T', 'S'])
        self._save_scalar_element('LITERAL-PREFIX', 'literalPrefix', str(self.__literalPrefix) if self.__literalPrefix is not None else None, create_after_nodes = ['DATA-TYPE-REFS', 'T', 'S'] + self._insert_after_tags)

