class RptHook(ARObject):
    """
    This meta class provide the ability to describe a rapid prototyping hook. This can either be described by an other AUTOSAR system with the category RPT_SYSTEM or as a non AUTOSAR software.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'RPT-HOOK'
        self._node = etree.Element('RPT-HOOK')
        self.__codeLabel = None
        self.__mcdIdentifier = None
        self.__rptArHook = None
        self.__sdgs = {}
        self.__variationPoint = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        self.__codeLabel = self._read_scalar_element('CODE-LABEL', datatype_utils.get_string_value)
        self.__mcdIdentifier = self._read_scalar_element('MCD-IDENTIFIER', datatype_utils.get_string_value)

        refCounter = 0
        self.__rptArHook = self._build_single_child('{*}RPT-AR-HOOK-IREF', AnyInstanceRef, file, 'rptArHook')
        refCounter = self._build_child_collection(self.__sdgs, '{*}SDGS/*', Sdg, file, 'sdgs', refCounter)
        self.__variationPoint = self._build_single_child('{*}VARIATION-POINT', VariationPoint, file, 'variationPoint')
        return self

    def get_codeLabel(self) -> str:
        return self.__codeLabel

    def set_codeLabel(self, value: str) -> None:
        self.__codeLabel = value
        XDT.mark_attribute_dirty('codeLabel', self)

    def get_mcdIdentifier(self) -> str:
        return self.__mcdIdentifier

    def set_mcdIdentifier(self, value: str) -> None:
        self.__mcdIdentifier = value
        XDT.mark_attribute_dirty('mcdIdentifier', self)

    def get_rptArHook(self) -> AnyInstanceRef:
        return self.__rptArHook

    def set_rptArHook(self, value: AnyInstanceRef) -> None:
        """
        Adds a single value to the rptArHook
        """
        if value is not None:
            if isinstance(value, AnyInstanceRef) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of AnyInstanceRef or its sub-classes'.format(value))

            value._detach_from_parent()
            self.__rptArHook = value
