class BswModeSwitchEvent(BswScheduleEvent):
    """
    A BswEvent resulting from a mode switch.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'BSW-MODE-SWITCH-EVENT'
        self._node = etree.Element('BSW-MODE-SWITCH-EVENT')
        self.__activation = None
        self.__modes = {}

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        self.__activation = self._read_scalar_element('ACTIVATION', ModeActivationKind.get)

        refCounter = 0
        refCounter = self._build_child_collection(self.__modes, '{*}MODE-IREFS/*', ModeInBswModuleDescriptionInstanceRef, file, 'modes', refCounter)
        return self

    def get_activation(self) -> ModeActivationKind:
        return self.__activation

    def set_activation(self, value: ModeActivationKind) -> None:
        self.__activation = value
        XDT.mark_attribute_dirty('activation', self)

    def get_modes(self) -> list[ModeInBswModuleDescriptionInstanceRef]:
        return list(self.__modes.keys())

    def __bind_mode(self, value: ModeInBswModuleDescriptionInstanceRef) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__modes.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, ModeInBswModuleDescriptionInstanceRef) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of ModeInBswModuleDescriptionInstanceRef or its sub-classes'.format(value))

        value._detach_from_parent()
        value._parent = self #set parent
        value.file = self.file
        if value.name is not None:
            value._refresh_paths()
        else:
            value._build_path(elementNameIfShortNameMissing = 'ModeInBswModuleDescriptionInstanceRef_@' + str(len(self.get_children()))) #updates the path
        XDT.mark_dirty(value, self, attributesToMakeDirty = ['timestamp', 'checksum'])

    def add_mode_at_index(self, index: int, value: ModeInBswModuleDescriptionInstanceRef) -> None:
        """
        Adds a single value to the modes at the given index
        """
        if value is not None:
            self.__bind_mode(value)
            AutosarNode._insert_at_index(self.__modes, value, index)
            self._sync_add_to_merge_target(value)

    def add_mode(self, value: ModeInBswModuleDescriptionInstanceRef) -> None:
        """
        Adds a single value to the modes
        """
        if value is not None:
            self.__bind_mode(value)
            self.__modes[value] = None
            self._sync_add_to_merge_target(value)

    def set_modes(self, values: list[ModeInBswModuleDescriptionInstanceRef]) -> None:
        """
        Adds a list of ref value to the modes
        """
        for value in values:
            self.add_mode(value)

    def remove_mode(self, value: ModeInBswModuleDescriptionInstanceRef) -> None:
        """
        Removes a single value from modes
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            value._detach_from_parent()
            value._parent = None #No parent
            value._refresh_paths() #resets the path
            if value._node.getparent() is not None:
                value._node.getparent().remove(value._node)

    def remove_modes(self, values: list[ModeInBswModuleDescriptionInstanceRef]) -> None:
        """
        Removes a list of value from modes
        """
        for value in values:
            self.remove_mode(value)

    def new_Mode(self, name: str=None) -> ModeInBswModuleDescriptionInstanceRef:
        """
        Creates a new ModeInBswModuleDescriptionInstanceRef under the BswModeSwitchEvent.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        ModeInBswModuleDescriptionInstanceRef_obj = ModeInBswModuleDescriptionInstanceRef()
        if isinstance(ModeInBswModuleDescriptionInstanceRef_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        ModeInBswModuleDescriptionInstanceRef_obj.name = name if isinstance(ModeInBswModuleDescriptionInstanceRef_obj, Referrable) else None
        self.add_mode(ModeInBswModuleDescriptionInstanceRef_obj)
        if isinstance(ModeInBswModuleDescriptionInstanceRef_obj, Referrable):
            ModeInBswModuleDescriptionInstanceRef_obj.set_shortName(name)
        return ModeInBswModuleDescriptionInstanceRef_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        children.extend(self.__modes)
        return children

    def _containment_slot_of(self, child: AutosarNode) -> str | None:
        if child in self.__modes:
            return 'modes'
        return super()._containment_slot_of(child)

    def add_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'modes':
            self.__modes[child] = None
        else:
            super().add_child(child, containment_slot)

    def remove_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'modes':
            self.__modes.pop(child, None)
        else:
            super().remove_child(child, containment_slot)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['Activation'] = self.__activation
        return property_values

    def is_atp_splitable(self) -> bool:
        return True

    def _save_contents(self):
        """
        Saves the content of BswModeSwitchEvent node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_BswScheduleEvent()
        self._save_scalar_element('ACTIVATION', 'activation', self.__activation.literal if self.__activation is not None else None, create_after_nodes = ['VARIATION-POINT', 'STARTS-ON-EVENT-REF', 'DISABLED-IN-MODE-IREFS', 'CONTEXT-LIMITATION-REFS', 'ACTIVATION-REASON-REPRESENTATION-REF', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'] + self._insert_after_tags)
        self._save_child_collection('MODE-IREFS', 'MODE-IREF', self.__modes, self._insert_after_tags + ['ACTIVATION', 'VARIATION-POINT', 'STARTS-ON-EVENT-REF', 'DISABLED-IN-MODE-IREFS', 'CONTEXT-LIMITATION-REFS', 'ACTIVATION-REASON-REPRESENTATION-REF', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])

