class ClientIdDefinition(Identifiable):
    """
    Several clients in one client-ECU can communicate via inter-ECU client-server communication with a server on a different ECU, if a client identifier is used to distinguish the different clients., The Client Identifier of the transaction handle that is used by the RTE can be defined by this element.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'CLIENT-ID-DEFINITION'
        self._node = etree.Element('CLIENT-ID-DEFINITION')
        self.__clientId = None
        self.__clientServerOperation = None
        self.__variationPoint = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        self.__clientId = self._read_scalar_element('CLIENT-ID', datatype_utils.get_string_value)

        self.__clientServerOperation = self._build_single_child('{*}CLIENT-SERVER-OPERATION-IREF', OperationInSystemInstanceRef, file, 'clientServerOperation')
        self.__variationPoint = self._build_single_child('{*}VARIATION-POINT', VariationPoint, file, 'variationPoint')
        return self

    def get_clientId(self) -> str:
        return self.__clientId

    def set_clientId(self, value: str) -> None:
        self.__clientId = value
        XDT.mark_attribute_dirty('clientId', self)

    def get_clientServerOperation(self) -> OperationInSystemInstanceRef:
        return self.__clientServerOperation

    def set_clientServerOperation(self, value: OperationInSystemInstanceRef) -> None:
        """
        Adds a single value to the clientServerOperation
        """
        if value is not None:
            if isinstance(value, OperationInSystemInstanceRef) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of OperationInSystemInstanceRef or its sub-classes'.format(value))

            value._detach_from_parent()
            self.__clientServerOperation = value
            value.file = self.file
            value._parent = self #set parent
            if value.name is not None:
                value._refresh_paths()
            else:
                value._build_path(elementNameIfShortNameMissing = 'OperationInSystemInstanceRef_@' + str(len(self.get_children()))) #updates the path
            self._sync_add_to_merge_target(value)
        elif self.__clientServerOperation is not None:
            self.__clientServerOperation._detach_from_parent()
