class SocketAddress(Identifiable):
    """
    This meta-class represents a socket address towards the rest of the meta-model. The actual semantics of the represented socket address, however, is contributed by aggregation of an ApplicationEndpoint.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'SOCKET-ADDRESS'
        self._node = etree.Element('SOCKET-ADDRESS')
        self.__differentiatedServiceField = None
        self.__flowLabel = None
        self.__ipAddress = None
        self.__pathMtuDiscoveryEnabled = None
        self.__pduCollectionMaxBufferSize = None
        self.__pduCollectionTimeout = None
        self.__portAddress = None
        self.__udpChecksumHandling = None
        self.__allowedIPv6ExtHeaders = None
        self.__allowedTcpOptions = None
        self.__applicationEndpoint = None
        self.__connector = None
        self.__multicastConnectors = {}
        self.__staticSocketConnections = {}
        self.__variationPoint = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        self.__differentiatedServiceField = self._read_scalar_element('DIFFERENTIATED-SERVICE-FIELD', datatype_utils.get_int_value)
        self.__flowLabel = self._read_scalar_element('FLOW-LABEL', datatype_utils.get_int_value)
        self.__ipAddress = self._read_scalar_element('IP-ADDRESS', datatype_utils.get_string_value)
        self.__pathMtuDiscoveryEnabled = self._read_scalar_element('PATH-MTU-DISCOVERY-ENABLED', datatype_utils.get_bool_value)
        self.__pduCollectionMaxBufferSize = self._read_scalar_element('PDU-COLLECTION-MAX-BUFFER-SIZE', datatype_utils.get_int_value)
        self.__pduCollectionTimeout = self._read_scalar_element('PDU-COLLECTION-TIMEOUT', datatype_utils.get_float_value)
        self.__portAddress = self._read_scalar_element('PORT-ADDRESS', datatype_utils.get_int_value)
        self.__udpChecksumHandling = self._read_scalar_element('UDP-CHECKSUM-HANDLING', UdpChecksumCalculationEnum.get)

        refCounter = 0
        self.__applicationEndpoint = self._build_single_child('{*}APPLICATION-ENDPOINT', ApplicationEndpoint, file, 'applicationEndpoint')
        refCounter = self._build_child_collection(self.__staticSocketConnections, '{*}STATIC-SOCKET-CONNECTIONS/*', StaticSocketConnection, file, 'staticSocketConnections', refCounter)
        self.__variationPoint = self._build_single_child('{*}VARIATION-POINT', VariationPoint, file, 'variationPoint')
        return self

    def _resolve_references(self):
        super()._resolve_references()
        self.__allowedIPv6ExtHeaders = self._resolve_single_reference('{*}ALLOWED-I-PV-6-EXT-HEADERS-REF', self.__allowedIPv6ExtHeaders)
