        refCounter = self._build_child_collection(self.__localUnicastAddress, '{*}LOCAL-UNICAST-ADDRESSS/*', ApplicationEndpointRefConditional, file, 'localUnicastAddress', refCounter)
        refCounter = self._build_child_collection(self.__remoteUnicastAddress, '{*}REMOTE-UNICAST-ADDRESSS/*', ApplicationEndpointRefConditional, file, 'remoteUnicastAddress', refCounter)
