class PdurIPduGroup(FibexElement):
    """
    The AUTOSAR PduR will enable and disable the sending of configurable groups of IPdus during runtime according to the AUTOSAR PduR specification.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'PDUR-I-PDU-GROUP'
        self._node = etree.Element('PDUR-I-PDU-GROUP')
        self.__communicationMode = None
        self.__iPdus = {}

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        self.__communicationMode = self._read_scalar_element('COMMUNICATION-MODE', datatype_utils.get_string_value)

        refCounter = 0
        refCounter = self._build_child_collection(self.__iPdus, '{*}I-PDUS/*', PduTriggeringRefConditional, file, 'iPdus', refCounter)
        return self

    def get_communicationMode(self) -> str:
        return self.__communicationMode

    def set_communicationMode(self, value: str) -> None:
        self.__communicationMode = value
        XDT.mark_attribute_dirty('communicationMode', self)

    def get_iPdus(self) -> list[PduTriggeringRefConditional]:
        return list(self.__iPdus.keys())

    def __bind_iPdu(self, value: PduTriggeringRefConditional) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__iPdus.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, PduTriggeringRefConditional) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of PduTriggeringRefConditional or its sub-classes'.format(value))

        value._detach_from_parent()
        value._parent = self #set parent
        value.file = self.file
        if value.name is not None:
            value._refresh_paths()
        else:
            value._build_path(elementNameIfShortNameMissing = 'PduTriggeringRefConditional_@' + str(len(self.get_children()))) #updates the path
        XDT.mark_dirty(value, self, attributesToMakeDirty = ['timestamp', 'checksum'])

    def add_iPdu_at_index(self, index: int, value: PduTriggeringRefConditional) -> None:
        """
        Adds a single value to the iPdus at the given index
        """
        if value is not None:
            self.__bind_iPdu(value)
            AutosarNode._insert_at_index(self.__iPdus, value, index)
            self._sync_add_to_merge_target(value)

    def add_iPdu(self, value: PduTriggeringRefConditional) -> None:
        """
        Adds a single value to the iPdus
        """
        if value is not None:
            self.__bind_iPdu(value)
            self.__iPdus[value] = None
            self._sync_add_to_merge_target(value)

    def set_iPdus(self, values: list[PduTriggeringRefConditional]) -> None:
        """
        Adds a list of ref value to the iPdus
        """
        for value in values:
            self.add_iPdu(value)

    def remove_iPdu(self, value: PduTriggeringRefConditional) -> None:
        """
        Removes a single value from iPdus
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            value._detach_from_parent()
            value._parent = None #No parent
            value._refresh_paths() #resets the path
            if value._node.getparent() is not None:
                value._node.getparent().remove(value._node)

    def remove_iPdus(self, values: list[PduTriggeringRefConditional]) -> None:
        """
        Removes a list of value from iPdus
        """
        for value in values:
            self.remove_iPdu(value)

    def new_IPdu(self, name: str=None) -> PduTriggeringRefConditional:
        """
        Creates a new PduTriggeringRefConditional under the PdurIPduGroup.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        PduTriggeringRefConditional_obj = PduTriggeringRefConditional()
        if isinstance(PduTriggeringRefConditional_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        PduTriggeringRefConditional_obj.name = name if isinstance(PduTriggeringRefConditional_obj, Referrable) else None
        self.add_iPdu(PduTriggeringRefConditional_obj)
        if isinstance(PduTriggeringRefConditional_obj, Referrable):
            PduTriggeringRefConditional_obj.set_shortName(name)
        return PduTriggeringRefConditional_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        children.extend(self.__iPdus)
        return children

    def _containment_slot_of(self, child: AutosarNode) -> str | None:
        if child in self.__iPdus:
            return 'iPdus'
        return super()._containment_slot_of(child)

    def add_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'iPdus':
            self.__iPdus[child] = None
        else:
            super().add_child(child, containment_slot)

    def remove_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'iPdus':
            self.__iPdus.pop(child, None)
        else:
            super().remove_child(child, containment_slot)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['CommunicationMode'] = self.__communicationMode
        return property_values

    def is_atp_splitable(self) -> bool:
        return True

    def _save_contents(self):
        """
        Saves the content of PdurIPduGroup node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_FibexElement()
        self._save_scalar_element('COMMUNICATION-MODE', 'communicationMode', str(self.__communicationMode) if self.__communicationMode is not None else None, create_after_nodes = ['VARIATION-POINT', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'] + self._insert_after_tags)
        self._save_child_collection('I-PDUS', None, self.__iPdus, self._insert_after_tags + ['COMMUNICATION-MODE', 'VARIATION-POINT', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])

