class MultiplexedPart(ARObject):
    """
    The StaticPart and the DynamicPart have common properties. Both can be separated in multiple segments within the multiplexed PDU.
    """
    def __init__(self):
        super().__init__()
        self.__segmentPositions = {}

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)

        refCounter = 0
        refCounter = self._build_child_collection(self.__segmentPositions, '{*}SEGMENT-POSITIONS/*', SegmentPosition, file, 'segmentPositions', refCounter)
        return self

    def get_segmentPositions(self) -> list[SegmentPosition]:
        return list(self.__segmentPositions.keys())

    def __bind_segmentPosition(self, value: SegmentPosition) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__segmentPositions.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, SegmentPosition) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of SegmentPosition or its sub-classes'.format(value))

        value._detach_from_parent()
        value._parent = self #set parent
        value.file = self.file
        if value.name is not None:
            value._refresh_paths()
        else:
            value._build_path(elementNameIfShortNameMissing = 'SegmentPosition_@' + str(len(self.get_children()))) #updates the path
        XDT.mark_dirty(value, self, attributesToMakeDirty = ['timestamp', 'checksum'])

    def add_segmentPosition_at_index(self, index: int, value: SegmentPosition) -> None:
        """
        Adds a single value to the segmentPositions at the given index
        """
        if value is not None:
            self.__bind_segmentPosition(value)
            AutosarNode._insert_at_index(self.__segmentPositions, value, index)
            self._sync_add_to_merge_target(value)

    def add_segmentPosition(self, value: SegmentPosition) -> None:
        """
        Adds a single value to the segmentPositions
        """
        if value is not None:
            self.__bind_segmentPosition(value)
            self.__segmentPositions[value] = None
            self._sync_add_to_merge_target(value)

    def set_segmentPositions(self, values: list[SegmentPosition]) -> None:
        """
        Adds a list of ref value to the segmentPositions
        """
        for value in values:
            self.add_segmentPosition(value)

    def remove_segmentPosition(self, value: SegmentPosition) -> None:
        """
        Removes a single value from segmentPositions
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            value._detach_from_parent()
            value._parent = None #No parent
            value._refresh_paths() #resets the path
            if value._node.getparent() is not None:
                value._node.getparent().remove(value._node)

    def remove_segmentPositions(self, values: list[SegmentPosition]) -> None:
        """
        Removes a list of value from segmentPositions
        """
        for value in values:
            self.remove_segmentPosition(value)

    def new_SegmentPosition(self, name: str=None) -> SegmentPosition:
        """
        Creates a new SegmentPosition under the MultiplexedPart.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        SegmentPosition_obj = SegmentPosition()
        if isinstance(SegmentPosition_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        SegmentPosition_obj.name = name if isinstance(SegmentPosition_obj, Referrable) else None
        self.add_segmentPosition(SegmentPosition_obj)
        if isinstance(SegmentPosition_obj, Referrable):
            SegmentPosition_obj.set_shortName(name)
        return SegmentPosition_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        children.extend(self.__segmentPositions)
        return children

    def _containment_slot_of(self, child: AutosarNode) -> str | None:
        if child in self.__segmentPositions:
            return 'segmentPositions'
        return super()._containment_slot_of(child)

    def add_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'segmentPositions':
            self.__segmentPositions[child] = None
        else:
            super().add_child(child, containment_slot)

    def remove_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'segmentPositions':
            self.__segmentPositions.pop(child, None)
        else:
            super().remove_child(child, containment_slot)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        return property_values


    def _save_MultiplexedPart(self):
        """
        Saves the content of MultiplexedPart node
        """
        super()._save_ARObject()
        self._save_child_collection('SEGMENT-POSITIONS', None, self.__segmentPositions, self._insert_after_tags + ['T', 'S'])

class DynamicPart(MultiplexedPart):
    """
    Dynamic part of a multiplexed I-Pdu. , Reserved space which is used to transport varying SignalIPdus at the same position, controlled by the corresponding selectorFieldCode.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'DYNAMIC-PART'
        self._node = etree.Element('DYNAMIC-PART')
        self.__dynamicPartAlternatives = {}
        self.__variationPoint = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)

        refCounter = 0
        refCounter = self._build_child_collection(self.__dynamicPartAlternatives, '{*}DYNAMIC-PART-ALTERNATIVES/*', DynamicPartAlternative, file, 'dynamicPartAlternatives', refCounter)
        self.__variationPoint = self._build_single_child('{*}VARIATION-POINT', VariationPoint, file, 'variationPoint')
        return self

    def get_dynamicPartAlternatives(self) -> list[DynamicPartAlternative]:
        return list(self.__dynamicPartAlternatives.keys())

    def __bind_dynamicPartAlternative(self, value: DynamicPartAlternative) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__dynamicPartAlternatives.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, DynamicPartAlternative) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of DynamicPartAlternative or its sub-classes'.format(value))

        value._detach_from_parent()
        value._parent = self #set parent
        value.file = self.file
        if value.name is not None:
            value._refresh_paths()
        else:
            value._build_path(elementNameIfShortNameMissing = 'DynamicPartAlternative_@' + str(len(self.get_children()))) #updates the path
        XDT.mark_dirty(value, self, attributesToMakeDirty = ['timestamp', 'checksum'])

    def add_dynamicPartAlternative_at_index(self, index: int, value: DynamicPartAlternative) -> None:
        """
        Adds a single value to the dynamicPartAlternatives at the given index
        """
        if value is not None:
            self.__bind_dynamicPartAlternative(value)
            AutosarNode._insert_at_index(self.__dynamicPartAlternatives, value, index)
            self._sync_add_to_merge_target(value)

    def add_dynamicPartAlternative(self, value: DynamicPartAlternative) -> None:
        """
        Adds a single value to the dynamicPartAlternatives
        """
        if value is not None:
            self.__bind_dynamicPartAlternative(value)
            self.__dynamicPartAlternatives[value] = None
            self._sync_add_to_merge_target(value)

    def set_dynamicPartAlternatives(self, values: list[DynamicPartAlternative]) -> None:
        """
        Adds a list of ref value to the dynamicPartAlternatives
        """
        for value in values:
            self.add_dynamicPartAlternative(value)

    def remove_dynamicPartAlternative(self, value: DynamicPartAlternative) -> None:
        """
        Removes a single value from dynamicPartAlternatives
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            value._detach_from_parent()
            value._parent = None #No parent
            value._refresh_paths() #resets the path
            if value._node.getparent() is not None:
                value._node.getparent().remove(value._node)

    def remove_dynamicPartAlternatives(self, values: list[DynamicPartAlternative]) -> None:
        """
        Removes a list of value from dynamicPartAlternatives
        """
        for value in values:
            self.remove_dynamicPartAlternative(value)

    def get_variationPoint(self) -> VariationPoint:
        return self.__variationPoint

    def set_variationPoint(self, value: VariationPoint) -> None:
        """
        Adds a single value to the variationPoint
        """
        if value is not None:
            if isinstance(value, VariationPoint) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of VariationPoint or its sub-classes'.format(value))

            value._detach_from_parent()
            self.__variationPoint = value
            value.file = self.file
            value._parent = self #set parent
            if value.name is not None:
                value._refresh_paths()
            else:
                value._build_path(elementNameIfShortNameMissing = 'VariationPoint_@' + str(len(self.get_children()))) #updates the path
            self._sync_add_to_merge_target(value)
        elif self.__variationPoint is not None:
            self.__variationPoint._detach_from_parent()
            self.__variationPoint = None
        XDT.mark_dirty(self.__variationPoint, self)

    def new_DynamicPartAlternative(self, name: str=None) -> DynamicPartAlternative:
        """
        Creates a new DynamicPartAlternative under the DynamicPart.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        DynamicPartAlternative_obj = DynamicPartAlternative()
        if isinstance(DynamicPartAlternative_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        DynamicPartAlternative_obj.name = name if isinstance(DynamicPartAlternative_obj, Referrable) else None
        self.add_dynamicPartAlternative(DynamicPartAlternative_obj)
        if isinstance(DynamicPartAlternative_obj, Referrable):
            DynamicPartAlternative_obj.set_shortName(name)
        return DynamicPartAlternative_obj

    def new_VariationPoint(self, name: str=None) -> VariationPoint:
        """
        Creates a new VariationPoint under the DynamicPart.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        VariationPoint_obj = VariationPoint()
        if isinstance(VariationPoint_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        VariationPoint_obj.name = name if isinstance(VariationPoint_obj, Referrable) else None
        self.set_variationPoint(VariationPoint_obj)
        if isinstance(VariationPoint_obj, Referrable):
            VariationPoint_obj.set_shortName(name)
        return VariationPoint_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        children.extend(self.__dynamicPartAlternatives)
        if self.__variationPoint is not None:
            children.append(self.__variationPoint)
        return children

    def _containment_slot_of(self, child: AutosarNode) -> str | None:
        if child in self.__dynamicPartAlternatives:
            return 'dynamicPartAlternatives'
        if self.__variationPoint is child:
            return 'variationPoint'
        return super()._containment_slot_of(child)

    def add_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'dynamicPartAlternatives':
            self.__dynamicPartAlternatives[child] = None
        elif containment_slot == 'variationPoint':
            if self.__variationPoint is None:
                self.__variationPoint = child
        else:
            super().add_child(child, containment_slot)

    def remove_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'dynamicPartAlternatives':
            self.__dynamicPartAlternatives.pop(child, None)
        elif containment_slot == 'variationPoint':
            if self.__variationPoint is child:
                self.__variationPoint = None
        else:
            super().remove_child(child, containment_slot)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        return property_values


    def _save_contents(self):
        """
        Saves the content of DynamicPart node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_MultiplexedPart()
        self._save_child_collection('DYNAMIC-PART-ALTERNATIVES', None, self.__dynamicPartAlternatives, self._insert_after_tags + ['SEGMENT-POSITIONS', 'T', 'S'])
        self._save_single_child('VARIATION-POINT', self.__variationPoint, self._insert_after_tags + ['DYNAMIC-PART-ALTERNATIVES', 'SEGMENT-POSITIONS', 'T', 'S'])

class SegmentPosition(ARObject):
    """
    The StaticPart and the DynamicPart can be, separated in multiple segments within the multiplexed PDU. , , The ISignalIPdus are copied bit by bit into the MultiplexedIPdu. If the space of the first segment is 5 bits large than the first 5 bits of the ISignalIPdu are copied into this first segment and so on.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'SEGMENT-POSITION'
        self._node = etree.Element('SEGMENT-POSITION')
        self.__segmentByteOrder = None
        self.__segmentLength = None
        self.__segmentPosition = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        self.__segmentByteOrder = self._read_scalar_element('SEGMENT-BYTE-ORDER', ByteOrderEnum.get)
        self.__segmentLength = self._read_scalar_element('SEGMENT-LENGTH', datatype_utils.get_int_value)
        self.__segmentPosition = self._read_scalar_element('SEGMENT-POSITION', datatype_utils.get_int_value)

        return self

    def get_segmentByteOrder(self) -> ByteOrderEnum:
        return self.__segmentByteOrder

    def set_segmentByteOrder(self, value: ByteOrderEnum) -> None:
        self.__segmentByteOrder = value
        XDT.mark_attribute_dirty('segmentByteOrder', self)

    def get_segmentLength(self) -> int:
        return self.__segmentLength

    def set_segmentLength(self, value: int) -> None:
        self.__segmentLength = value
        XDT.mark_attribute_dirty('segmentLength', self)

    def get_segmentPosition(self) -> int:
        return self.__segmentPosition

    def set_segmentPosition(self, value: int) -> None:
        self.__segmentPosition = value
        XDT.mark_attribute_dirty('segmentPosition', self)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['SegmentByteOrder'] = self.__segmentByteOrder
        property_values['SegmentLength'] = self.__segmentLength
        property_values['SegmentPosition'] = self.__segmentPosition
        return property_values


    def _save_contents(self):
        """
        Saves the content of SegmentPosition node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_ARObject()
        self._save_scalar_element('SEGMENT-BYTE-ORDER', 'segmentByteOrder', self.__segmentByteOrder.literal if self.__segmentByteOrder is not None else None, create_after_nodes = ['T', 'S'] + self._insert_after_tags)
        self._save_scalar_element('SEGMENT-LENGTH', 'segmentLength', str(self.__segmentLength) if self.__segmentLength is not None else None, create_after_nodes = ['SEGMENT-BYTE-ORDER', 'T', 'S'] + self._insert_after_tags)
        self._save_scalar_element('SEGMENT-POSITION', 'segmentPosition', str(self.__segmentPosition) if self.__segmentPosition is not None else None, create_after_nodes = ['SEGMENT-LENGTH', 'SEGMENT-BYTE-ORDER', 'T', 'S'] + self._insert_after_tags)

class DynamicPartAlternative(ARObject):
    """
    One of the Com IPdu alternatives that are transmitted in the Dynamic Part of the MultiplexedIPdu. The selectorFieldCode, specifies which Com IPdu is contained in the DynamicPart within a, certain transmission of a multiplexed PDU.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'DYNAMIC-PART-ALTERNATIVE'
        self._node = etree.Element('DYNAMIC-PART-ALTERNATIVE')
        self.__initialDynamicPart = None
        self.__selectorFieldCode = None
        self.__iPdu = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        self.__initialDynamicPart = self._read_scalar_element('INITIAL-DYNAMIC-PART', datatype_utils.get_bool_value)
        self.__selectorFieldCode = self._read_scalar_element('SELECTOR-FIELD-CODE', datatype_utils.get_int_value)

        return self

    def _resolve_references(self):
        super()._resolve_references()
        self.__iPdu = self._resolve_single_reference('{*}I-PDU-REF', self.__iPdu)

    def get_initialDynamicPart(self) -> bool:
        return self.__initialDynamicPart

    def set_initialDynamicPart(self, value: bool) -> None:
        self.__initialDynamicPart = value
        XDT.mark_attribute_dirty('initialDynamicPart', self)

    def get_selectorFieldCode(self) -> int:
        return self.__selectorFieldCode

    def set_selectorFieldCode(self, value: int) -> None:
        self.__selectorFieldCode = value
        XDT.mark_attribute_dirty('selectorFieldCode', self)

    def get_iPdu(self) -> ISignalIPdu:
        return self.__iPdu

    def set_iPdu(self, value: ISignalIPdu) -> None:
        """
        Adds a single value to the iPdu
        """
        if value is not None:
            if isinstance(value, ISignalIPdu) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of ISignalIPdu or its sub-classes'.format(value))
            if self.__iPdu is not None and self.__iPdu.is_proxy() is False:
                self.__iPdu.referenced_by.remove(self)
            self.__iPdu = value
            value.referenced_by.add(self)
        elif self.__iPdu is not None:
            if self.__iPdu.is_proxy() is False:
                self.__iPdu.referenced_by.remove(self)
            self.__iPdu = None
        XDT.mark_dirty(self.__iPdu, self)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['InitialDynamicPart'] = self.__initialDynamicPart
        property_values['SelectorFieldCode'] = self.__selectorFieldCode
        property_values['IPdu'] = self.__iPdu
        return property_values


    def _save_contents(self):
        """
        Saves the content of DynamicPartAlternative node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_ARObject()
