class MultiplexedIPdu(IPdu):
    """
    A MultiplexedPdu (i.e. NOT a COM I-PDU) contains a DynamicPart, an optional StaticPart and a selectorField. In case of multiplexing this IPdu is routed between the Pdu Multiplexer and the Interface Layer. , , A multiplexer is used to define variable parts within an IPdu that may carry different signals. The receivers of such a IPdu can determine which signalPdus are transmitted by evaluating the selector field, which carries a unique selector code for each sub-part.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'MULTIPLEXED-I-PDU'
        self._node = etree.Element('MULTIPLEXED-I-PDU')
        self.__selectorFieldByteOrder = None
        self.__selectorFieldLength = None
        self.__selectorFieldStartPosition = None
        self.__triggerMode = None
        self.__unusedBitPattern = None
        self.__dynamicParts = {}
        self.__staticParts = {}

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        self.__selectorFieldByteOrder = self._read_scalar_element('SELECTOR-FIELD-BYTE-ORDER', ByteOrderEnum.get)
        self.__selectorFieldLength = self._read_scalar_element('SELECTOR-FIELD-LENGTH', datatype_utils.get_int_value)
        self.__selectorFieldStartPosition = self._read_scalar_element('SELECTOR-FIELD-START-POSITION', datatype_utils.get_int_value)
        self.__triggerMode = self._read_scalar_element('TRIGGER-MODE', TriggerMode.get)
        self.__unusedBitPattern = self._read_scalar_element('UNUSED-BIT-PATTERN', datatype_utils.get_int_value)

        refCounter = 0
        refCounter = self._build_child_collection(self.__dynamicParts, '{*}DYNAMIC-PARTS/*', DynamicPart, file, 'dynamicParts', refCounter)
        refCounter = self._build_child_collection(self.__staticParts, '{*}STATIC-PARTS/*', StaticPart, file, 'staticParts', refCounter)
        return self

    def get_selectorFieldByteOrder(self) -> ByteOrderEnum:
        return self.__selectorFieldByteOrder

    def set_selectorFieldByteOrder(self, value: ByteOrderEnum) -> None:
        self.__selectorFieldByteOrder = value
        XDT.mark_attribute_dirty('selectorFieldByteOrder', self)

    def get_selectorFieldLength(self) -> int:
        return self.__selectorFieldLength

