class TransmissionModeCondition(ARObject):
    """
    Possibility to attach a condition to each signal within an I-PDU., , If at least one condition evaluates to true, TRANSMISSION MODE True shall be used for this I-Pdu. In all other cases, the TRANSMISSION MODE FALSE shall be used.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'TRANSMISSION-MODE-CONDITION'
        self._node = etree.Element('TRANSMISSION-MODE-CONDITION')
        self.__dataFilter = None
        self.__iSignalInIPdu = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)

        self.__dataFilter = self._build_single_child('{*}DATA-FILTER', DataFilter, file, 'dataFilter')
        return self

    def _resolve_references(self):
        super()._resolve_references()
        self.__iSignalInIPdu = self._resolve_single_reference('{*}I-SIGNAL-IN-I-PDU-REF', self.__iSignalInIPdu)

    def get_dataFilter(self) -> DataFilter:
        return self.__dataFilter

    def set_dataFilter(self, value: DataFilter) -> None:
        """
        Adds a single value to the dataFilter
        """
        if value is not None:
            if isinstance(value, DataFilter) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of DataFilter or its sub-classes'.format(value))

            value._detach_from_parent()
            self.__dataFilter = value
            value.file = self.file
            value._parent = self #set parent
            if value.name is not None:
                value._refresh_paths()
            else:
                value._build_path(elementNameIfShortNameMissing = 'DataFilter_@' + str(len(self.get_children()))) #updates the path
            self._sync_add_to_merge_target(value)
        elif self.__dataFilter is not None:
            self.__dataFilter._detach_from_parent()
            self.__dataFilter = None
        XDT.mark_dirty(self.__dataFilter, self)

    def get_iSignalInIPdu(self) -> ISignalToIPduMapping:
        return self.__iSignalInIPdu

    def set_iSignalInIPdu(self, value: ISignalToIPduMapping) -> None:
        """
        Adds a single value to the iSignalInIPdu
        """
        if value is not None:
            if isinstance(value, ISignalToIPduMapping) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of ISignalToIPduMapping or its sub-classes'.format(value))
            if self.__iSignalInIPdu is not None and self.__iSignalInIPdu.is_proxy() is False:
                self.__iSignalInIPdu.referenced_by.remove(self)
            self.__iSignalInIPdu = value
            value.referenced_by.add(self)
        elif self.__iSignalInIPdu is not None:
            if self.__iSignalInIPdu.is_proxy() is False:
                self.__iSignalInIPdu.referenced_by.remove(self)
            self.__iSignalInIPdu = None
        XDT.mark_dirty(self.__iSignalInIPdu, self)

    def new_DataFilter(self, name: str=None) -> DataFilter:
        """
        Creates a new DataFilter under the TransmissionModeCondition.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        DataFilter_obj = DataFilter()
        if isinstance(DataFilter_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        DataFilter_obj.name = name if isinstance(DataFilter_obj, Referrable) else None
        self.set_dataFilter(DataFilter_obj)
        if isinstance(DataFilter_obj, Referrable):
            DataFilter_obj.set_shortName(name)
        return DataFilter_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        if self.__dataFilter is not None:
            children.append(self.__dataFilter)
        return children

    def _containment_slot_of(self, child: AutosarNode) -> str | None:
        if self.__dataFilter is child:
            return 'dataFilter'
        return super()._containment_slot_of(child)

    def add_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'dataFilter':
            if self.__dataFilter is None:
                self.__dataFilter = child
        else:
            super().add_child(child, containment_slot)

    def remove_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'dataFilter':
            if self.__dataFilter is child:
                self.__dataFilter = None
        else:
            super().remove_child(child, containment_slot)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['ISignalInIPdu'] = self.__iSignalInIPdu
        return property_values


    def _save_contents(self):
        """
        Saves the content of TransmissionModeCondition node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_ARObject()
        self._save_single_child('DATA-FILTER', self.__dataFilter, self._insert_after_tags + ['T', 'S'])
        self._save_single_reference('I-SIGNAL-IN-I-PDU-REF', self.__iSignalInIPdu, self._insert_after_tags + ['DATA-FILTER', 'T', 'S'])

class TransmissionModeTiming(ARObject):
    """
    If the COM Transmission Mode is false the timing is aggregated by the TransmissionModeTiming element in the role of transmissionModeFalseTiming. If the COM Transmission Mode is true the timing is aggregated by the TransmissionModeTiming element in the role of transmissionModeTrueTiming.  , , COM supports the following Transmission Modes: , * Periodic (Cyclic Timing), * Direct /n-times (EventControlledTiming), * Mixed (Cyclic and EventControlledTiming are assigned), * None (no timing is assigned)
    """
    def __init__(self):
        super().__init__()
        self.tag = 'TRANSMISSION-MODE-TIMING'
        self._node = etree.Element('TRANSMISSION-MODE-TIMING')
        self.__cyclicTiming = None
        self.__eventControlledTiming = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)

        self.__cyclicTiming = self._build_single_child('{*}CYCLIC-TIMING', CyclicTiming, file, 'cyclicTiming')
        self.__eventControlledTiming = self._build_single_child('{*}EVENT-CONTROLLED-TIMING', EventControlledTiming, file, 'eventControlledTiming')
        return self

    def get_cyclicTiming(self) -> CyclicTiming:
        return self.__cyclicTiming

    def set_cyclicTiming(self, value: CyclicTiming) -> None:
        """
        Adds a single value to the cyclicTiming
        """
        if value is not None:
            if isinstance(value, CyclicTiming) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of CyclicTiming or its sub-classes'.format(value))

            value._detach_from_parent()
            self.__cyclicTiming = value
            value.file = self.file
            value._parent = self #set parent
            if value.name is not None:
                value._refresh_paths()
            else:
                value._build_path(elementNameIfShortNameMissing = 'CyclicTiming_@' + str(len(self.get_children()))) #updates the path
            self._sync_add_to_merge_target(value)
        elif self.__cyclicTiming is not None:
            self.__cyclicTiming._detach_from_parent()
            self.__cyclicTiming = None
        XDT.mark_dirty(self.__cyclicTiming, self)

    def get_eventControlledTiming(self) -> EventControlledTiming:
        return self.__eventControlledTiming

