class ScheduleTableEntry(ARObject):
    """
    Table entry in a LinScheduleTable. Specifies what will be done in the frame slot.
    """
    def __init__(self):
        super().__init__()
        self.__delay = None
        self.__positionInTable = None
        self.__introduction = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        self.__delay = self._read_scalar_element('DELAY', datatype_utils.get_float_value)
        self.__positionInTable = self._read_scalar_element('POSITION-IN-TABLE', datatype_utils.get_int_value)

        self.__introduction = self._build_single_child('{*}INTRODUCTION', DocumentationBlock, file, 'introduction')
        return self

    def get_delay(self) -> float:
        return self.__delay

    def set_delay(self, value: float) -> None:
        self.__delay = value
        XDT.mark_attribute_dirty('delay', self)

    def get_positionInTable(self) -> int:
        return self.__positionInTable

    def set_positionInTable(self, value: int) -> None:
        self.__positionInTable = value
        XDT.mark_attribute_dirty('positionInTable', self)

    def get_introduction(self) -> DocumentationBlock:
        return self.__introduction

    def set_introduction(self, value: DocumentationBlock) -> None:
        """
        Adds a single value to the introduction
        """
        if value is not None:
            if isinstance(value, DocumentationBlock) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of DocumentationBlock or its sub-classes'.format(value))

            value._detach_from_parent()
            self.__introduction = value
            value.file = self.file
            value._parent = self #set parent
            if value.name is not None:
                value._refresh_paths()
            else:
                value._build_path(elementNameIfShortNameMissing = 'DocumentationBlock_@' + str(len(self.get_children()))) #updates the path
            self._sync_add_to_merge_target(value)
        elif self.__introduction is not None:
            self.__introduction._detach_from_parent()
            self.__introduction = None
        XDT.mark_dirty(self.__introduction, self)

    def new_Introduction(self, name: str=None) -> DocumentationBlock:
        """
        Creates a new DocumentationBlock under the ScheduleTableEntry.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        DocumentationBlock_obj = DocumentationBlock()
        if isinstance(DocumentationBlock_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        DocumentationBlock_obj.name = name if isinstance(DocumentationBlock_obj, Referrable) else None
        self.set_introduction(DocumentationBlock_obj)
        if isinstance(DocumentationBlock_obj, Referrable):
            DocumentationBlock_obj.set_shortName(name)
        return DocumentationBlock_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        if self.__introduction is not None:
            children.append(self.__introduction)
        return children

    def _containment_slot_of(self, child: AutosarNode) -> str | None:
        if self.__introduction is child:
            return 'introduction'
        return super()._containment_slot_of(child)

    def add_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'introduction':
            if self.__introduction is None:
                self.__introduction = child
        else:
            super().add_child(child, containment_slot)

    def remove_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'introduction':
            if self.__introduction is child:
                self.__introduction = None
        else:
            super().remove_child(child, containment_slot)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['Delay'] = self.__delay
        property_values['PositionInTable'] = self.__positionInTable
        return property_values


    def _save_ScheduleTableEntry(self):
        """
        Saves the content of ScheduleTableEntry node
        """
        super()._save_ARObject()
        self._save_single_child('INTRODUCTION', self.__introduction, self._insert_after_tags + ['T', 'S'])
        self._save_scalar_element('DELAY', 'delay', str(self.__delay) if self.__delay is not None else None, create_after_nodes = ['INTRODUCTION', 'T', 'S'] + self._insert_after_tags)
        self._save_scalar_element('POSITION-IN-TABLE', 'positionInTable', str(self.__positionInTable) if self.__positionInTable is not None else None, create_after_nodes = ['DELAY', 'INTRODUCTION', 'T', 'S'] + self._insert_after_tags)

