class FrameMapping(ARObject):
    """
    The entire source frame is mapped as it is onto the target frame (what in general is only possible inside of a common platform). In this case source and target frame should be the identical object., , Each pair consists in a SOURCE and a TARGET referencing to a FrameTriggering., , The Frame Mapping is not supported by the Autosar BSW. The existence is optional and has been incorporated into the System Template mainly for compatibility in order to allow interchange between FIBEX and AUTOSAR descriptions.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'FRAME-MAPPING'
        self._node = etree.Element('FRAME-MAPPING')
        self.__introduction = None
        self.__sourceFrame = None
        self.__targetFrame = None
        self.__variationPoint = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)

        self.__introduction = self._build_single_child('{*}INTRODUCTION', DocumentationBlock, file, 'introduction')
        self.__variationPoint = self._build_single_child('{*}VARIATION-POINT', VariationPoint, file, 'variationPoint')
        return self

    def _resolve_references(self):
        super()._resolve_references()
        self.__sourceFrame = self._resolve_single_reference('{*}SOURCE-FRAME-REF', self.__sourceFrame)
        self.__targetFrame = self._resolve_single_reference('{*}TARGET-FRAME-REF', self.__targetFrame)

    def get_introduction(self) -> DocumentationBlock:
        return self.__introduction

    def set_introduction(self, value: DocumentationBlock) -> None:
        """
        Adds a single value to the introduction
        """
        if value is not None:
            if isinstance(value, DocumentationBlock) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of DocumentationBlock or its sub-classes'.format(value))

            value._detach_from_parent()
            self.__introduction = value
            value.file = self.file
            value._parent = self #set parent
            if value.name is not None:
                value._refresh_paths()
            else:
                value._build_path(elementNameIfShortNameMissing = 'DocumentationBlock_@' + str(len(self.get_children()))) #updates the path
            self._sync_add_to_merge_target(value)
        elif self.__introduction is not None:
            self.__introduction._detach_from_parent()
            self.__introduction = None
        XDT.mark_dirty(self.__introduction, self)

    def get_sourceFrame(self) -> FrameTriggering:
        return self.__sourceFrame

    def set_sourceFrame(self, value: FrameTriggering) -> None:
        """
        Adds a single value to the sourceFrame
        """
        if value is not None:
            if isinstance(value, FrameTriggering) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of FrameTriggering or its sub-classes'.format(value))
            if self.__sourceFrame is not None and self.__sourceFrame.is_proxy() is False:
                self.__sourceFrame.referenced_by.remove(self)
            self.__sourceFrame = value
            value.referenced_by.add(self)
        elif self.__sourceFrame is not None:
            if self.__sourceFrame.is_proxy() is False:
                self.__sourceFrame.referenced_by.remove(self)
            self.__sourceFrame = None
        XDT.mark_dirty(self.__sourceFrame, self)

    def get_targetFrame(self) -> FrameTriggering:
        return self.__targetFrame

    def set_targetFrame(self, value: FrameTriggering) -> None:
        """
        Adds a single value to the targetFrame
        """
        if value is not None:
            if isinstance(value, FrameTriggering) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of FrameTriggering or its sub-classes'.format(value))
            if self.__targetFrame is not None and self.__targetFrame.is_proxy() is False:
                self.__targetFrame.referenced_by.remove(self)
            self.__targetFrame = value
            value.referenced_by.add(self)
        elif self.__targetFrame is not None:
            if self.__targetFrame.is_proxy() is False:
                self.__targetFrame.referenced_by.remove(self)
            self.__targetFrame = None
        XDT.mark_dirty(self.__targetFrame, self)

    def get_variationPoint(self) -> VariationPoint:
        return self.__variationPoint

    def set_variationPoint(self, value: VariationPoint) -> None:
        """
        Adds a single value to the variationPoint
        """
        if value is not None:
            if isinstance(value, VariationPoint) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of VariationPoint or its sub-classes'.format(value))

            value._detach_from_parent()
            self.__variationPoint = value
            value.file = self.file
            value._parent = self #set parent
            if value.name is not None:
                value._refresh_paths()
            else:
                value._build_path(elementNameIfShortNameMissing = 'VariationPoint_@' + str(len(self.get_children()))) #updates the path
            self._sync_add_to_merge_target(value)
        elif self.__variationPoint is not None:
            self.__variationPoint._detach_from_parent()
            self.__variationPoint = None
        XDT.mark_dirty(self.__variationPoint, self)

    def new_VariationPoint(self, name: str=None) -> VariationPoint:
        """
        Creates a new VariationPoint under the FrameMapping.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        VariationPoint_obj = VariationPoint()
        if isinstance(VariationPoint_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        VariationPoint_obj.name = name if isinstance(VariationPoint_obj, Referrable) else None
        self.set_variationPoint(VariationPoint_obj)
        if isinstance(VariationPoint_obj, Referrable):
            VariationPoint_obj.set_shortName(name)
        return VariationPoint_obj

    def new_Introduction(self, name: str=None) -> DocumentationBlock:
        """
        Creates a new DocumentationBlock under the FrameMapping.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        DocumentationBlock_obj = DocumentationBlock()
        if isinstance(DocumentationBlock_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        DocumentationBlock_obj.name = name if isinstance(DocumentationBlock_obj, Referrable) else None
        self.set_introduction(DocumentationBlock_obj)
        if isinstance(DocumentationBlock_obj, Referrable):
            DocumentationBlock_obj.set_shortName(name)
        return DocumentationBlock_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        if self.__introduction is not None:
            children.append(self.__introduction)
        if self.__variationPoint is not None:
            children.append(self.__variationPoint)
        return children

    def _containment_slot_of(self, child: AutosarNode) -> str | None:
        if self.__introduction is child:
            return 'introduction'
        if self.__variationPoint is child:
            return 'variationPoint'
        return super()._containment_slot_of(child)

    def add_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'introduction':
            if self.__introduction is None:
                self.__introduction = child
        elif containment_slot == 'variationPoint':
            if self.__variationPoint is None:
                self.__variationPoint = child
        else:
            super().add_child(child, containment_slot)

    def remove_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'introduction':
            if self.__introduction is child:
                self.__introduction = None
        elif containment_slot == 'variationPoint':
            if self.__variationPoint is child:
                self.__variationPoint = None
        else:
            super().remove_child(child, containment_slot)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['SourceFrame'] = self.__sourceFrame
        property_values['TargetFrame'] = self.__targetFrame
        return property_values


    def _save_contents(self):
        """
        Saves the content of FrameMapping node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_ARObject()
        self._save_single_child('INTRODUCTION', self.__introduction, self._insert_after_tags + ['T', 'S'])
        self._save_single_reference('SOURCE-FRAME-REF', self.__sourceFrame, self._insert_after_tags + ['INTRODUCTION', 'T', 'S'])
        self._save_single_reference('TARGET-FRAME-REF', self.__targetFrame, self._insert_after_tags + ['SOURCE-FRAME-REF', 'INTRODUCTION', 'T', 'S'])
        self._save_single_child('VARIATION-POINT', self.__variationPoint, self._insert_after_tags + ['TARGET-FRAME-REF', 'SOURCE-FRAME-REF', 'INTRODUCTION', 'T', 'S'])

class Gateway(FibexElement):
    """
    A gateway is an ECU that is connected to two or more clusters (channels, but not redundant), and performs a frame, Pdu or signal mapping between them.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'GATEWAY'
        self._node = etree.Element('GATEWAY')
        self.__ecu = None
        self.__frameMappings = {}
        self.__iPduMappings = {}
        self.__signalMappings = {}

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)

        refCounter = 0
        refCounter = self._build_child_collection(self.__frameMappings, '{*}FRAME-MAPPINGS/*', FrameMapping, file, 'frameMappings', refCounter)
        refCounter = self._build_child_collection(self.__iPduMappings, '{*}I-PDU-MAPPINGS/*', IPduMapping, file, 'iPduMappings', refCounter)
        refCounter = self._build_child_collection(self.__signalMappings, '{*}SIGNAL-MAPPINGS/*', ISignalMapping, file, 'signalMappings', refCounter)
        return self

    def _resolve_references(self):
        super()._resolve_references()
        self.__ecu = self._resolve_single_reference('{*}ECU-REF', self.__ecu)

    def get_ecu(self) -> EcuInstance:
        return self.__ecu

    def set_ecu(self, value: EcuInstance) -> None:
        """
        Adds a single value to the ecu
        """
        if value is not None:
            if isinstance(value, EcuInstance) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of EcuInstance or its sub-classes'.format(value))
            if self.__ecu is not None and self.__ecu.is_proxy() is False:
                self.__ecu.referenced_by.remove(self)
            self.__ecu = value
            value.referenced_by.add(self)
        elif self.__ecu is not None:
            if self.__ecu.is_proxy() is False:
                self.__ecu.referenced_by.remove(self)
            self.__ecu = None
        XDT.mark_dirty(self.__ecu, self)

    def get_frameMappings(self) -> list[FrameMapping]:
        return list(self.__frameMappings.keys())

    def __bind_frameMapping(self, value: FrameMapping) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__frameMappings.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, FrameMapping) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of FrameMapping or its sub-classes'.format(value))

        value._detach_from_parent()
        value._parent = self #set parent
        value.file = self.file
        if value.name is not None:
            value._refresh_paths()
        else:
            value._build_path(elementNameIfShortNameMissing = 'FrameMapping_@' + str(len(self.get_children()))) #updates the path
        XDT.mark_dirty(value, self, attributesToMakeDirty = ['timestamp', 'checksum'])

    def add_frameMapping_at_index(self, index: int, value: FrameMapping) -> None:
        """
        Adds a single value to the frameMappings at the given index
        """
        if value is not None:
            self.__bind_frameMapping(value)
            AutosarNode._insert_at_index(self.__frameMappings, value, index)
            self._sync_add_to_merge_target(value)

    def add_frameMapping(self, value: FrameMapping) -> None:
        """
        Adds a single value to the frameMappings
        """
        if value is not None:
            self.__bind_frameMapping(value)
            self.__frameMappings[value] = None
            self._sync_add_to_merge_target(value)

    def set_frameMappings(self, values: list[FrameMapping]) -> None:
        """
        Adds a list of ref value to the frameMappings
        """
        for value in values:
            self.add_frameMapping(value)

    def remove_frameMapping(self, value: FrameMapping) -> None:
        """
        Removes a single value from frameMappings
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            value._detach_from_parent()
            value._parent = None #No parent
            value._refresh_paths() #resets the path
            if value._node.getparent() is not None:
                value._node.getparent().remove(value._node)

    def remove_frameMappings(self, values: list[FrameMapping]) -> None:
        """
        Removes a list of value from frameMappings
        """
        for value in values:
            self.remove_frameMapping(value)

