class IPSecConfig(ARObject):
    """
    IPsec is a protocol that is designed to provide "end-to-end" cryptographically-based security for IP network connections.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'IP-SEC-CONFIG'
        self._node = etree.Element('IP-SEC-CONFIG')
        self.__ipSecConfigProps = None
        self.__ipSecRules = {}

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)

        refCounter = 0
        refCounter = self._build_child_collection(self.__ipSecRules, '{*}IP-SEC-RULES/*', IPSecRule, file, 'ipSecRules', refCounter)
        return self

    def _resolve_references(self):
        super()._resolve_references()
        self.__ipSecConfigProps = self._resolve_single_reference('{*}IP-SEC-CONFIG-PROPS-REF', self.__ipSecConfigProps)

    def get_ipSecConfigProps(self) -> IPSecConfigProps:
        return self.__ipSecConfigProps

    def set_ipSecConfigProps(self, value: IPSecConfigProps) -> None:
        """
        Adds a single value to the ipSecConfigProps
        """
        if value is not None:
            if isinstance(value, IPSecConfigProps) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of IPSecConfigProps or its sub-classes'.format(value))
            if self.__ipSecConfigProps is not None and self.__ipSecConfigProps.is_proxy() is False:
                self.__ipSecConfigProps.referenced_by.remove(self)
            self.__ipSecConfigProps = value
            value.referenced_by.add(self)
        elif self.__ipSecConfigProps is not None:
            if self.__ipSecConfigProps.is_proxy() is False:
                self.__ipSecConfigProps.referenced_by.remove(self)
            self.__ipSecConfigProps = None
        XDT.mark_dirty(self.__ipSecConfigProps, self)

    def get_ipSecRules(self) -> list[IPSecRule]:
        return list(self.__ipSecRules.keys())

    def __bind_ipSecRule(self, value: IPSecRule) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__ipSecRules.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, IPSecRule) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of IPSecRule or its sub-classes'.format(value))

        value._detach_from_parent()
        value._parent = self #set parent
        value.file = self.file
        if value.name is not None:
            value._refresh_paths()
        else:
            value._build_path(elementNameIfShortNameMissing = 'IPSecRule_@' + str(len(self.get_children()))) #updates the path
        XDT.mark_dirty(value, self, attributesToMakeDirty = ['uuid', 'category', 'shortName', 'timestamp', 'checksum'])

    def add_ipSecRule_at_index(self, index: int, value: IPSecRule) -> None:
        """
        Adds a single value to the ipSecRules at the given index
        """
        if value is not None:
            self.__bind_ipSecRule(value)
            AutosarNode._insert_at_index(self.__ipSecRules, value, index)
            self._sync_add_to_merge_target(value)

    def add_ipSecRule(self, value: IPSecRule) -> None:
        """
        Adds a single value to the ipSecRules
        """
        if value is not None:
            self.__bind_ipSecRule(value)
            self.__ipSecRules[value] = None
            self._sync_add_to_merge_target(value)

    def set_ipSecRules(self, values: list[IPSecRule]) -> None:
        """
        Adds a list of ref value to the ipSecRules
        """
        for value in values:
            self.add_ipSecRule(value)

    def remove_ipSecRule(self, value: IPSecRule) -> None:
        """
        Removes a single value from ipSecRules
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            value._detach_from_parent()
            value._parent = None #No parent
            value._refresh_paths() #resets the path
            if value._node.getparent() is not None:
                value._node.getparent().remove(value._node)

    def remove_ipSecRules(self, values: list[IPSecRule]) -> None:
        """
        Removes a list of value from ipSecRules
        """
        for value in values:
            self.remove_ipSecRule(value)

    def new_IPSecRule(self, name: str=None) -> IPSecRule:
        """
        Creates a new IPSecRule under the IPSecConfig.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        IPSecRule_obj = IPSecRule()
        if isinstance(IPSecRule_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        IPSecRule_obj.name = name if isinstance(IPSecRule_obj, Referrable) else None
        self.add_ipSecRule(IPSecRule_obj)
        if isinstance(IPSecRule_obj, Referrable):
            IPSecRule_obj.set_shortName(name)
        return IPSecRule_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        children.extend(self.__ipSecRules)
        return children

    def _containment_slot_of(self, child: AutosarNode) -> str | None:
        if child in self.__ipSecRules:
            return 'ipSecRules'
        return super()._containment_slot_of(child)

    def add_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'ipSecRules':
            self.__ipSecRules[child] = None
        else:
            super().add_child(child, containment_slot)

    def remove_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'ipSecRules':
            self.__ipSecRules.pop(child, None)
        else:
            super().remove_child(child, containment_slot)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['IpSecConfigProps'] = self.__ipSecConfigProps
        return property_values


    def _save_contents(self):
        """
        Saves the content of IPSecConfig node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_ARObject()
        self._save_single_reference('IP-SEC-CONFIG-PROPS-REF', self.__ipSecConfigProps, self._insert_after_tags + ['T', 'S'])
        self._save_child_collection('IP-SEC-RULES', None, self.__ipSecRules, self._insert_after_tags + ['IP-SEC-CONFIG-PROPS-REF', 'T', 'S'])

