        self._save_single_reference('COMMUNICATION-CONNECTOR-REF', self.__communicationConnector, self._insert_after_tags + ['ALL-NM-MESSAGES-KEEP-AWAKE', 'VARIATION-POINT', 'TX-NM-PDU-REFS', 'RX-NM-PDU-REFS', 'NM-PASSIVE-MODE-ENABLED', 'NM-NODE-ID', 'NM-IF-ECU-REF', 'NM-COORDINATOR-ROLE', 'NM-COORD-CLUSTER', 'MACHINE-REF', 'CONTROLLER-REF', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])
