class J1939NmNode(NmNode):
    """
    J1939 specific NM Node attributes.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'J-1939-NM-NODE'
        self._node = etree.Element('J-1939-NM-NODE')
        self.__nodeName = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)

        self.__nodeName = self._build_single_child('{*}NODE-NAME', J1939NodeName, file, 'nodeName')
        return self

    def get_nodeName(self) -> J1939NodeName:
        return self.__nodeName

    def set_nodeName(self, value: J1939NodeName) -> None:
        """
        Adds a single value to the nodeName
        """
        if value is not None:
            if isinstance(value, J1939NodeName) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of J1939NodeName or its sub-classes'.format(value))

            value._detach_from_parent()
            self.__nodeName = value
            value.file = self.file
            value._parent = self #set parent
            if value.name is not None:
                value._refresh_paths()
            else:
                value._build_path(elementNameIfShortNameMissing = 'J1939NodeName_@' + str(len(self.get_children()))) #updates the path
            self._sync_add_to_merge_target(value)
        elif self.__nodeName is not None:
            self.__nodeName._detach_from_parent()
            self.__nodeName = None
        XDT.mark_dirty(self.__nodeName, self)

    def new_NodeName(self, name: str=None) -> J1939NodeName:
        """
        Creates a new J1939NodeName under the J1939NmNode.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        J1939NodeName_obj = J1939NodeName()
        if isinstance(J1939NodeName_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        J1939NodeName_obj.name = name if isinstance(J1939NodeName_obj, Referrable) else None
        self.set_nodeName(J1939NodeName_obj)
        if isinstance(J1939NodeName_obj, Referrable):
            J1939NodeName_obj.set_shortName(name)
        return J1939NodeName_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        if self.__nodeName is not None:
            children.append(self.__nodeName)
        return children

    def _containment_slot_of(self, child: AutosarNode) -> str | None:
        if self.__nodeName is child:
            return 'nodeName'
        return super()._containment_slot_of(child)

    def add_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'nodeName':
            if self.__nodeName is None:
                self.__nodeName = child
        else:
            super().add_child(child, containment_slot)

    def remove_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'nodeName':
            if self.__nodeName is child:
                self.__nodeName = None
        else:
            super().remove_child(child, containment_slot)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        return property_values


    def _save_contents(self):
        """
        Saves the content of J1939NmNode node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_NmNode()
        self._save_single_child('NODE-NAME', self.__nodeName, self._insert_after_tags + ['VARIATION-POINT', 'TX-NM-PDU-REFS', 'RX-NM-PDU-REFS', 'NM-PASSIVE-MODE-ENABLED', 'NM-NODE-ID', 'NM-IF-ECU-REF', 'NM-COORDINATOR-ROLE', 'NM-COORD-CLUSTER', 'MACHINE-REF', 'CONTROLLER-REF', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])

