class EthTpConfig(TpConfig):
    """
    This element defines which PduTriggerings shall be handled using "TP" semantics.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'ETH-TP-CONFIG'
        self._node = etree.Element('ETH-TP-CONFIG')
        self.__tpConnections = {}

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)

        refCounter = 0
        refCounter = self._build_child_collection(self.__tpConnections, '{*}TP-CONNECTIONS/*', EthTpConnection, file, 'tpConnections', refCounter)
        return self

    def get_tpConnections(self) -> list[EthTpConnection]:
        return list(self.__tpConnections.keys())

    def __bind_tpConnection(self, value: EthTpConnection) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__tpConnections.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, EthTpConnection) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of EthTpConnection or its sub-classes'.format(value))

        value._detach_from_parent()
        value._parent = self #set parent
        value.file = self.file
        if value.name is not None:
            value._refresh_paths()
        else:
            value._build_path(elementNameIfShortNameMissing = 'EthTpConnection_@' + str(len(self.get_children()))) #updates the path
        XDT.mark_dirty(value, self, attributesToMakeDirty = ['timestamp', 'checksum'])

    def add_tpConnection_at_index(self, index: int, value: EthTpConnection) -> None:
        """
        Adds a single value to the tpConnections at the given index
        """
        if value is not None:
            self.__bind_tpConnection(value)
            AutosarNode._insert_at_index(self.__tpConnections, value, index)
            self._sync_add_to_merge_target(value)

    def add_tpConnection(self, value: EthTpConnection) -> None:
        """
        Adds a single value to the tpConnections
        """
        if value is not None:
            self.__bind_tpConnection(value)
            self.__tpConnections[value] = None
            self._sync_add_to_merge_target(value)

    def set_tpConnections(self, values: list[EthTpConnection]) -> None:
        """
        Adds a list of ref value to the tpConnections
        """
        for value in values:
            self.add_tpConnection(value)

    def remove_tpConnection(self, value: EthTpConnection) -> None:
        """
        Removes a single value from tpConnections
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            value._detach_from_parent()
            value._parent = None #No parent
            value._refresh_paths() #resets the path
            if value._node.getparent() is not None:
                value._node.getparent().remove(value._node)

    def remove_tpConnections(self, values: list[EthTpConnection]) -> None:
        """
        Removes a list of value from tpConnections
        """
        for value in values:
            self.remove_tpConnection(value)

    def new_TpConnection(self, name: str=None) -> EthTpConnection:
        """
        Creates a new EthTpConnection under the EthTpConfig.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        EthTpConnection_obj = EthTpConnection()
        if isinstance(EthTpConnection_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        EthTpConnection_obj.name = name if isinstance(EthTpConnection_obj, Referrable) else None
        self.add_tpConnection(EthTpConnection_obj)
        if isinstance(EthTpConnection_obj, Referrable):
            EthTpConnection_obj.set_shortName(name)
        return EthTpConnection_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        children.extend(self.__tpConnections)
        return children

    def _containment_slot_of(self, child: AutosarNode) -> str | None:
        if child in self.__tpConnections:
            return 'tpConnections'
        return super()._containment_slot_of(child)

    def add_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'tpConnections':
            self.__tpConnections[child] = None
        else:
            super().add_child(child, containment_slot)

    def remove_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'tpConnections':
            self.__tpConnections.pop(child, None)
        else:
            super().remove_child(child, containment_slot)


