class FlexrayArTpConnection(TpConnection):
    """
    A connection within a channel identifies the sender and the receiver of this particular communication., , The FlexRay Autosar Tp module routes a Pdu through this connection.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'FLEXRAY-AR-TP-CONNECTION'
        self._node = etree.Element('FLEXRAY-AR-TP-CONNECTION')
        self.__connectionPrioPdus = None
        self.__directTpSdu = None
        self.__flowControlPdu = None
        self.__multicast = None
        self.__reversedTpSdu = None
        self.__source = None
        self.__targets = {}
        self.__transmitPdus = {}

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        self.__connectionPrioPdus = self._read_scalar_element('CONNECTION-PRIO-PDUS', datatype_utils.get_int_value)

        return self

    def _resolve_references(self):
        super()._resolve_references()
        self.__directTpSdu = self._resolve_single_reference('{*}DIRECT-TP-SDU-REF', self.__directTpSdu)
        self.__flowControlPdu = self._resolve_single_reference('{*}FLOW-CONTROL-PDU-REF', self.__flowControlPdu)
        self.__multicast = self._resolve_single_reference('{*}MULTICAST-REF', self.__multicast)
        self.__reversedTpSdu = self._resolve_single_reference('{*}REVERSED-TP-SDU-REF', self.__reversedTpSdu)
        self.__source = self._resolve_single_reference('{*}SOURCE-REF', self.__source)
        self.__targets = self._resolve_reference_list('{*}TARGET-REFS/*', self.__targets)
        self.__transmitPdus = self._resolve_reference_list('{*}TRANSMIT-PDU-REFS/*', self.__transmitPdus)

    def get_connectionPrioPdus(self) -> int:
        return self.__connectionPrioPdus

    def set_connectionPrioPdus(self, value: int) -> None:
        self.__connectionPrioPdus = value
        XDT.mark_attribute_dirty('connectionPrioPdus', self)

    def get_directTpSdu(self) -> IPdu:
        return self.__directTpSdu

    def set_directTpSdu(self, value: IPdu) -> None:
        """
        Adds a single value to the directTpSdu
        """
        if value is not None:
            if isinstance(value, IPdu) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of IPdu or its sub-classes'.format(value))
            if self.__directTpSdu is not None and self.__directTpSdu.is_proxy() is False:
                self.__directTpSdu.referenced_by.remove(self)
            self.__directTpSdu = value
            value.referenced_by.add(self)
        elif self.__directTpSdu is not None:
            if self.__directTpSdu.is_proxy() is False:
                self.__directTpSdu.referenced_by.remove(self)
            self.__directTpSdu = None
        XDT.mark_dirty(self.__directTpSdu, self)

    def get_flowControlPdu(self) -> NPdu:
        return self.__flowControlPdu

    def set_flowControlPdu(self, value: NPdu) -> None:
        """
        Adds a single value to the flowControlPdu
        """
        if value is not None:
            if isinstance(value, NPdu) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of NPdu or its sub-classes'.format(value))
            if self.__flowControlPdu is not None and self.__flowControlPdu.is_proxy() is False:
                self.__flowControlPdu.referenced_by.remove(self)
            self.__flowControlPdu = value
            value.referenced_by.add(self)
        elif self.__flowControlPdu is not None:
            if self.__flowControlPdu.is_proxy() is False:
                self.__flowControlPdu.referenced_by.remove(self)
            self.__flowControlPdu = None
        XDT.mark_dirty(self.__flowControlPdu, self)

    def get_multicast(self) -> TpAddress:
        return self.__multicast

    def set_multicast(self, value: TpAddress) -> None:
        """
        Adds a single value to the multicast
        """
        if value is not None:
            if isinstance(value, TpAddress) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of TpAddress or its sub-classes'.format(value))
            if self.__multicast is not None and self.__multicast.is_proxy() is False:
                self.__multicast.referenced_by.remove(self)
            self.__multicast = value
            value.referenced_by.add(self)
        elif self.__multicast is not None:
            if self.__multicast.is_proxy() is False:
                self.__multicast.referenced_by.remove(self)
            self.__multicast = None
        XDT.mark_dirty(self.__multicast, self)

    def get_reversedTpSdu(self) -> IPdu:
        return self.__reversedTpSdu

    def set_reversedTpSdu(self, value: IPdu) -> None:
        """
        Adds a single value to the reversedTpSdu
        """
        if value is not None:
            if isinstance(value, IPdu) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of IPdu or its sub-classes'.format(value))
            if self.__reversedTpSdu is not None and self.__reversedTpSdu.is_proxy() is False:
                self.__reversedTpSdu.referenced_by.remove(self)
            self.__reversedTpSdu = value
            value.referenced_by.add(self)
        elif self.__reversedTpSdu is not None:
            if self.__reversedTpSdu.is_proxy() is False:
                self.__reversedTpSdu.referenced_by.remove(self)
            self.__reversedTpSdu = None
        XDT.mark_dirty(self.__reversedTpSdu, self)

    def get_source(self) -> FlexrayArTpNode:
        return self.__source

    def set_source(self, value: FlexrayArTpNode) -> None:
        """
        Adds a single value to the source
        """
        if value is not None:
            if isinstance(value, FlexrayArTpNode) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of FlexrayArTpNode or its sub-classes'.format(value))
            if self.__source is not None and self.__source.is_proxy() is False:
                self.__source.referenced_by.remove(self)
            self.__source = value
            value.referenced_by.add(self)
        elif self.__source is not None:
            if self.__source.is_proxy() is False:
                self.__source.referenced_by.remove(self)
            self.__source = None
        XDT.mark_dirty(self.__source, self)

    def get_targets(self) -> list[FlexrayArTpNode]:
        return list(self.__targets.keys())

    def __bind_target(self, value: FlexrayArTpNode) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__targets.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, FlexrayArTpNode) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of FlexrayArTpNode or its sub-classes'.format(value))

        value.referenced_by.add(self)
        XDT.mark_dirty(value, self)


    def add_target(self, value: FlexrayArTpNode) -> None:
        """
        Adds a single value to the targets
        """
        if value is not None:
            self.__bind_target(value)
            self.__targets[value] = None

    def set_targets(self, values: list[FlexrayArTpNode]) -> None:
        """
        Adds a list of ref value to the targets
        """
        for value in values:
            self.add_target(value)

    def remove_target(self, value: FlexrayArTpNode) -> None:
        """
        Removes a single value from targets
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            self.__targets.pop(value)
            if value.is_proxy() is False:
                value.referenced_by.remove(self)

    def remove_targets(self, values: list[FlexrayArTpNode]) -> None:
        """
        Removes a list of value from targets
        """
        for value in values:
            self.remove_target(value)

    def get_transmitPdus(self) -> list[NPdu]:
        return list(self.__transmitPdus.keys())

    def __bind_transmitPdu(self, value: NPdu) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__transmitPdus.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, NPdu) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of NPdu or its sub-classes'.format(value))

        value.referenced_by.add(self)
        XDT.mark_dirty(value, self)


    def add_transmitPdu(self, value: NPdu) -> None:
        """
        Adds a single value to the transmitPdus
        """
        if value is not None:
            self.__bind_transmitPdu(value)
            self.__transmitPdus[value] = None

    def set_transmitPdus(self, values: list[NPdu]) -> None:
        """
        Adds a list of ref value to the transmitPdus
        """
        for value in values:
            self.add_transmitPdu(value)

    def remove_transmitPdu(self, value: NPdu) -> None:
        """
        Removes a single value from transmitPdus
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            self.__transmitPdus.pop(value)
            if value.is_proxy() is False:
                value.referenced_by.remove(self)

    def remove_transmitPdus(self, values: list[NPdu]) -> None:
        """
        Removes a list of value from transmitPdus
        """
        for value in values:
            self.remove_transmitPdu(value)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['ConnectionPrioPdus'] = self.__connectionPrioPdus
        property_values['DirectTpSdu'] = self.__directTpSdu
        property_values['FlowControlPdu'] = self.__flowControlPdu
        property_values['Multicast'] = self.__multicast
        property_values['ReversedTpSdu'] = self.__reversedTpSdu
        property_values['Source'] = self.__source
        property_values['Targets'] = self.__targets
        property_values['TransmitPdus'] = self.__transmitPdus
        return property_values


    def _save_contents(self):
        """
        Saves the content of FlexrayArTpConnection node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_TpConnection()
        self._save_scalar_element('CONNECTION-PRIO-PDUS', 'connectionPrioPdus', str(self.__connectionPrioPdus) if self.__connectionPrioPdus is not None else None, create_after_nodes = ['IDENT', 'T', 'S'] + self._insert_after_tags)
        self._save_single_reference('DIRECT-TP-SDU-REF', self.__directTpSdu, self._insert_after_tags + ['CONNECTION-PRIO-PDUS', 'IDENT', 'T', 'S'])
        self._save_single_reference('FLOW-CONTROL-PDU-REF', self.__flowControlPdu, self._insert_after_tags + ['DIRECT-TP-SDU-REF', 'CONNECTION-PRIO-PDUS', 'IDENT', 'T', 'S'])
        self._save_single_reference('MULTICAST-REF', self.__multicast, self._insert_after_tags + ['FLOW-CONTROL-PDU-REF', 'DIRECT-TP-SDU-REF', 'CONNECTION-PRIO-PDUS', 'IDENT', 'T', 'S'])
        self._save_single_reference('REVERSED-TP-SDU-REF', self.__reversedTpSdu, self._insert_after_tags + ['MULTICAST-REF', 'FLOW-CONTROL-PDU-REF', 'DIRECT-TP-SDU-REF', 'CONNECTION-PRIO-PDUS', 'IDENT', 'T', 'S'])
        self._save_single_reference('SOURCE-REF', self.__source, self._insert_after_tags + ['REVERSED-TP-SDU-REF', 'MULTICAST-REF', 'FLOW-CONTROL-PDU-REF', 'DIRECT-TP-SDU-REF', 'CONNECTION-PRIO-PDUS', 'IDENT', 'T', 'S'])
        self._save_reference_list('TARGET-REFS', 'TARGET-REF', self.__targets, self._insert_after_tags + ['SOURCE-REF', 'REVERSED-TP-SDU-REF', 'MULTICAST-REF', 'FLOW-CONTROL-PDU-REF', 'DIRECT-TP-SDU-REF', 'CONNECTION-PRIO-PDUS', 'IDENT', 'T', 'S'])
        self._save_reference_list('TRANSMIT-PDU-REFS', 'TRANSMIT-PDU-REF', self.__transmitPdus, self._insert_after_tags + ['TARGET-REFS', 'SOURCE-REF', 'REVERSED-TP-SDU-REF', 'MULTICAST-REF', 'FLOW-CONTROL-PDU-REF', 'DIRECT-TP-SDU-REF', 'CONNECTION-PRIO-PDUS', 'IDENT', 'T', 'S'])

class TpAddress(Identifiable):
    """
    An ECUs TP address on the referenced channel. This represents the diagnostic Address.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'TP-ADDRESS'
        self._node = etree.Element('TP-ADDRESS')
        self.__tpAddress = None
        self.__variationPoint = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        self.__tpAddress = self._read_scalar_element('TP-ADDRESS', datatype_utils.get_int_value)

        self.__variationPoint = self._build_single_child('{*}VARIATION-POINT', VariationPoint, file, 'variationPoint')
        return self

    def get_tpAddress(self) -> int:
        return self.__tpAddress

    def set_tpAddress(self, value: int) -> None:
        self.__tpAddress = value
        XDT.mark_attribute_dirty('tpAddress', self)

    def get_variationPoint(self) -> VariationPoint:
        return self.__variationPoint

    def set_variationPoint(self, value: VariationPoint) -> None:
        """
        Adds a single value to the variationPoint
        """
        if value is not None:
            if isinstance(value, VariationPoint) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of VariationPoint or its sub-classes'.format(value))

            value._detach_from_parent()
            self.__variationPoint = value
            value.file = self.file
            value._parent = self #set parent
            if value.name is not None:
                value._refresh_paths()
            else:
                value._build_path(elementNameIfShortNameMissing = 'VariationPoint_@' + str(len(self.get_children()))) #updates the path
            self._sync_add_to_merge_target(value)
        elif self.__variationPoint is not None:
            self.__variationPoint._detach_from_parent()
            self.__variationPoint = None
        XDT.mark_dirty(self.__variationPoint, self)

    def new_VariationPoint(self, name: str=None) -> VariationPoint:
        """
        Creates a new VariationPoint under the TpAddress.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        VariationPoint_obj = VariationPoint()
        if isinstance(VariationPoint_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        VariationPoint_obj.name = name if isinstance(VariationPoint_obj, Referrable) else None
        self.set_variationPoint(VariationPoint_obj)
        if isinstance(VariationPoint_obj, Referrable):
            VariationPoint_obj.set_shortName(name)
        return VariationPoint_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        if self.__variationPoint is not None:
            children.append(self.__variationPoint)
        return children

    def _containment_slot_of(self, child: AutosarNode) -> str | None:
        if self.__variationPoint is child:
            return 'variationPoint'
        return super()._containment_slot_of(child)

    def add_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'variationPoint':
            if self.__variationPoint is None:
                self.__variationPoint = child
        else:
            super().add_child(child, containment_slot)

    def remove_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'variationPoint':
            if self.__variationPoint is child:
                self.__variationPoint = None
        else:
            super().remove_child(child, containment_slot)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['TpAddress'] = self.__tpAddress
        return property_values


    def _save_contents(self):
        """
        Saves the content of TpAddress node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_Identifiable()
