class FlexrayTpEcu(ARObject):
    """
    ECU specific TP configuration parameters. Each TpEcu element has a reference to exactly one ECUInstance in the topology.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'FLEXRAY-TP-ECU'
        self._node = etree.Element('FLEXRAY-TP-ECU')
        self.__cancellation = None
        self.__cycleTimeMainFunction = None
        self.__fullDuplexEnabled = None
        self.__transmitCancellation = None
        self.__ecuInstance = None
        self.__variationPoint = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        self.__cancellation = self._read_scalar_element('CANCELLATION', datatype_utils.get_bool_value)
        self.__cycleTimeMainFunction = self._read_scalar_element('CYCLE-TIME-MAIN-FUNCTION', datatype_utils.get_float_value)
        self.__fullDuplexEnabled = self._read_scalar_element('FULL-DUPLEX-ENABLED', datatype_utils.get_bool_value)
        self.__transmitCancellation = self._read_scalar_element('TRANSMIT-CANCELLATION', datatype_utils.get_bool_value)

        self.__variationPoint = self._build_single_child('{*}VARIATION-POINT', VariationPoint, file, 'variationPoint')
        return self

