class FlexrayTpNode(Identifiable):
    """
    TP Node (Sender or Receiver) provides the TP Address and the connection to the Topology description.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'FLEXRAY-TP-NODE'
        self._node = etree.Element('FLEXRAY-TP-NODE')
        self.__connectors = {}
        self.__tpAddress = None
        self.__variationPoint = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)

        self.__variationPoint = self._build_single_child('{*}VARIATION-POINT', VariationPoint, file, 'variationPoint')
        return self

    def _resolve_references(self):
        super()._resolve_references()
        self.__connectors = self._resolve_reference_list('{*}CONNECTOR-REFS/*', self.__connectors)
        self.__tpAddress = self._resolve_single_reference('{*}TP-ADDRESS-REF', self.__tpAddress)

    def get_connectors(self) -> list[CommunicationConnector]:
        return list(self.__connectors.keys())

    def __bind_connector(self, value: CommunicationConnector) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__connectors.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, CommunicationConnector) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of CommunicationConnector or its sub-classes'.format(value))

