class J1939TpConnection(TpConnection):
    """
    A J1939TpConnection represents an internal path for the transmission or reception of a Pdu via J1939Tp and describes the sender and the receiver of this particular communication. The J1939Tp module routes a Pdu (J1939 PGN) through the connection.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'J-1939-TP-CONNECTION'
        self._node = etree.Element('J-1939-TP-CONNECTION')
        self.__broadcast = None
        self.__bufferRatio = None
        self.__cancellation = None
        self.__dynamicBs = None
        self.__maxBs = None
        self.__maxExpBs = None
        self.__retry = None
        self.__dataPdu = None
        self.__directPdu = None
        self.__flowControlPdus = {}
        self.__receivers = {}
        self.__tpPgs = {}
        self.__tpSdus = {}
        self.__transmitter = None
        self.__variationPoint = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        self.__broadcast = self._read_scalar_element('BROADCAST', datatype_utils.get_bool_value)
        self.__bufferRatio = self._read_scalar_element('BUFFER-RATIO', datatype_utils.get_int_value)
        self.__cancellation = self._read_scalar_element('CANCELLATION', datatype_utils.get_bool_value)
        self.__dynamicBs = self._read_scalar_element('DYNAMIC-BS', datatype_utils.get_bool_value)
        self.__maxBs = self._read_scalar_element('MAX-BS', datatype_utils.get_int_value)
        self.__maxExpBs = self._read_scalar_element('MAX-EXP-BS', datatype_utils.get_int_value)
        self.__retry = self._read_scalar_element('RETRY', datatype_utils.get_bool_value)

        refCounter = 0
        refCounter = self._build_child_collection(self.__tpPgs, '{*}TP-PGS/*', J1939TpPg, file, 'tpPgs', refCounter)
        self.__variationPoint = self._build_single_child('{*}VARIATION-POINT', VariationPoint, file, 'variationPoint')
        return self

    def _resolve_references(self):
        super()._resolve_references()
        self.__dataPdu = self._resolve_single_reference('{*}DATA-PDU-REF', self.__dataPdu)
        self.__directPdu = self._resolve_single_reference('{*}DIRECT-PDU-REF', self.__directPdu)
        self.__flowControlPdus = self._resolve_reference_list('{*}FLOW-CONTROL-PDU-REFS/*', self.__flowControlPdus)
        self.__receivers = self._resolve_reference_list('{*}RECEIVER-REFS/*', self.__receivers)
        self.__tpSdus = self._resolve_reference_list('{*}TP-SDU-REFS/*', self.__tpSdus)
        self.__transmitter = self._resolve_single_reference('{*}TRANSMITTER-REF', self.__transmitter)

