class LinTpConnection(TpConnection):
    """
    A LinTP channel represents an internal path for the transmission or reception of a Pdu via LinTp and describes the sender and the receiver of this particular communication. , , LinTp supports (per Lin Cluster) the configuration of one Rx Tp-SDU and one Tx Tp-SDU per NAD the LinMaster uses to address one or more of its Lin Slaves. To support this an arbitrary number of LinTpConnections shall be described.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'LIN-TP-CONNECTION'
        self._node = etree.Element('LIN-TP-CONNECTION')
        self.__dropNotRequestedNad = None
        self.__maxNumberOfRespPendingFrames = None
        self.__p2Max = None
        self.__p2Timing = None
        self.__timeoutAs = None
        self.__timeoutCr = None
        self.__timeoutCs = None
        self.__dataPdu = None
        self.__flowControl = None
        self.__linTpNSdu = None
        self.__multicast = None
        self.__receivers = {}
        self.__transmitter = None
        self.__variationPoint = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        self.__dropNotRequestedNad = self._read_scalar_element('DROP-NOT-REQUESTED-NAD', datatype_utils.get_bool_value)
        self.__maxNumberOfRespPendingFrames = self._read_scalar_element('MAX-NUMBER-OF-RESP-PENDING-FRAMES', datatype_utils.get_int_value)
        self.__p2Max = self._read_scalar_element('P-2-MAX', datatype_utils.get_float_value)
        self.__p2Timing = self._read_scalar_element('P-2-TIMING', datatype_utils.get_float_value)
        self.__timeoutAs = self._read_scalar_element('TIMEOUT-AS', datatype_utils.get_float_value)
        self.__timeoutCr = self._read_scalar_element('TIMEOUT-CR', datatype_utils.get_float_value)
        self.__timeoutCs = self._read_scalar_element('TIMEOUT-CS', datatype_utils.get_float_value)

        self.__variationPoint = self._build_single_child('{*}VARIATION-POINT', VariationPoint, file, 'variationPoint')
        return self

    def _resolve_references(self):
        super()._resolve_references()
        self.__dataPdu = self._resolve_single_reference('{*}DATA-PDU-REF', self.__dataPdu)
        self.__flowControl = self._resolve_single_reference('{*}FLOW-CONTROL-REF', self.__flowControl)
        self.__linTpNSdu = self._resolve_single_reference('{*}LIN-TP-N-SDU-REF', self.__linTpNSdu)
        self.__multicast = self._resolve_single_reference('{*}MULTICAST-REF', self.__multicast)
        self.__receivers = self._resolve_reference_list('{*}RECEIVER-REFS/*', self.__receivers)
        self.__transmitter = self._resolve_single_reference('{*}TRANSMITTER-REF', self.__transmitter)

