class TransformationTechnology(Identifiable):
    """
    A TransformationTechnology is a transformer inside a transformer chain.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'TRANSFORMATION-TECHNOLOGY'
        self._node = etree.Element('TRANSFORMATION-TECHNOLOGY')
        self.__hasInternalState = None
        self.__needsOriginalData = None
        self.__protocol = None
        self.__transformerClass = None
        self.__version = None
        self.__bufferProperties = None
        self.__transformationDescriptions = {}
        self.__variationPoint = None
        self.__transformationDescriptions_childTypes = {'SOMEIP-TRANSFORMATION-DESCRIPTION': 'SOMEIPTransformationDescription', 'USER-DEFINED-TRANSFORMATION-DESCRIPTION': 'UserDefinedTransformationDescription', 'END-TO-END-TRANSFORMATION-DESCRIPTION': 'EndToEndTransformationDescription', }

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        self.__hasInternalState = self._read_scalar_element('HAS-INTERNAL-STATE', datatype_utils.get_bool_value)
        self.__needsOriginalData = self._read_scalar_element('NEEDS-ORIGINAL-DATA', datatype_utils.get_bool_value)
        self.__protocol = self._read_scalar_element('PROTOCOL', datatype_utils.get_string_value)
        self.__transformerClass = self._read_scalar_element('TRANSFORMER-CLASS', TransformerClassEnum.get)
        self.__version = self._read_scalar_element('VERSION', datatype_utils.get_string_value)

        refCounter = 0
        self.__bufferProperties = self._build_single_child('{*}BUFFER-PROPERTIES', BufferProperties, file, 'bufferProperties')
        refCounter = self._build_child_collection(self.__transformationDescriptions, '{*}TRANSFORMATION-DESCRIPTIONS/*', self.__transformationDescriptions_childTypes, file, 'transformationDescriptions', refCounter)
