class DocumentElementScope(SpecElementScope):
    """
    Specifies if a specification element such as a requirement, specification, deliverable, artifact, task definition or activity is in scope of this data exchange point. The DocumentElementScope may reference all specification elements that have a name or ID. The only exception are Meta Classes, Meta Attribute and constraints which are handled in the Data Format Tailoring section of the Profile of Data Exchange Point., , Elements of Autosar specification documents are referenced via their ID (requirement, specification items) or name (deliverable, artifact, task definition or activity)
    """
    def __init__(self):
        super().__init__()
        self.tag = 'DOCUMENT-ELEMENT-SCOPE'
        self._node = etree.Element('DOCUMENT-ELEMENT-SCOPE')
        self.__customDocumentElement = None
        self.__tailorings = {}


    def _resolve_references(self):
        super()._resolve_references()
        self.__customDocumentElement = self._resolve_single_reference('{*}CUSTOM-DOCUMENT-ELEMENT-REF', self.__customDocumentElement)
        self.__tailorings = self._resolve_reference_list('{*}TAILORING-REFS/*', self.__tailorings)

    def get_customDocumentElement(self) -> Traceable:
        return self.__customDocumentElement

    def set_customDocumentElement(self, value: Traceable) -> None:
        """
        Adds a single value to the customDocumentElement
        """
        if value is not None:
            if isinstance(value, Traceable) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of Traceable or its sub-classes'.format(value))
            if self.__customDocumentElement is not None and self.__customDocumentElement.is_proxy() is False:
                self.__customDocumentElement.referenced_by.remove(self)
            self.__customDocumentElement = value
            value.referenced_by.add(self)
        elif self.__customDocumentElement is not None:
            if self.__customDocumentElement.is_proxy() is False:
                self.__customDocumentElement.referenced_by.remove(self)
            self.__customDocumentElement = None
        XDT.mark_dirty(self.__customDocumentElement, self)

    def get_tailorings(self) -> list[DataFormatElementReference]:
        return list(self.__tailorings.keys())

    def __bind_tailoring(self, value: DataFormatElementReference) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__tailorings.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, DataFormatElementReference) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of DataFormatElementReference or its sub-classes'.format(value))

        value.referenced_by.add(self)
        XDT.mark_dirty(value, self)


    def add_tailoring(self, value: DataFormatElementReference) -> None:
        """
        Adds a single value to the tailorings
        """
        if value is not None:
            self.__bind_tailoring(value)
            self.__tailorings[value] = None

    def set_tailorings(self, values: list[DataFormatElementReference]) -> None:
        """
        Adds a list of ref value to the tailorings
        """
        for value in values:
            self.add_tailoring(value)

    def remove_tailoring(self, value: DataFormatElementReference) -> None:
        """
        Removes a single value from tailorings
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            self.__tailorings.pop(value)
            if value.is_proxy() is False:
                value.referenced_by.remove(self)

    def remove_tailorings(self, values: list[DataFormatElementReference]) -> None:
        """
        Removes a list of value from tailorings
        """
        for value in values:
            self.remove_tailoring(value)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['CustomDocumentElement'] = self.__customDocumentElement
        property_values['Tailorings'] = self.__tailorings
        return property_values


    def _save_contents(self):
        """
        Saves the content of DocumentElementScope node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_SpecElementScope()
        self._save_single_reference('CUSTOM-DOCUMENT-ELEMENT-REF', self.__customDocumentElement, self._insert_after_tags + ['IN-SCOPE', 'ALTERNATIVE-NAME', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])
        self._save_reference_list('TAILORING-REFS', 'TAILORING-REF', self.__tailorings, self._insert_after_tags + ['CUSTOM-DOCUMENT-ELEMENT-REF', 'IN-SCOPE', 'ALTERNATIVE-NAME', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])

