class AggregationTailoring(AttributeTailoring):
    """
    Tailoring of aggregations in the AUTOSAR meta-model
    """
    def __init__(self):
        super().__init__()
        self.tag = 'AGGREGATION-TAILORING'
        self._node = etree.Element('AGGREGATION-TAILORING')
        self.__typeTailorings = {}
        self.__typeTailorings_childTypes = {'ABSTRACT-CLASS-TAILORING': 'AbstractClassTailoring', 'CONCRETE-CLASS-TAILORING': 'ConcreteClassTailoring', }

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)

        refCounter = 0
        refCounter = self._build_child_collection(self.__typeTailorings, '{*}TYPE-TAILORINGS/*', self.__typeTailorings_childTypes, file, 'typeTailorings', refCounter)
        return self

    def get_typeTailorings(self) -> list[ClassTailoring]:
        return list(self.__typeTailorings.keys())

    def __bind_typeTailoring(self, value: ClassTailoring) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__typeTailorings.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, ClassTailoring) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of ClassTailoring or its sub-classes'.format(value))

        value._detach_from_parent()
        value._parent = self #set parent
        value.file = self.file
        if value.name is not None:
            value._refresh_paths()
        else:
            value._build_path(elementNameIfShortNameMissing = 'ClassTailoring_@' + str(len(self.get_children()))) #updates the path
        XDT.mark_dirty(value, self, attributesToMakeDirty = ['timestamp', 'checksum'])

    def add_typeTailoring_at_index(self, index: int, value: ClassTailoring) -> None:
        """
        Adds a single value to the typeTailorings at the given index
        """
        if value is not None:
            self.__bind_typeTailoring(value)
            AutosarNode._insert_at_index(self.__typeTailorings, value, index)
            self._sync_add_to_merge_target(value)

    def add_typeTailoring(self, value: ClassTailoring) -> None:
        """
        Adds a single value to the typeTailorings
        """
        if value is not None:
            self.__bind_typeTailoring(value)
            self.__typeTailorings[value] = None
            self._sync_add_to_merge_target(value)

    def set_typeTailorings(self, values: list[ClassTailoring]) -> None:
        """
        Adds a list of ref value to the typeTailorings
        """
        for value in values:
            self.add_typeTailoring(value)

    def remove_typeTailoring(self, value: ClassTailoring) -> None:
        """
        Removes a single value from typeTailorings
        """
