class PrimitiveAttributeCondition(AttributeCondition,AbstractValueRestriction):
    """
    The PrimitiveAttributeCondition evaluates to true, if the referenced primitive attribute is accepted by all rules of this condition.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'PRIMITIVE-ATTRIBUTE-CONDITION'
        self._node = etree.Element('PRIMITIVE-ATTRIBUTE-CONDITION')
        self.__attribute = None


    def _resolve_references(self):
        super()._resolve_references()
        self.__attribute = self._resolve_single_reference('{*}ATTRIBUTE-REF', self.__attribute)

    def get_attribute(self) -> PrimitiveAttributeTailoring:
        return self.__attribute

    def set_attribute(self, value: PrimitiveAttributeTailoring) -> None:
        """
        Adds a single value to the attribute
        """
        if value is not None:
            if isinstance(value, PrimitiveAttributeTailoring) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of PrimitiveAttributeTailoring or its sub-classes'.format(value))
            if self.__attribute is not None and self.__attribute.is_proxy() is False:
                self.__attribute.referenced_by.remove(self)
            self.__attribute = value
            value.referenced_by.add(self)
        elif self.__attribute is not None:
            if self.__attribute.is_proxy() is False:
                self.__attribute.referenced_by.remove(self)
            self.__attribute = None
        XDT.mark_dirty(self.__attribute, self)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['Attribute'] = self.__attribute
        return property_values


    def _save_contents(self):
        """
        Saves the content of PrimitiveAttributeCondition node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_AttributeCondition()
        super()._save_AbstractValueRestriction()
        self._save_single_reference('ATTRIBUTE-REF', self.__attribute, self._insert_after_tags + ['PATTERN', 'MIN-LENGTH', 'MIN', 'MAX-LENGTH', 'MAX', 'UPPER-MULTIPLICITY-INFINITE', 'UPPER-MULTIPLICITY', 'LOWER-MULTIPLICITY', 'T', 'S'])

