class FMAttributeValue(ARObject):
    """
    This defines a value for the attribute that is referred to in the role definition.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'FM-ATTRIBUTE-VALUE'
        self._node = etree.Element('FM-ATTRIBUTE-VALUE')
        self.__value = None
        self.__definition = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)
        self.__value = self._read_scalar_element('VALUE', datatype_utils.get_string_value)

        return self

    def _resolve_references(self):
        super()._resolve_references()
        self.__definition = self._resolve_single_reference('{*}DEFINITION-REF', self.__definition)

    def get_value(self) -> str:
        return self.__value

    def set_value(self, value: str) -> None:
        self.__value = value
        XDT.mark_attribute_dirty('value', self)

    def get_definition(self) -> FMAttributeDef:
        return self.__definition

    def set_definition(self, value: FMAttributeDef) -> None:
        """
        Adds a single value to the definition
        """
        if value is not None:
            if isinstance(value, FMAttributeDef) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of FMAttributeDef or its sub-classes'.format(value))
            if self.__definition is not None and self.__definition.is_proxy() is False:
                self.__definition.referenced_by.remove(self)
            self.__definition = value
            value.referenced_by.add(self)
        elif self.__definition is not None:
            if self.__definition.is_proxy() is False:
                self.__definition.referenced_by.remove(self)
            self.__definition = None
        XDT.mark_dirty(self.__definition, self)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        property_values['Value'] = self.__value
        property_values['Definition'] = self.__definition
        return property_values


    def _save_contents(self):
        """
        Saves the content of FMAttributeValue node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_ARObject()
        self._save_single_reference('DEFINITION-REF', self.__definition, self._insert_after_tags + ['T', 'S'])
        self._save_scalar_element('VALUE', 'value', str(self.__value) if self.__value is not None else None, create_after_nodes = ['DEFINITION-REF', 'T', 'S'] + self._insert_after_tags)

class FMFormulaByFeaturesAndAttributes(FormulaExpression):
    """
    An expression that has the syntax of the AUTOSAR formula language but uses only references to features or feature attributes (not system constants) as operands.
    """
    def __init__(self):
        super().__init__()
        self.__attributes = {}
        self.__features = {}

        self.__mixedtext = None


    def _resolve_references(self):
        super()._resolve_references()
        self.__attributes = self._resolve_reference_list('{*}ATTRIBUTE-REF', self.__attributes)
        self.__features = self._resolve_reference_list('{*}FEATURE-REF', self.__features)

    def get_attributes(self) -> list[FMAttributeDef]:
        return list(self.__attributes.keys())

    def __bind_attribute(self, value: FMAttributeDef) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__attributes.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, FMAttributeDef) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of FMAttributeDef or its sub-classes'.format(value))

        value.referenced_by.add(self)
        XDT.mark_dirty(value, self)


    def add_attribute(self, value: FMAttributeDef) -> None:
        """
        Adds a single value to the attributes
        """
        if value is not None:
            self.__bind_attribute(value)
            self.__attributes[value] = None

    def set_attributes(self, values: list[FMAttributeDef]) -> None:
        """
        Adds a list of ref value to the attributes
        """
        for value in values:
            self.add_attribute(value)

    def remove_attribute(self, value: FMAttributeDef) -> None:
        """
        Removes a single value from attributes
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            self.__attributes.pop(value)
            if value.is_proxy() is False:
                value.referenced_by.remove(self)

    def remove_attributes(self, values: list[FMAttributeDef]) -> None:
        """
        Removes a list of value from attributes
        """
        for value in values:
            self.remove_attribute(value)

    def get_features(self) -> list[FMFeature]:
        return list(self.__features.keys())

