class AdaptiveSwcInternalBehavior(Identifiable):
    """
    This meta-class represents the ability to define an internal behavior of an AtomicSwComponentType used on the AUTOSAR adaptive platform. , , Please note that the model of internal behavior in this case, in stark contrast to the situation of the AUTOSAR classic platform, is very minimal.
    """
    def __init__(self):
        super().__init__()
        self.tag = 'ADAPTIVE-SWC-INTERNAL-BEHAVIOR'
        self._node = etree.Element('ADAPTIVE-SWC-INTERNAL-BEHAVIOR')
        self.__serviceDependencies = {}
        self.__variationPoint = None

    def _build(self, parent, node, file, elementNameIfShortNameMissing = None):
        super()._build(parent, node, file, elementNameIfShortNameMissing)

        refCounter = 0
        refCounter = self._build_child_collection(self.__serviceDependencies, '{*}SERVICE-DEPENDENCYS/*', SwcServiceDependency, file, 'serviceDependencies', refCounter)
        self.__variationPoint = self._build_single_child('{*}VARIATION-POINT', VariationPoint, file, 'variationPoint')
        return self

    def get_serviceDependencies(self) -> list[SwcServiceDependency]:
        return list(self.__serviceDependencies.keys())

    def __bind_serviceDependencie(self, value: SwcServiceDependency) -> None:
        if isinstance(value, Referrable) and any(v.name == value.name for v in self.__serviceDependencies.keys()):
            raise InvalidRefOrChildNodeException('Operation not possible. A node with name {} already present in {}.'.format(value.name, self))
        if isinstance(value, SwcServiceDependency) is False:
            raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of SwcServiceDependency or its sub-classes'.format(value))

        value._detach_from_parent()
        value._parent = self #set parent
        value.file = self.file
        if value.name is not None:
            value._refresh_paths()
        else:
            value._build_path(elementNameIfShortNameMissing = 'SwcServiceDependency_@' + str(len(self.get_children()))) #updates the path
        XDT.mark_dirty(value, self, attributesToMakeDirty = ['uuid', 'category', 'shortName', 'timestamp', 'checksum'])

    def add_serviceDependencie_at_index(self, index: int, value: SwcServiceDependency) -> None:
        """
        Adds a single value to the serviceDependencies at the given index
        """
        if value is not None:
            self.__bind_serviceDependencie(value)
            AutosarNode._insert_at_index(self.__serviceDependencies, value, index)
            self._sync_add_to_merge_target(value)

    def add_serviceDependencie(self, value: SwcServiceDependency) -> None:
        """
        Adds a single value to the serviceDependencies
        """
        if value is not None:
            self.__bind_serviceDependencie(value)
            self.__serviceDependencies[value] = None
            self._sync_add_to_merge_target(value)

    def set_serviceDependencies(self, values: list[SwcServiceDependency]) -> None:
        """
        Adds a list of ref value to the serviceDependencies
        """
        for value in values:
            self.add_serviceDependencie(value)

    def remove_serviceDependencie(self, value: SwcServiceDependency) -> None:
        """
        Removes a single value from serviceDependencies
        """
        if value is not None:
            XDT.mark_dirty(value, self)
            value._detach_from_parent()
            value._parent = None #No parent
            value._refresh_paths() #resets the path
            if value._node.getparent() is not None:
                value._node.getparent().remove(value._node)

    def remove_serviceDependencies(self, values: list[SwcServiceDependency]) -> None:
        """
        Removes a list of value from serviceDependencies
        """
        for value in values:
            self.remove_serviceDependencie(value)

    def get_variationPoint(self) -> VariationPoint:
        return self.__variationPoint

    def set_variationPoint(self, value: VariationPoint) -> None:
        """
        Adds a single value to the variationPoint
        """
        if value is not None:
            if isinstance(value, VariationPoint) is False:
                raise InvalidRefOrChildNodeException('Operation not possible. {} should be an instance of VariationPoint or its sub-classes'.format(value))

            value._detach_from_parent()
            self.__variationPoint = value
            value.file = self.file
            value._parent = self #set parent
            if value.name is not None:
                value._refresh_paths()
            else:
                value._build_path(elementNameIfShortNameMissing = 'VariationPoint_@' + str(len(self.get_children()))) #updates the path
            self._sync_add_to_merge_target(value)
        elif self.__variationPoint is not None:
            self.__variationPoint._detach_from_parent()
            self.__variationPoint = None
        XDT.mark_dirty(self.__variationPoint, self)

    def new_VariationPoint(self, name: str=None) -> VariationPoint:
        """
        Creates a new VariationPoint under the AdaptiveSwcInternalBehavior.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        VariationPoint_obj = VariationPoint()
        if isinstance(VariationPoint_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        VariationPoint_obj.name = name if isinstance(VariationPoint_obj, Referrable) else None
        self.set_variationPoint(VariationPoint_obj)
        if isinstance(VariationPoint_obj, Referrable):
            VariationPoint_obj.set_shortName(name)
        return VariationPoint_obj

    def new_ServiceDependencie(self, name: str=None) -> SwcServiceDependency:
        """
        Creates a new SwcServiceDependency under the AdaptiveSwcInternalBehavior.
        Raises exception:
                       - if name is not provided for a Referrable type
                       - if child with same name exists under the current node
        """
        SwcServiceDependency_obj = SwcServiceDependency()
        if isinstance(SwcServiceDependency_obj, Referrable) and name is None:
            raise NoShortNameException('name should not be None for Referrable objects')
        SwcServiceDependency_obj.name = name if isinstance(SwcServiceDependency_obj, Referrable) else None
        self.add_serviceDependencie(SwcServiceDependency_obj)
        if isinstance(SwcServiceDependency_obj, Referrable):
            SwcServiceDependency_obj.set_shortName(name)
        return SwcServiceDependency_obj

    def get_children(self) -> list[AutosarNode]:
        children = super().get_children()
        children.extend(self.__serviceDependencies)
        if self.__variationPoint is not None:
            children.append(self.__variationPoint)
        return children

    def _containment_slot_of(self, child: AutosarNode) -> str | None:
        if child in self.__serviceDependencies:
            return 'serviceDependencies'
        if self.__variationPoint is child:
            return 'variationPoint'
        return super()._containment_slot_of(child)

    def add_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'serviceDependencies':
            self.__serviceDependencies[child] = None
        elif containment_slot == 'variationPoint':
            if self.__variationPoint is None:
                self.__variationPoint = child
        else:
            super().add_child(child, containment_slot)

    def remove_child(self, child: AutosarNode, containment_slot: str) -> None:
        if child is None:
            return
        if containment_slot == 'serviceDependencies':
            self.__serviceDependencies.pop(child, None)
        elif containment_slot == 'variationPoint':
            if self.__variationPoint is child:
                self.__variationPoint = None
        else:
            super().remove_child(child, containment_slot)


    def get_property_values(self) -> dict[str, Any]:
        property_values = super().get_property_values()
        return property_values

    def is_atp_splitable(self) -> bool:
        return True

    def _save_contents(self):
        """
        Saves the content of AdaptiveSwcInternalBehavior node
        """
        if XDT.is_dirty(self) is False:
            return
        super()._save_Identifiable()
        self._save_child_collection('SERVICE-DEPENDENCYS', None, self.__serviceDependencies, self._insert_after_tags + ['UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])
        self._save_single_child('VARIATION-POINT', self.__variationPoint, self._insert_after_tags + ['SERVICE-DEPENDENCYS', 'UUID', 'ANNOTATIONS', 'INTRODUCTION', 'ADMIN-DATA', 'CATEGORY', 'DESC', 'LONG-NAME', 'SHORT-NAME-FRAGMENTS', 'SHORT-NAME', 'T', 'S'])

